window.EVENTS_C=[{"id":"C-001","branch":"C","stage":1,"day":1,"shichen":"辰时","checkpoint":"及笄礼晨起梳妆","scene":"元符三年秋，今日你及笄。天未亮，母亲就捧着木笄进来：「闺女，坐好。」","options":[{"text":"乖乖坐好让母亲绾发","correct":true,"tags":["规矩","家世"],"dims":{"家世":2},"feedback":"母亲手很稳：「绾了发，就是大人了。」","source":"笄礼为女子成人重礼，时辰有定，见《仪礼》士昏礼之义。"},{"text":"嚷着再睡半个时辰","correct":false,"tags":["现代思维"],"dims":{"自主":1},"feedback":"母亲沉了脸：「笄礼赖床，传出去像什么话。」","source":"笄礼三加有序，见《仪礼》士昏礼贾疏。"}],"difficulty":1,"npc":["母亲"],"foreshadow":null},{"id":"C-001-未","branch":"C","stage":1,"day":1,"shichen":"未时","checkpoint":"笄礼三加之序","scene":"宾客观礼。正宾为你一加木笄，再加发钗，三加钗冠。你跪坐着，背挺得笔直。","options":[{"text":"依礼三次跪拜答礼","correct":true,"tags":["规矩","家世"],"dims":{"家世":2},"feedback":"正宾赞道：「李家有女，礼数周全。」父亲在旁微微颔首。","source":"《仪礼·士昏礼》：笄礼三加，每加皆有拜答。"},{"text":"嫌烦只跪一次就算","correct":false,"tags":["现代思维"],"dims":{"自主":1},"feedback":"席间有老夫人摇头低语。母亲的脸色不太好看。","source":"笄礼三加三拜，缺一即为失仪，见《仪礼》注疏。"}],"difficulty":1,"npc":["母亲","正宾"],"foreshadow":null},{"id":"C-001-戌","branch":"C","stage":1,"day":1,"shichen":"戌时","checkpoint":"及笄夜父女对话","scene":"夜里父亲把你叫到书房，案上摊着你幼时写的字：「笄了。往后待人接物，可有计较？」","options":[{"text":"「诗书礼乐，女儿都想学」","correct":true,"tags":["学习","才华"],"dims":{"才华":2},"feedback":"父亲笑了：「不愧是我李格非的女儿。」","source":"李家乃文章世家，父以文名世，见《金石录后序》记家学。"},{"text":"「学着怎么当个好媳妇」","correct":true,"tags":["规矩"],"dims":{"家世":1},"feedback":"父亲点头，又有些怅然：「也好。只是别丢了笔墨。」","source":"宋代士族女子既习女红亦重翰墨，见《东京梦华录》序。"}],"difficulty":1,"npc":["父亲李格非"],"foreshadow":"父亲看重她的笔墨","flavor":true},{"id":"C-002","branch":"C","stage":1,"day":2,"shichen":"辰时","checkpoint":"媒人初上门","scene":"及笄第二天，全汴京最有名的王媒婆就上门了，笑得满脸褶子：「给姑娘道喜！」","options":[{"text":"随母亲正厅见客，垂手听","correct":true,"tags":["规矩","家世"],"dims":{"家世":2},"feedback":"王媒婆夸你「端庄」，母亲脸上有光。","source":"宋代议婚，当事女子回避为常礼，见《仪礼》男女之别。"},{"text":"躲去屏风后偷听","correct":false,"tags":["现代思维"],"dims":{"自主":1},"feedback":"母亲回头瞥见裙角，事后数落你：「没规矩。」","source":"闺秀窥听外事失仪，见《仪礼》内外之别。"}],"difficulty":1,"npc":["王媒婆","母亲"],"foreshadow":null},{"id":"C-002-未","branch":"C","stage":1,"day":2,"shichen":"未时","checkpoint":"媒人的话术","scene":"王媒婆喝着茶，夸一家「城南张员外家，田产三百亩」，又夸一家「赵太丞家，公子在太学念书」。","options":[{"text":"记下两家底细，先不作声","correct":true,"tags":["谨慎","家世"],"dims":{"家世":1,"自主":1},"feedback":"你听出她夸大其词——媒人的话，七分水分。","source":"宋代议婚由父母媒妁主导，见《仪礼》士昏礼。"},{"text":"当场问「公子人品如何」","correct":false,"tags":["现代思维"],"dims":{"自主":1},"feedback":"母亲咳嗽一声瞪你。姑娘家自己开口问夫婿，失礼。","source":"女子自询夫婿为失仪，见《仪礼》士昏礼婚义。"}],"difficulty":1,"npc":["王媒婆"],"foreshadow":"赵太丞家公子在太学"},{"id":"C-002-戌","branch":"C","stage":1,"day":2,"shichen":"戌时","checkpoint":"灯下抄书","scene":"夜里你照旧坐到灯下，白日的事扰得你静不下心。案上是没抄完的《汉书》。","options":[{"text":"定神抄完今日功课","correct":true,"tags":["才华","学习"],"dims":{"才华":2},"feedback":"笔尖入纸，心就静了。议婚是议婚，书是书。","source":"宋代士族闺秀抄书为常课，见《金石录后序》自述。"},{"text":"搁笔去打听赵家的事","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"你叫丫鬟去灶房闲扯，听了一耳朵「赵公子品学兼优」。","source":"汴京人家借仆妇传话探听亲事，见《东京梦华录》记娶妇媒妁。"}],"difficulty":1,"npc":["丫鬟小翠"],"foreshadow":"她留意起赵家","flavor":true},{"id":"C-003","branch":"C","stage":1,"day":3,"shichen":"辰时","checkpoint":"父亲考校诗书","scene":"早饭毕，父亲随手指着院里梧桐：「以秋桐为题，赋两句。」","options":[{"text":"吟「新桐引秋意」","correct":true,"tags":["才华"],"dims":{"才华":2,"名声":1},"feedback":"父亲捋须：「清而不弱。署个日子收进你的诗箧。」","source":"家学以诗课女，见《金石录后序》记闺门家学。"},{"text":"说「女子无才便是德」","correct":false,"tags":["现代思维"],"dims":{"家世":1},"feedback":"父亲皱眉：「胡说。那是愚夫愚妇的话。」","source":"北宋士族教女重才德，见《仪礼》妇学之教。"}],"difficulty":1,"npc":["父亲李格非"],"foreshadow":null},{"id":"C-003-未","branch":"C","stage":1,"day":3,"shichen":"未时","checkpoint":"女红还是读书","scene":"母亲教你理丝线绷绣架：「诗书再好，嫁妆里的绣活不能假手于人。」","options":[{"text":"上午绣活下午读书","correct":true,"tags":["务实","家世"],"dims":{"家世":1,"才华":1},"feedback":"母亲满意：「两样都不丢，才是体面。」","source":"宋代嫁妆重绣品，士族女子亦须亲制部分，见黄昇墓出土绣品。"},{"text":"说绣活交给绣娘就行","correct":false,"tags":["现代思维"],"dims":{"自主":1},"feedback":"母亲摇头：「绣品上手帕角的名字，是要给婆家看的。」","source":"宋代新妇绣品为奁中体面，亲制为尚，见《梦粱录·嫁娶》。"}],"difficulty":1,"npc":["母亲"],"foreshadow":null},{"id":"C-003-戌","branch":"C","stage":1,"day":3,"shichen":"戌时","checkpoint":"丫鬟说媒婆八卦","scene":"小翠铺床时叽叽喳喳：「王媒婆在灶房说，张员外家的儿子斗鸡走狗，赵家公子却是个书痴。」","options":[{"text":"笑斥她别传闲话","correct":true,"tags":["规矩"],"dims":{"家世":1},"feedback":"小翠吐吐舌头。你心里却把「书痴」二字记下了。","source":"宋代闺阁戒仆妇传舌，见《仪礼》治家之义。"},{"text":"追问书痴怎么个痴法","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"「听说赵公子为了买一块古碑拓片，当了自己的新袍子。」你怔了怔。","source":"赵家公子为太学生，贫而好古，见《金石录后序》。"}],"difficulty":1,"npc":["丫鬟小翠"],"foreshadow":"赵公子当袍买碑","flavor":true},{"id":"C-004","branch":"C","stage":1,"day":4,"shichen":"辰时","checkpoint":"随母上香规矩","scene":"母亲带你去大相国寺上香还愿。出门前交代：「今日是朔望，人挤人，跟紧我。」","options":[{"text":"低眉随母亲缓行","correct":true,"tags":["规矩"],"dims":{"家世":2},"feedback":"一路妇人相看，有人夸「李家小娘子好仪态」。","source":"宋代大家闺秀出行须端谨，见《东京梦华录》记士庶游观。"},{"text":"东张西望看热闹","correct":false,"tags":["现代思维"],"dims":{"自主":1},"feedback":"母亲拽住你袖子：「寺里多少双眼睛，叫人看了去怎么议婚。」","source":"闺秀出行以仆从为卫，见《东京梦华录》记士庶出行。"}],"difficulty":1,"npc":["母亲"],"foreshadow":null},{"id":"C-004-未","branch":"C","stage":1,"day":4,"shichen":"未时","checkpoint":"相国寺书摊","scene":"上完香经过殿后书摊，一部《说文解字》旧刻摊在那儿。母亲去前殿添香油，叫你原地等。","options":[{"text":"蹲下翻两页再放回","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"摊主笑：「小娘子识货，这是蜀刻。」你记下了这个摊。","source":"相国寺万姓交易有书籍字画摊，见《东京梦华录》卷三。"},{"text":"掏钱直接买下","correct":false,"tags":["现代思维"],"dims":{"自主":1},"feedback":"你忘了自己没带钱袋，丫鬟急得直摆手——闺秀当众付钱，招摇。","source":"宋代闺秀外出，银钱由仆妇掌管，见《东京梦华录》记市井交易。"}],"difficulty":1,"npc":["书摊主"],"foreshadow":"相国寺书摊"},{"id":"C-004-戌","branch":"C","stage":1,"day":4,"shichen":"戌时","checkpoint":"夜记书摊","scene":"回家后你惦记着那部《说文解字》。父亲进门看见你写的书单，笑了。","options":[{"text":"请父亲下次替你看看","correct":true,"tags":["才华","家世"],"dims":{"才华":1,"家世":1},"feedback":"父亲一口应下：「蜀刻难得，我明日下朝去替你掌眼。」","source":"李格非雅好典籍，父女以书相得，见《金石录后序》。"},{"text":"赌气说要自己攒钱买","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"父亲挑眉：「有志气。不过你的月钱，怕要攒三年。」","source":"宋代闺秀有月例钱，数额有限，见《梦粱录》记人家日用。"}],"difficulty":1,"npc":["父亲李格非"],"foreshadow":null,"flavor":true},{"id":"C-005","branch":"C","stage":1,"day":5,"shichen":"辰时","checkpoint":"女红课","scene":"晨妆毕，母亲把一方绢子递来：「今日绣折枝梅花，针脚要藏住。」你的目光却飘向案头那卷书。","options":[{"text":"静下心把梅枝绣完","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"母亲翻看背面不见线结，点头：「这才像话。」","source":"宋代闺秀以女红为必修课，见《东京梦华录》记嫁娶备办针线。"},{"text":"草草几针便去看书","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"母亲捏起绢子一抖，线头散落：「书要读，活计也不能荒。」","source":"士大夫家闺教并重，妇功不废，见《仪礼》妇学之教。"}],"difficulty":1,"npc":["母亲"],"foreshadow":null},{"id":"C-005-未","branch":"C","stage":1,"day":5,"shichen":"未时","checkpoint":"学点茶","scene":"午后嬷嬷教你点茶。建盏里茶粉调膏，汤瓶的水声由远而近——「听汤，蟹眼过后鱼眼生。」","options":[{"text":"接过汤瓶亲自候汤","correct":true,"tags":["家世","才华"],"dims":{"家世":1,"才华":1},"feedback":"嬷嬷赞你手稳：「娘子这手，待客拿得出去。」","source":"宋人点茶候汤看水纹，蟹眼鱼眼之辨，见《东京梦华录》茶事。"},{"text":"嫌烫让嬷嬷代劳","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"嬷嬷嘴上不说，回头便学给母亲听：娘子娇气。","source":"闺秀需习茶礼待客，见《梦粱录》记人家日常茶事。"}],"difficulty":1,"npc":["嬷嬷"],"foreshadow":null},{"id":"C-005-戌","branch":"C","stage":1,"day":5,"shichen":"戌时","checkpoint":"隔帘听政","scene":"父亲在书房会客，说到朝廷新法，声音渐高。你挑灯经过，脚步不由得慢下来。","options":[{"text":"站着听完记下人名","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"你只把听到的人名官职默记在心，未置一词。","source":"士人家眷不预外事，但耳濡目染，见《续资治通鉴长编》家集常记此类。"},{"text":"掀帘进去评两句","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"客人一愣，父亲沉下脸：「女儿家，回房去。」","source":"宋代闺秀不预外议，失礼则累家声，见《仪礼》内外之别。"}],"difficulty":2,"npc":["父亲","客人"],"foreshadow":null},{"id":"C-006","branch":"C","stage":1,"day":6,"shichen":"辰时","checkpoint":"溪亭旧梦","scene":"晨起小坐，忽想起去年夏日与女伴泛舟溪亭，藕花深处惊起一滩鸥鹭——「常记溪亭日暮，沉醉不知归路」。","options":[{"text":"把这帧记忆写进小笺","correct":true,"tags":["才华"],"dims":{"才华":2,"自主":1},"feedback":"你提笔写下数行，自己读了又读，不觉莞尔。","source":"宋人好以词记游，闺阁尤多清句，见《琅嬛记》记闺中词事。"},{"text":"说与丫鬟笑一场便罢","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"丫鬟听得眼亮：「娘子再说一遍，我记着。」","source":"闺中嬉戏游赏，见《武林旧事》记都人游湖之盛。"}],"difficulty":1,"npc":["丫鬟"],"foreshadow":"溪亭词句","flavor":true,"yishou":true},{"id":"C-006-未","branch":"C","stage":1,"day":6,"shichen":"未时","checkpoint":"斗草会","scene":"午后几位闺伴来访，约在园中斗草。有人采了「观音柳」，有人寻得「罗汉松」，轮到你出手。","options":[{"text":"以对仗草名压场","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"你亮出「君子竹」对「美人蕉」，满座叫好。","source":"斗草以对仗为胜，端午前后最盛，见《东京梦华录》记端午斗草。"},{"text":"摘了邻家一枝名花","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"花是好花，可摘花的手被邻家婆子瞧见了。","source":"斗草以草不以花，逾墙摘花失仪，见《梦粱录》记端午习俗。"}],"difficulty":1,"npc":["闺伴"],"foreshadow":null},{"id":"C-006-戌","branch":"C","stage":1,"day":6,"shichen":"戌时","checkpoint":"晚课临帖","scene":"晚课临《兰亭》。父亲踱进来，看你执笔：「腕要悬，指要活。字如其人，软塌塌的可不行。」","options":[{"text":"照他说的悬腕重写","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"写到第三张，父亲微微点头，把那张留下了。","source":"李格非工文善书，课女甚严，见《金石录后序》记家学。"},{"text":"描红糊弄一页交差","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"父亲一眼看穿：「描的也是字？重临十行。」","source":"宋士大夫家教严，课业不恕，见《仪礼》家塾之教。"}],"difficulty":1,"npc":["父亲"],"foreshadow":null},{"id":"C-007","branch":"C","stage":1,"day":7,"shichen":"辰时","checkpoint":"庚帖上门","scene":"王媒婆又来了，袖子里揣着红纸庚帖。母亲留你同坐，低声讲：「问名之后是纳吉，六礼一步错不得。」","options":[{"text":"听完问一句三代名讳","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"王媒婆笑道：「娘子问得在行，这才是正经人家规矩。」","source":"问名即问女方名氏生辰，兼叙三代，见《仪礼》婚义六礼。"},{"text":"抢过庚帖看生辰","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"母亲按住你的手：「哪有姑娘家自己拆庚帖的。」","source":"庚帖由家长收受，闺秀不得自启，见《宋会要辑稿》婚礼仪注。"}],"difficulty":2,"npc":["母亲","王媒婆"],"foreshadow":"庚帖规矩"},{"id":"C-007-未","branch":"C","stage":1,"day":7,"shichen":"未时","checkpoint":"乳母私语","scene":"乳母在张员外家做过针线，晌午凑过来：「那家的底细，娘子想听哪样？」","options":[{"text":"问他家待下人如何","correct":true,"tags":["自主","家世"],"dims":{"自主":1,"家世":1},"feedback":"乳母点头：「问得巧。待下人刻薄的人家，待媳妇也刻薄。」","source":"宋人议亲重家风门风，见《东京梦华录》记娶妇先观门第家风。"},{"text":"只问聘财有多少","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"乳母讪笑：「娘子这话传出去，人家要说眼皮子浅。」","source":"议亲先问财为人所轻，见《宋会要辑稿》戒争财婚。"}],"difficulty":2,"npc":["乳母"],"foreshadow":"张家底细"},{"id":"C-007-戌","branch":"C","stage":1,"day":7,"shichen":"戌时","checkpoint":"剪烛夜话","scene":"夜里母亲来你房中剪烛。说起自己当年出阁，她指尖绕着帕子：「那会儿我比你现在还小半岁。」","options":[{"text":"问母亲可曾有过不甘","correct":true,"tags":["情缘","自主","感情"],"dims":{"情缘":1,"自主":1},"feedback":"母亲怔了怔，笑道：「傻话。」可她半天没再开口。","source":"宋代母女夜话多诉婚嫁心事，见《琅嬛记》闺阁琐记。"},{"text":"说女儿不嫁也养得活","correct":false,"tags":["自主","感情"],"dims":{"自主":2},"feedback":"母亲吹了灯：「浑说。女子无夫家，立身如浮萍。」","source":"宋代女子以夫家为归宿，见《宋刑统》户婚律之义。"}],"difficulty":2,"npc":["母亲"],"foreshadow":null},{"id":"C-008","branch":"C","stage":1,"day":8,"shichen":"辰时","checkpoint":"备兰汤","scene":"上巳将近，家里采兰煮汤。嬷嬷教你把兰草佩在襟前：「三月三，祓禊去晦，姑娘家最要紧。」","options":[{"text":"跟着学佩兰之礼","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"兰香沾襟，嬷嬷满意：「明日出门就这样打扮。」","source":"上巳祓禊佩兰，见《梦粱录》记三月上巳风俗。"},{"text":"嫌味道冲悄悄摘掉","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"嬷嬷闻出味不对：「兰草呢？这可是禳灾的。」","source":"佩兰为祓禊正仪，见《武林旧事》记上巳事。"}],"difficulty":1,"npc":["嬷嬷"],"foreshadow":"上巳出行"},{"id":"C-008-未","branch":"C","stage":1,"day":8,"shichen":"未时","checkpoint":"族兄考书","scene":"在太学读书的族兄回家省亲，饭后考你《论语》：「『知者不惑』，下一句？」","options":[{"text":"接上并反问他一典","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"族兄大笑：「好！我们李家的女儿，不让须眉。」","source":"太学诸生以经义相难，见《续资治通鉴长编》记太学课试。"},{"text":"背错了还要强辩","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"族兄摇头：「背错不打紧，嘴硬可要不得。」","source":"士人家以谦逊为德，见《仪礼》记少者事长之礼。"}],"difficulty":2,"npc":["族兄"],"foreshadow":null},{"id":"C-008-戌","branch":"C","stage":1,"day":8,"shichen":"戌时","checkpoint":"灯下词卷","scene":"灯下你读一册手抄的小词，正入神，母亲掀帘进来：「读的什么，这样入迷？」","options":[{"text":"大方与母亲论词","correct":true,"tags":["才华","情缘"],"dims":{"才华":1,"情缘":1},"feedback":"母亲翻了两页：「情辞是好，只是别学太痴。」","source":"宋闺阁多喜小词，见《琅嬛记》记闺中传抄词卷。"},{"text":"藏起说在读《女诫》","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"母亲瞥见笺角的花押，叹气：「藏什么，我又不是外人。」","source":"闺中读词多避长辈，见《琅嬛记》。"}],"difficulty":1,"npc":["母亲"],"foreshadow":"词卷"},{"id":"C-009","branch":"C","stage":1,"day":9,"shichen":"辰时","checkpoint":"官媒登门","scene":"城南衙内家遣官媒来「看看姑娘」。母亲一早便有些乱，嘱咐你：「今日晨妆比平日再仔细些。」","options":[{"text":"如常晨妆不卑不亢","correct":true,"tags":["家世","名声"],"dims":{"家世":1,"名声":1},"feedback":"官媒看在眼里，回话时赞了句「端凝有度」。","source":"相媳妇重仪态举止，见《东京梦华录》记娶妇相看之俗。"},{"text":"躲到屏风后偷看","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"屏风缝隙被人瞧见了裙角，官媒笑得意味深长。","source":"闺秀避见外客为礼，见《仪礼》男女之别。"}],"difficulty":2,"npc":["官媒","母亲"],"foreshadow":"衙内提亲"},{"id":"C-009-未","branch":"C","stage":1,"day":9,"shichen":"未时","checkpoint":"官媒试诗","scene":"茶过三巡，官媒笑吟吟道：「听闻娘子能诗。老身出一句——『春风又到梁王苑』。」","options":[{"text":"对句工整且谦退","correct":true,"tags":["才华","名声"],"dims":{"才华":1,"名声":1},"feedback":"官媒记下你的对句，说这家公子必爱这个。","source":"媒人传话多考闺秀才名，见《梦粱录》记嫁娶先询才德。"},{"text":"卖弄连用三个典故","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"官媒赔笑听着，出门便说：「才太盛，怕是难降伏。」","source":"议亲忌锋芒过露，见《宋会要辑稿》婚礼议德。"}],"difficulty":3,"npc":["官媒"],"foreshadow":null},{"id":"C-009-戌","branch":"C","stage":1,"day":9,"shichen":"戌时","checkpoint":"父亲之忧","scene":"晚间父亲把你叫去：「衙内家权势煊赫，可他家长子，名声不大好。你怎么看？」","options":[{"text":"先宽慰父亲再细问","correct":true,"tags":["家世","自主"],"dims":{"家世":1,"自主":1},"feedback":"父亲脸色稍缓：「你肯用心想，就好。」","source":"婚配由父家长定夺，子女进言以婉为得体，见《仪礼》。"},{"text":"当即哭闹说不嫁","correct":false,"tags":["自主"],"dims":{"自主":2},"feedback":"父亲拍案：「婚姻大事，岂容你使性子！」","source":"父母之命不可公然违逆，见《宋刑统》户婚律。"}],"difficulty":2,"npc":["父亲"],"foreshadow":"拒婚伏笔"},{"id":"C-010","branch":"C","stage":1,"day":10,"shichen":"辰时","checkpoint":"小词传抄","scene":"闺伴捎来消息：你那几行小笺被她家女眷传抄，连她父亲看了都问「这是谁家女儿写的」。","options":[{"text":"羞喜之下再写一阕","correct":true,"tags":["才华"],"dims":{"才华":2,"名声":1},"feedback":"你提笔又成数行，自己心里也有点儿得意。","source":"宋闺秀词名多由闺伴传抄而起，见《琅嬛记》。"},{"text":"急令把笺子都收回","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"闺伴为难：「早抄走了，哪里收得回来。」","source":"闺阁文字流出难禁，见《琅嬛记》记闺词外传。"}],"difficulty":1,"npc":["闺伴"],"foreshadow":"词名渐起"},{"id":"C-010-未","branch":"C","stage":1,"day":10,"shichen":"未时","checkpoint":"母亲之忧","scene":"母亲听闻你的词句在外传抄，眉头不展：「女子才名太盛，未必是福。」","options":[{"text":"答应母亲往后收敛","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"母亲这才展眉：「藏着点儿，对你只有好。」","source":"宋人议亲忌才名过露，见《宋会要辑稿》婚礼议德。"},{"text":"辩说文章无男女","correct":false,"tags":["自主"],"dims":{"自主":2},"feedback":"母亲叹气：「道理是这个道理，世道不是这个世道。」","source":"宋代闺秀才名与妇德之辨，见《仪礼》妇顺之训。"}],"difficulty":2,"npc":["母亲"],"foreshadow":null},{"id":"C-010-戌","branch":"C","stage":1,"day":10,"shichen":"戌时","checkpoint":"父亲考诗","scene":"晚课后父亲忽出题：「就以阶前白菊为咏，限一炷香。」","options":[{"text":"咏其晚节不咏颜色","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"父亲沉吟良久，说了句「气象不小」，把诗稿收进了袖中。","source":"李格非以诗文课女，见《金石录后序》记家学渊源。"},{"text":"堆砌金玉字眼求工","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"父亲皱眉：「绮靡有余，风骨不足。重写。」","source":"宋人论诗重风骨轻绮靡，见《续资治通鉴长编》记士风。"}],"difficulty":3,"npc":["父亲"],"foreshadow":null},{"id":"C-011","branch":"C","stage":1,"day":11,"shichen":"辰时","checkpoint":"家宴屏后","scene":"家中设宴请父亲的同年。你按礼在屏后伺候茶水，席间诗酒唱和，一句句往耳朵里钻。","options":[{"text":"默记佳句饭后录下","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"饭后你录下半纸，比席上人自己记的还全。","source":"士人宴集以诗为礼，见《东京梦华录》记士庶宴饮。"},{"text":"听得入迷忘了续茶","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"母亲咳嗽一声提醒你，客人的茶盏空了好一会儿。","source":"闺秀执事以勤谨为先，见《仪礼》妇职。"}],"difficulty":1,"npc":["父亲","客人"],"foreshadow":null},{"id":"C-011-未","branch":"C","stage":1,"day":11,"shichen":"未时","checkpoint":"太学来信","scene":"族兄自太学寄信回家，说今年诸生最盛谈的是「格物」二字，还说太学里也有人传看闺中词。","options":[{"text":"回信请教格物之义","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"族兄回信写了满满两页，直夸你问得在点子上。","source":"太学讲格物穷理，见《续资治通鉴长编》记太学学制。"},{"text":"只问谁在传看词","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"族兄回信打趣：「妹妹这是急了？」你臊了半天。","source":"闺词传入太学为雅谈，见《琅嬛记》。"}],"difficulty":2,"npc":["族兄"],"foreshadow":"词入太学"},{"id":"C-011-戌","branch":"C","stage":1,"day":11,"shichen":"戌时","checkpoint":"灯下说文","scene":"父亲把相国寺那部《说文解字》带了回来，往你案上一放：「蜀刻，拿去读。」","options":[{"text":"当夜先读序再检字","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"序里「文字者，经艺之本」一句，你看了三遍。","source":"《说文解字》宋时蜀刻为贵，见《东京梦华录》记书肆刻本。"},{"text":"翻两页嫌枯燥搁下","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"父亲也不催，只说：「搁着吧，总有你回头寻它的时候。」","source":"小学为治经之门，见《金石录后序》记父子论学。"}],"difficulty":2,"npc":["父亲"],"foreshadow":"说文解字"},{"id":"C-012","branch":"C","stage":1,"day":12,"shichen":"辰时","checkpoint":"选衣料","scene":"母亲带你去库里选衣料，说姑娘家的四季衣裳要提早备。满架罗绢，你一眼看中那匹月白的。","options":[{"text":"选月白绢再配绛带","correct":true,"tags":["家世","才华"],"dims":{"家世":1,"才华":1},"feedback":"母亲点头：「素净里见精神，是你的眼光。」","source":"宋士人女装尚素雅，见《周氏墓》出土衣饰用色。"},{"text":"挑最艳的大红妆花","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"母亲按下：「那是喜服的料子，平白穿了招摇。」","source":"大红为吉服之色，常服忌僭，见《宋会要辑稿》服制。"}],"difficulty":1,"npc":["母亲"],"foreshadow":null},{"id":"C-012-未","branch":"C","stage":1,"day":12,"shichen":"未时","checkpoint":"新妇回门","scene":"邻家新妇回门，说起夫家规矩：晨昏定省之外，婆婆还考她算账。你听得心里直打鼓。","options":[{"text":"向她讨教应对之法","correct":true,"tags":["家世","自主"],"dims":{"家世":1,"自主":1},"feedback":"新妇悄悄教你：「账目要暗里清楚，面上要装糊涂。」","source":"新妇事姑舅以顺为则，见《仪礼》妇事舅姑之礼。"},{"text":"说这样的家不嫁也罢","correct":false,"tags":["自主"],"dims":{"自主":2},"feedback":"新妇苦笑：「嫁都嫁了，说这个还有什么用。」","source":"宋妇人既嫁从夫，见《宋刑统》户婚律。"}],"difficulty":2,"npc":["邻家新妇"],"foreshadow":"为妇之难"},{"id":"C-012-戌","branch":"C","stage":1,"day":12,"shichen":"戌时","checkpoint":"夜坐自省","scene":"夜静了，你对着烛花想白天的事——规矩、账目、婆婆。嫁做人妇，到底是怎样一回事？","options":[{"text":"把疑问逐条写在小笺","correct":true,"tags":["自主","才华"],"dims":{"自主":1,"才华":1},"feedback":"写完了心里反倒亮堂些，笺子压在了妆奁底。","source":"闺中自记心事为常，见《琅嬛记》。"},{"text":"吹灯睡觉不去想了","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"明日自有明日的章程，你睡得倒还安稳。","source":"闺秀言行贵安分从容，见《仪礼》。"}],"difficulty":1,"npc":null,"foreshadow":"妆奁笺","flavor":true},{"id":"C-013","branch":"C","stage":1,"day":13,"shichen":"辰时","checkpoint":"雨后海棠","scene":"昨夜雨疏风骤。晨起你试问卷帘的丫鬟，海棠如何？她答「却道海棠依旧」。你失笑——「知否，知否，应是绿肥红瘦」。","options":[{"text":"把这问答写入小词","correct":true,"tags":["才华"],"dims":{"才华":3},"feedback":"一阕小词一挥而就，你搁笔看了又看。","source":"宋人以词记日常问答，见《琅嬛记》闺词记事。"},{"text":"亲自去园中看海棠","correct":true,"tags":["自主","才华"],"dims":{"自主":1,"才华":2},"feedback":"绿肥红瘦，果然。雨打过的花，更见精神。","source":"汴京人家多植海棠，见《东京梦华录》记园囿花木。"}],"difficulty":1,"npc":["丫鬟"],"foreshadow":"海棠词","flavor":true,"yishou":true},{"id":"C-013-未","branch":"C","stage":1,"day":13,"shichen":"未时","checkpoint":"词稿外传","scene":"闺伴来访，一眼看见案上那阕海棠词，死活要抄一份带走，说是「这样的句子，不传可惜了」。","options":[{"text":"叮嘱莫署我的名字","correct":true,"tags":["才华","名声"],"dims":{"才华":1,"名声":1},"feedback":"闺伴应下。可好句子自己会长脚，你拦不住的。","source":"闺词外传多不署名，见《琅嬛记》。"},{"text":"由她署上名字传去","correct":false,"tags":["名声"],"dims":{"名声":2},"feedback":"词是好词，可「恃才扬己」四个字也快到你家门口了。","source":"女子才名过露易招物议，见《宋会要辑稿》议婚重德。"}],"difficulty":2,"npc":["闺伴"],"foreshadow":"词名渐起"},{"id":"C-013-戌","branch":"C","stage":1,"day":13,"shichen":"戌时","checkpoint":"席间闻词","scene":"父亲赴宴回来，进门便笑：「今日席上有人念一阕咏海棠的小词，满座叫好。你猜是谁写的？」","options":[{"text":"装傻说猜不着","correct":true,"tags":["自主","才华"],"dims":{"自主":1,"才华":1},"feedback":"父亲大笑：「我的女儿，我还能认不出她的笔意？」","source":"父女以文相认，见《金石录后序》记家学之趣。"},{"text":"红着脸认了","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"父亲正色道：「词是好词。往后传出去的，都要是这样的。」","source":"父教以文质相兼，见《金石录后序》。"}],"difficulty":1,"npc":["父亲"],"foreshadow":null,"flavor":true},{"id":"C-014","branch":"C","stage":1,"day":14,"shichen":"辰时","checkpoint":"赵家遣媒","scene":"王媒婆三度登门，这回说的是赵太丞家：「他家公子在太学，人才出众，最爱读史。」你心里忽地一动。","options":[{"text":"不动声色听她说完","correct":true,"tags":["家世","感情"],"dims":{"家世":2},"feedback":"母亲送客回来，只说了一句：「这家，可以议。」","source":"议亲由家长主之，女听而已，见《仪礼》婚义。"},{"text":"忍不住问公子样貌","correct":false,"tags":["名声","感情"],"dims":{"情缘":1,"名声":1},"feedback":"王媒婆笑出了声，母亲的眼刀立刻飞了过来。","source":"闺秀问婚忌轻佻，见《宋会要辑稿》婚礼仪注。"}],"difficulty":2,"npc":["王媒婆","母亲"],"foreshadow":"赵家议亲"},{"id":"C-014-未","branch":"C","stage":1,"day":14,"shichen":"未时","checkpoint":"访赵家事","scene":"母亲托乳母去打听赵家公子的为人。傍晚乳母回话：「读书种子，不赌不狎，就是爱收金石字画，花钱如流水。」","options":[{"text":"说爱收字画是雅癖","correct":true,"tags":["情缘","才华"],"dims":{"情缘":1,"才华":1},"feedback":"母亲失笑：「你倒替他说话。」你的耳根先红了。","source":"宋士人以金石书画为雅好，见《东京梦华录》记相国寺书画市。"},{"text":"嫌花钱如流水不妥","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"乳母道：「娘子有所不知，那家底厚，供得起这个癖。」","source":"赵氏为宗室疏属，家丰于财，见《宋会要辑稿》宗室条。"}],"difficulty":2,"npc":["乳母","母亲"],"foreshadow":"金石之癖"},{"id":"C-014-戌","branch":"C","stage":1,"day":14,"shichen":"戌时","checkpoint":"灯下心事","scene":"夜里你铺开小笺，想写点什么。「读书种子」「金石字画」几个字眼在脑子里转，笔尖迟迟落不下去。","options":[{"text":"把心事写成朦胧词","correct":true,"tags":["情缘","才华"],"dims":{"情缘":2,"才华":1},"feedback":"写完了自己读，句句是他，字字无他。","source":"闺词多寄托难言之情，见《琅嬛记》。"},{"text":"搁笔熄灯逼自己睡","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"躺下了，烛花爆了一声，你又睁开了眼。","source":"待字女儿心事，见《琅嬛记》闺情琐记。"}],"difficulty":1,"npc":null,"foreshadow":"朦胧词"},{"id":"C-015","branch":"C","stage":1,"day":15,"shichen":"辰时","checkpoint":"焚香雅集","scene":"家里要办小雅集招待几位女眷。母亲教你焚香：「香要隔火，烟要细，主人家的体面全在这些看不见的地方。」","options":[{"text":"守着香炉盯了半日","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"客人进门便道「好香」，母亲脸上有光。","source":"宋人燕居以焚香为雅，见《梦粱录》记烧香点茶四般闲事。"},{"text":"交给嬷嬷自己躲懒","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"香灰塌了一回，嬷嬷重起了一炉，谁都看见了。","source":"待客之礼主人亲执，见《仪礼》主妇设食之义。"}],"difficulty":1,"npc":["母亲","嬷嬷"],"foreshadow":null},{"id":"C-015-未","branch":"C","stage":1,"day":15,"shichen":"未时","checkpoint":"婶娘探口风","scene":"族中婶娘来做客，话里话外打探你的亲事：「衙内家那样的人家，过了这村可没这店了。」","options":[{"text":"只说全凭父母做主","correct":true,"tags":["家世","名声"],"dims":{"家世":1,"名声":1},"feedback":"婶娘讨了个没趣，讪讪转了话头。","source":"婚事由父母之命，闺秀不自陈，见《仪礼》。"},{"text":"脱口说那家不合适","correct":false,"tags":["自主"],"dims":{"自主":2},"feedback":"话传到衙内家耳朵里，便成了「李家女儿嫌我们家」。","source":"议亲言语出口即招是非，见《宋会要辑稿》戒争讼婚。"}],"difficulty":3,"npc":["婶娘"],"foreshadow":"衙内记恨"},{"id":"C-015-戌","branch":"C","stage":1,"day":15,"shichen":"戌时","checkpoint":"回绝之意","scene":"父亲把母亲和你叫到一处，沉声道：「衙内家这门亲，我想回了。就怕驳了面子，往后多事。」","options":[{"text":"说利害父亲早看透了","correct":true,"tags":["家世","自主"],"dims":{"家世":1,"自主":1},"feedback":"父亲点头：「你既明白，我便没什么可顾忌的。」","source":"婚配父主之而咨于女，见《仪礼》婚义注疏。"},{"text":"吓得一句话说不出","correct":false,"tags":["名声"],"dims":{"家世":1},"feedback":"父亲叹口气：「罢了，横竖有爹娘替你担着。」","source":"女儿以父母为依，见《宋刑统》户婚律。"}],"difficulty":2,"npc":["父亲","母亲"],"foreshadow":"拒婚伏笔"},{"id":"C-016","branch":"C","stage":1,"day":16,"shichen":"辰时","checkpoint":"媒婆回话","scene":"王媒婆来回话，说衙内家听到回绝，脸面上很下不来，放出话来：「看谁还敢跟李家结亲。」","options":[{"text":"安慰媒婆不怪她","correct":true,"tags":["名声","自主"],"dims":{"名声":1,"自主":1},"feedback":"王媒婆叹道：「娘子这份涵养，自有更好的人家配。」","source":"媒人两头传话最忌结怨，见《东京梦华录》记媒妁之俗。"},{"text":"冷笑道随他们去","correct":false,"tags":["自主"],"dims":{"自主":2},"feedback":"这话经媒婆的嘴传出去，又添了三分颜色。","source":"言语招尤，见《宋会要辑稿》戒妇人预外事。"}],"difficulty":2,"npc":["王媒婆"],"foreshadow":"衙内记恨"},{"id":"C-016-未","branch":"C","stage":1,"day":16,"shichen":"未时","checkpoint":"母亲忧心","scene":"母亲一整天心神不宁，择菜时掐断了三根葱都不知道。你搬了个绣墩坐到她旁边。","options":[{"text":"宽慰母亲赵家更好","correct":true,"tags":["情缘","家世"],"dims":{"情缘":1,"家世":1},"feedback":"母亲拍拍你的手：「但愿吧。赵家的庚帖，明日便去合。」","source":"合庚帖问吉凶为纳吉，见《仪礼》六礼。"},{"text":"自己也慌得直掉泪","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"娘儿俩对着掉了一回眼泪，反倒都不那么怕了。","source":"母女相依，见《琅嬛记》闺情。"}],"difficulty":1,"npc":["母亲"],"foreshadow":"赵家纳吉"},{"id":"C-016-戌","branch":"C","stage":1,"day":16,"shichen":"戌时","checkpoint":"父亲风骨","scene":"晚饭时父亲只说了一句话：「我们李家的女儿，不嫁权势，嫁人品。」一桌子人都安静了。","options":[{"text":"起身给父亲斟一盏","correct":true,"tags":["家世","自主"],"dims":{"家世":2,"自主":1},"feedback":"父亲接过茶，眼里有笑：「我女儿懂事。」","source":"李格非以风节著，不附权贵，见《金石录后序》。"},{"text":"低头扒饭记在心里","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"这句话你记了一辈子。","source":"宋士人家以气节传家，见《续资治通鉴长编》士风。"}],"difficulty":1,"npc":["父亲","母亲"],"foreshadow":null,"flavor":true},{"id":"C-017","branch":"C","stage":1,"day":17,"shichen":"辰时","checkpoint":"上巳梳妆","scene":"三月三，上巳日。母亲破例许你随家眷出游祓禊。晨起梳妆，丫鬟在你鬓边簪了一枝新折的兰草。","options":[{"text":"淡妆佩兰不失闺仪","correct":true,"tags":["家世","名声"],"dims":{"家世":1,"名声":1},"feedback":"母亲上下打量：「这样才像书香人家的姑娘。」","source":"上巳士女出游盛妆而贵有度，见《梦粱录》记上巳。"},{"text":"盛装要压过满堤人","correct":false,"tags":["名声"],"dims":{"名声":2},"feedback":"一路被人指点「好招摇的小娘子」，母亲的笑有点挂不住。","source":"闺秀出游客的体宜端重，见《仪礼》妇容之训。"}],"difficulty":1,"npc":["母亲","丫鬟"],"foreshadow":"上巳初见"},{"id":"C-017-未","branch":"C","stage":1,"day":17,"shichen":"未时","checkpoint":"水边初逢","scene":"水滨祓禊，游人如织。对岸一队太学生禊饮赋诗，为首的年轻人一袭青衫，临流执卷。丫鬟低呼：「那不是赵家——」","options":[{"text":"垂目敛袖不看第二眼","correct":true,"tags":["名声","情缘","感情"],"dims":{"名声":1,"情缘":1},"feedback":"可那袭青衫，到底还是在你眼底停了一瞬。","source":"上巳男女各以群游，遥观不狎，见《东京梦华录》记上巳游观。"},{"text":"大大方方望了过去","correct":false,"tags":["名声","感情"],"dims":{"名声":2},"feedback":"对岸有人哄笑起来，母亲拉着你便走：「成什么体统！」","source":"男女大防，见《仪礼》男女不杂坐之戒。"}],"difficulty":3,"npc":["丫鬟","母亲","赵家公子"],"foreshadow":"青衫初见"},{"id":"C-017-戌","branch":"C","stage":1,"day":17,"shichen":"戌时","checkpoint":"归途听闻","scene":"归途车上，随行婆子们还在说白天的热闹：「太学那班人里，领头的那个后生，一首诗惊动了一座堤。」","options":[{"text":"只听着一句不问","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"你掀开车帘看外头的灯，耳朵却一直竖着。","source":"上巳诗会传为都中谈资，见《武林旧事》记上巳诗事。"},{"text":"打听那后生是谁","correct":false,"tags":["名声"],"dims":{"名声":1,"情缘":1},"feedback":"婆子们挤眉弄眼：「娘子这是动心了？」","source":"闺秀言动皆为议亲之资，见《宋会要辑稿》婚礼议德。"}],"difficulty":2,"npc":["婆子"],"foreshadow":"青衫初见"},{"id":"C-018","branch":"C","stage":1,"day":18,"shichen":"辰时","checkpoint":"记游小词","scene":"晨起凭窗，昨日的水光人影还在眼前。你铺开小笺，想把祓禊所见记下来，笔尖转了几转。","options":[{"text":"只写春水不写人","correct":true,"tags":["才华","情缘"],"dims":{"才华":2,"情缘":1},"feedback":"一阕词写尽了春水，又好像写尽了别的什么。","source":"宋人咏物词多有所寄，见《琅嬛记》。"},{"text":"把青衫也写进词里","correct":false,"tags":["情缘","名声"],"dims":{"情缘":2,"名声":1},"feedback":"写完你自己先臊了，揉了笺子——这样的东西可传不得。","source":"闺词涉男女之嫌为忌，见《琅嬛记》闺戒。"}],"difficulty":2,"npc":null,"foreshadow":"春水词","yishou":true},{"id":"C-018-未","branch":"C","stage":1,"day":18,"shichen":"未时","checkpoint":"闺伴来报","scene":"闺伴跑来，进门便嚷：「奇了！太学里都在传你那阕海棠词，都说不知谁家女儿，有这样一副玲珑心肝！」","options":[{"text":"问太学里谁最称赞","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"闺伴掰着指头数，数到第三个名字时你垂下了眼——赵家的。","source":"闺词入太学为雅谈，见《琅嬛记》。"},{"text":"恼她多嘴赶她走","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"闺伴委屈：「好心当成驴肝肺。」扭头三日没理你。","source":"闺伴交恶易生口舌，见《琅嬛记》。"}],"difficulty":2,"npc":["闺伴"],"foreshadow":"词为媒"},{"id":"C-018-戌","branch":"C","stage":1,"day":18,"shichen":"戌时","checkpoint":"灯下猜想","scene":"灯下你翻来覆去想一件事：他读那阕词的时候，会是什么神情？读完，会不会也想见见写词的人？","options":[{"text":"想归想照旧熄灯睡","correct":true,"tags":["自主","情缘"],"dims":{"自主":1,"情缘":1},"feedback":"梦里仿佛有水声，有鸥鹭，有一袭看不清脸的青衫。","source":"闺中情思见于梦，见《琅嬛记》。"},{"text":"披衣起来再添一阕","correct":false,"tags":["才华","情缘"],"dims":{"才华":1,"情缘":2},"feedback":"写到「那人」二字，笔尖一顿，到底没敢落墨。","source":"闺词避嫌，见《琅嬛记》闺戒。"}],"difficulty":1,"npc":null,"foreshadow":null},{"id":"C-019","branch":"C","stage":1,"day":19,"shichen":"辰时","checkpoint":"两家通问","scene":"赵家正式遣人来「通问」。母亲整衣见客，你在里间听见外头说「两家世谊，早有结好之意」。","options":[{"text":"静心听完才起身","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"母亲进来时眼角带笑：「赵家的意思，很诚。」","source":"纳采前先通问两家之意，见《仪礼》婚义疏。"},{"text":"贴着门缝往外瞧","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"衣角扫倒了门边花架，外头都听见了。","source":"闺秀屏居不露面，见《仪礼》内外之制。"}],"difficulty":2,"npc":["母亲","赵家使者"],"foreshadow":"赵家纳采"},{"id":"C-019-未","branch":"C","stage":1,"day":19,"shichen":"未时","checkpoint":"学备端午","scene":"端午将近，嬷嬷教你裹粽子、系百索。你想起太学也有解粽之会，手上的丝线绕着绕着走了神。","options":[{"text":"回神把粽子裹端正","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"嬷嬷数着你裹的角黍：「端正，跟娘子的人一样。」","source":"端午裹粽系百索，见《东京梦华录》记端午物事。"},{"text":"走神扎破了手指","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"血珠冒出来，嬷嬷笑骂：「魂儿飞哪儿去了？」","source":"端午诸事，见《梦粱录》。"}],"difficulty":1,"npc":["嬷嬷"],"foreshadow":null},{"id":"C-019-戌","branch":"C","stage":1,"day":19,"shichen":"戌时","checkpoint":"父亲考较","scene":"晚间父亲问你：「赵家公子，你都知道些什么？」你垂手立着，知道这一关要过得妥帖。","options":[{"text":"只说他惜金石爱词章","correct":true,"tags":["才华","情缘"],"dims":{"才华":1,"情缘":1},"feedback":"父亲颔首：「看他行事，是个能惜物的。惜物者惜人。」","source":"观人以所好，见《续资治通鉴长编》人物品藻。"},{"text":"红着脸说不知道","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"父亲笑了：「不知道？前日谁耳朵竖得那样高？」","source":"父女谐语，见《金石录后序》记闺门之乐。"}],"difficulty":2,"npc":["父亲"],"foreshadow":"惜物惜人"},{"id":"C-020","branch":"C","stage":1,"day":20,"shichen":"辰时","checkpoint":"流言骤起","scene":"清早王媒婆赶来报信：衙内家在外放话，说李家女儿「才名是假，品行有亏」，分明是要坏你的名声。","options":[{"text":"请母亲找证人自证","correct":true,"tags":["家世","名声"],"dims":{"家世":1,"名声":2},"feedback":"斗草、雅集的女眷都愿意作证，流言先矮了半截。","source":"名誉之争以人证为解，见《宋会要辑稿》戒诬讼。"},{"text":"气得要上门理论","correct":false,"tags":["自主"],"dims":{"自主":2},"feedback":"母亲死死拦住：「你这一去，正中了人家下怀！」","source":"闺秀不与外事，见《仪礼》内外之防。"}],"difficulty":3,"npc":["王媒婆","母亲"],"foreshadow":"流言风波"},{"id":"C-020-未","branch":"C","stage":1,"day":20,"shichen":"未时","checkpoint":"父亲辨白","scene":"父亲下朝回来，说他今日当着几位同年把话挑明了：「小女才名，席间诸公都见过。污蔑小女，就是污蔑在座诸位的眼睛。」","options":[{"text":"给父亲奉一盏热茶","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"父亲接了茶：「读书人护读书人，他们不敢再嚼舌根。」","source":"士人相护以清议为盾，见《续资治通鉴长编》记士风。"},{"text":"追问谁在背后使坏","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"父亲摆手：「知道是谁又如何？把自己的日子过好便是。」","source":"君子不争口舌，见《仪礼》义疏。"}],"difficulty":2,"npc":["父亲"],"foreshadow":null},{"id":"C-020-戌","branch":"C","stage":1,"day":20,"shichen":"戌时","checkpoint":"一家同心","scene":"晚间一家人围坐。母亲说：「经这一遭，倒把谁亲谁疏看清楚了。」你忽然觉得，风波也不全是坏事。","options":[{"text":"把这话记进小笺","correct":true,"tags":["自主","才华"],"dims":{"自主":1,"才华":1},"feedback":"「患难见人心」五个字，你写得格外用力。","source":"闺中记事，见《琅嬛记》。"},{"text":"说往后更需谨慎","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"父亲点头：「吃过亏知道谨慎，这亏就没白吃。」","source":"家教以惩忿为先，见《仪礼》。"}],"difficulty":1,"npc":["父亲","母亲"],"foreshadow":null,"flavor":true},{"id":"C-021","branch":"C","stage":1,"day":21,"shichen":"辰时","checkpoint":"赵家纳采","scene":"吉日。赵家遣使纳采，礼物里一对活雁用红绸系着，执礼甚恭。你隔着帘子，听见满院的道贺声。","options":[{"text":"依礼回避不出","correct":true,"tags":["家世","名声"],"dims":{"家世":1,"名声":1},"feedback":"使者回去禀报：「李家娘子的礼数，一丝不差。」","source":"纳采用雁，女家受之，闺秀回避，见《仪礼》士昏礼。"},{"text":"隔帘偷看那对雁","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"雁是活的，扑棱一声，吓了你一跳，也笑了你一回。","source":"纳采用雁取其顺阴阳，见《仪礼》士昏礼。"}],"difficulty":2,"npc":["赵家使者","母亲"],"foreshadow":"纳采成"},{"id":"C-021-未","branch":"C","stage":1,"day":21,"shichen":"未时","checkpoint":"庚帖合吉","scene":"两家庚帖送到庙里合过，回话说「天造地设，大吉」。母亲把庚帖供在案上，烧了三炷香。","options":[{"text":"随母亲拜了一拜","correct":true,"tags":["情缘","家世"],"dims":{"情缘":1,"家世":1},"feedback":"香烟袅袅里，你忽然有点相信命了。","source":"纳吉归卜于庙，得吉乃定，见《仪礼》士昏礼。"},{"text":"心里说不信这个","correct":false,"tags":["自主"],"dims":{"自主":2},"feedback":"话到嘴边又咽了回去——今日，就让母亲高兴高兴吧。","source":"婚仪尚卜吉，见《宋会要辑稿》婚礼。"}],"difficulty":1,"npc":["母亲"],"foreshadow":"婚事初定"},{"id":"C-021-戌","branch":"C","stage":1,"day":21,"shichen":"戌时","checkpoint":"名分初定","scene":"夜里你躺在床上想：过了今日，你便是「赵家未来的媳妇」了。这个名分像一件新衣，合身又陌生。","options":[{"text":"披衣写下一阕词","correct":true,"tags":["情缘","才华","感情"],"dims":{"情缘":2,"才华":1},"feedback":"词里没有他的名字，可每个字都朝着他。","source":"闺词寄情，见《琅嬛记》。"},{"text":"翻来覆去到天明","correct":false,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"晨起母亲看你眼下乌青，只当你是欢喜的。","source":"待嫁女儿心事，见《琅嬛记》。"}],"difficulty":1,"npc":null,"foreshadow":null},{"id":"C-022","branch":"C","stage":1,"day":22,"shichen":"辰时","checkpoint":"开奁单","scene":"母亲取出一本厚册子：「该教你立奁单了。嫁妆不是摆设，是你往后几十年的底气。」","options":[{"text":"一笔一画跟着记","correct":true,"tags":["家世","自主"],"dims":{"家世":2,"自主":1},"feedback":"田几亩、铺几间、器物若干——你头一回看清「底气」长什么样。","source":"宋人厚嫁，奁产为妇私财，见《宋会要辑稿》记奁产。"},{"text":"嫌铜臭不肯学","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"母亲把册子一合：「今日嫌它俗，他日就要吃它的亏。」","source":"奁产为妇立身之本，见《宋刑统》户婚律记妻财。"}],"difficulty":2,"npc":["母亲"],"foreshadow":"奁产启蒙"},{"id":"C-022-未","branch":"C","stage":1,"day":22,"shichen":"未时","checkpoint":"学看田契","scene":"母亲铺开几张田契教你认：哪张是活契，哪张是绝卖，红契白契差在哪儿，佃户的名册怎么看。","options":[{"text":"逐张问过不肯含糊","correct":true,"tags":["自主","家世"],"dims":{"自主":1,"家世":1},"feedback":"母亲欣慰：「懂了这些，往后谁也别想糊弄你。」","source":"宋田契分红契白契，见《宋刑统》记典卖之制。"},{"text":"看了两张便喊头疼","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"母亲也不逼你：「慢慢来，反正离出阁还有日子。」","source":"奁产管理为妇职之一，见《梦粱录》记嫁娶奁具。"}],"difficulty":3,"npc":["母亲"],"foreshadow":"奁产启蒙"},{"id":"C-022-戌","branch":"C","stage":1,"day":22,"shichen":"戌时","checkpoint":"底气之论","scene":"夜里母亲替你将奁单收进妆奁，忽然说：「记住，这些东西到了夫家还是你的。女人在婆家的腰杆，一半是它撑的。」","options":[{"text":"问另一半是什么","correct":true,"tags":["自主","家世"],"dims":{"自主":1,"家世":1},"feedback":"母亲笑了：「另一半？是你的心性和本事。」","source":"宋妇奁产为私财，见《宋刑统》户婚律。"},{"text":"点头把册子抱紧","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"那本厚册子，从此成了你妆奁最底下的一层。","source":"奁单随身入夫家，见《东京梦华录》记嫁娶。"}],"difficulty":1,"npc":["母亲"],"foreshadow":"奁产底气","flavor":true},{"id":"C-023","branch":"C","stage":1,"day":23,"shichen":"辰时","checkpoint":"选陪嫁书画","scene":"父亲带你开他的藏室，让你自己挑陪嫁的书画碑帖：「金银是死的，这些是活的。挑你真正喜欢的。」","options":[{"text":"挑金石碑帖与古籍","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"父亲抚掌：「好眼光！这些东西，识货的人才知道金贵。」","source":"士人家以书画碑帖为奁，见《金石录后序》记收藏。"},{"text":"挑最值钱的几件","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"父亲摇头：「值钱的未必是好的。重来。」","source":"收藏重鉴赏不重价，见《金石录后序》。"}],"difficulty":2,"npc":["父亲"],"foreshadow":"金石陪嫁"},{"id":"C-023-未","branch":"C","stage":1,"day":23,"shichen":"未时","checkpoint":"辨伪课","scene":"父亲取出一真一赝两张帖，教你辨：纸色、墨色、印章、题跋，一样样对过去。","options":[{"text":"看出赝品三处破绽","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"父亲拊掌：「可以出师一半了。」","source":"宋人辨帖重纸墨题跋，见《金石录后序》记鉴赏。"},{"text":"把真的当成了假的","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"父亲大笑：「打眼了！多看多摸，眼力是喂出来的。」","source":"鉴赏以目验为学，见《金石录后序》。"}],"difficulty":3,"npc":["父亲"],"foreshadow":"金石之癖"},{"id":"C-023-戌","branch":"C","stage":1,"day":23,"shichen":"戌时","checkpoint":"收藏之乐","scene":"晚来父亲摩挲着一方古印，说起他年轻时为一卷碑帖徒步百里的旧事，眼里有光。","options":[{"text":"听得入神往更多问","correct":true,"tags":["才华","情缘"],"dims":{"才华":1,"情缘":1},"feedback":"你忽然想：那个爱收金石的赵家公子，和父亲是一路人。","source":"士人以金石为性命，见《金石录后序》。"},{"text":"笑父亲痴","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"父亲也不恼：「痴才好。人无癖不可与交。」","source":"癖好之说，见《琅嬛记》引前人语。"}],"difficulty":1,"npc":["父亲"],"foreshadow":"金石同好"},{"id":"C-024","branch":"C","stage":1,"day":24,"shichen":"辰时","checkpoint":"纳征议聘","scene":"赵家纳征，聘礼单子抬了进来：币帛、茶饼、金银、衣饰，一样样唱名入库。媒婆的嘴一直没停过。","options":[{"text":"帮母亲对单子入库","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"单子与实物分毫不差，母亲对媒婆笑道：「赵家是体面人。」","source":"纳征即纳币，礼物唱名，见《仪礼》士昏礼。"},{"text":"躲在房里不好意思","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"母亲后来埋怨：「自己的聘礼都不经心，像什么样子。」","source":"新妇当事事经心，见《仪礼》妇职。"}],"difficulty":2,"npc":["母亲","王媒婆"],"foreshadow":"纳征成"},{"id":"C-024-未","branch":"C","stage":1,"day":24,"shichen":"未时","checkpoint":"婶娘酸语","scene":"婶娘又来，这回换了副面孔：「哎哟，赵家那样的门第，侄女儿嫁过去，可要看人脸色哟。」","options":[{"text":"笑着岔开不接招","correct":true,"tags":["名声","自主"],"dims":{"名声":1,"自主":1},"feedback":"你一腔春风把她的话堵了回去，婶娘坐不住，先走了。","source":"应对以柔为刚，见《仪礼》妇顺之义。"},{"text":"反唇相讥顶回去","correct":false,"tags":["自主"],"dims":{"自主":2},"feedback":"痛快是痛快，可「李家女儿牙尖嘴利」又添了新注脚。","source":"口舌招尤，见《宋会要辑稿》戒讼。"}],"difficulty":2,"npc":["婶娘"],"foreshadow":null},{"id":"C-024-戌","branch":"C","stage":1,"day":24,"shichen":"戌时","checkpoint":"盘点奁单","scene":"夜里你与母亲把奁单又过了一遍：田、铺、器物、书画，再添上今日赵家的聘礼，厚厚一册了。","options":[{"text":"提议书画单列一册","correct":true,"tags":["才华","家世"],"dims":{"才华":1,"家世":1},"feedback":"母亲依了你：「也好，这些是心头物，不与寻常物件混记。」","source":"书画碑帖别为一藏，见《金石录后序》记归来堂。"},{"text":"打着哈欠说够了","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"母亲合上册子：「也是，日子长着呢，慢慢添。」","source":"奁产随时增益，见《梦粱录》记嫁娶。"}],"difficulty":1,"npc":["母亲"],"foreshadow":"书画奁册"},{"id":"C-025","branch":"C","stage":1,"day":25,"shichen":"辰时","checkpoint":"请期将至","scene":"赵家来请期了——正式商量婚期。日子定在来年。从今日起，你待嫁的日子，可以一天一天数了。","options":[{"text":"在心里记下这个数","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"还有多少日？你在心里排了一遍，又排了一遍。","source":"请期择吉以告，见《仪礼》士昏礼。"},{"text":"嘴上说着还早还早","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"丫鬟抿嘴笑：「娘子昨夜数日子数到几更，当我不知道？」","source":"闺中情态，见《琅嬛记》。"}],"difficulty":1,"npc":["母亲","丫鬟"],"foreshadow":"婚期初定"},{"id":"C-025-未","branch":"C","stage":1,"day":25,"shichen":"未时","checkpoint":"回望来路","scene":"午后独坐，你想起及笄那日——不过月余，恍如隔世。这一个月学的、见的、经的，都够写一本书了。","options":[{"text":"把这月余记成长卷","correct":true,"tags":["才华","自主"],"dims":{"才华":2,"自主":1},"feedback":"写到最后一句，你停了笔：往后的日子，会写成什么样？","source":"闺中自记行年，见《琅嬛记》。"},{"text":"去园中走了一圈","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"海棠早已谢了。可你知道，明年它还会开。","source":"闺中伤时感物，见《琅嬛记》。"}],"difficulty":1,"npc":null,"foreshadow":"长卷","flavor":true},{"id":"C-025-戌","branch":"C","stage":1,"day":25,"shichen":"戌时","checkpoint":"父亲赠言","scene":"晚间父亲把你叫到书房，只说了两句话：「嫁得出去，不算本事。嫁得值，才是。赵家那孩子，我替你相看过了——值。」","options":[{"text":"郑重谢过父亲","correct":true,"tags":["家世","情缘"],"dims":{"家世":1,"情缘":2},"feedback":"父亲摆摆手，眼角却有笑纹：「去吧，早些安置。」","source":"父为女择配重人品，见《仪礼》婚义。"},{"text":"问哪里看得出值","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"父亲笑道：「他看碑帖的眼神，跟我年轻时一模一样。」","source":"观人以所好，见《金石录后序》。"}],"difficulty":1,"npc":["父亲"],"foreshadow":"阶段一毕","flavor":true},{"id":"C-026","branch":"C","stage":2,"day":26,"shichen":"辰时","checkpoint":"学中馈","scene":"婚事既定，母亲开始教你管家的头一课：「中馈不是做饭，是一家的油盐柴米、人情往来，全在你心里一本账。」","options":[{"text":"从今日的家用账看起","correct":true,"tags":["家世","自主"],"dims":{"家世":2,"自主":1},"feedback":"一本流水账看下来，谁家节礼该添、哪笔采买该省，你有了数。","source":"宋妇主中馈掌家计，见《梦粱录》记人家日用。"},{"text":"说这些交给仆妇便是","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"母亲正色：「仆妇可代劳，不可代心。你心里没数，家就漏了。」","source":"主妇总持家计，见《仪礼》妇职之义。"}],"difficulty":2,"npc":["母亲"],"foreshadow":"中馈之学"},{"id":"C-026-未","branch":"C","stage":2,"day":26,"shichen":"未时","checkpoint":"节礼单子","scene":"母亲让你试拟年下的节礼单子：哪家送酒果，哪家送衣料，哪家新添了人口要加一份，哪家有白事要避讳。","options":[{"text":"先问清各家近况再拟","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"单子拟出来，母亲只改了两处：「比我头一年强多了。」","source":"节礼往来看世情，见《东京梦华录》记节物馈送。"},{"text":"照去年单子抄一遍","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"母亲点着一处：「这家上月添了丁，你照抄去年，失礼。」","source":"馈送随时损益，见《梦粱录》。"}],"difficulty":3,"npc":["母亲"],"foreshadow":null},{"id":"C-026-戌","branch":"C","stage":2,"day":26,"shichen":"戌时","checkpoint":"灯下算账","scene":"夜里你就着灯把家账又盘了一遍，算珠噼啪，竟觉得比诗词另有一番滋味。","options":[{"text":"把窍要记成小册","correct":true,"tags":["自主","家世"],"dims":{"自主":1,"家世":1},"feedback":"你给它起名《居家须知》，压在奁单旁边。","source":"闺中自记家政，见《琅嬛记》。"},{"text":"算完就睡不复盘","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"第二日母亲问起一笔开销，你竟答不上来。","source":"家计贵熟记，见《仪礼》妇职。"}],"difficulty":1,"npc":null,"foreshadow":"居家须知"},{"id":"C-027","branch":"C","stage":2,"day":27,"shichen":"辰时","checkpoint":"学待仆下","scene":"家中仆妇几十口，母亲教你第二课：「驭下要恩威并用。罚要明，赏要快，话要留三分。」","options":[{"text":"记下恩威并施四字","correct":true,"tags":["家世","自主"],"dims":{"家世":1,"自主":1},"feedback":"灶上一个媳妇偷懒，你罚得清楚又给了台阶，满厨房服气。","source":"治家宽严相济，见《仪礼》家治之训。"},{"text":"说仆人用哄的就行","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"不出三日，厨房就敢短你的炭——人善被人欺。","source":"宽而无制则下玩，见《宋刑统》家令之义。"}],"difficulty":2,"npc":["母亲","仆妇"],"foreshadow":null},{"id":"C-027-未","branch":"C","stage":2,"day":27,"shichen":"未时","checkpoint":"认人情簿","scene":"母亲捧出一本《人情簿》：几十年来谁家婚丧嫁娶、送了多少，一笔笔都在。她说这比田契还金贵。","options":[{"text":"按姓氏抄录一份","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"抄到半夜，李家和半座汴京城的关系，在你心里织成了网。","source":"士人家皆有人情账，见《东京梦华录》记往来仪节。"},{"text":"翻几页嫌琐碎","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"母亲叹道：「这些琐碎，就是世道人心。」","source":"人情簿为家学，见《琅嬛记》。"}],"difficulty":2,"npc":["母亲"],"foreshadow":"人情簿"},{"id":"C-027-戌","branch":"C","stage":2,"day":27,"shichen":"戌时","checkpoint":"夜话婆媳","scene":"母亲忽然说起你未来的婆母：「赵家夫人是明白人，但明白人也喜欢被敬重。头三年，熬的是心。」","options":[{"text":"问怎样才算敬重","correct":true,"tags":["家世","自主"],"dims":{"家世":1,"自主":1},"feedback":"母亲道：「小事勤问，大事不专，受了委屈回家说。」","source":"事舅姑之礼，见《仪礼》妇事舅姑。"},{"text":"说我会对她好","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"母亲摇头：「好字太空。婆媳之间，讲究的是分寸。」","source":"妇事姑以顺且敬，见《仪礼》。"}],"difficulty":2,"npc":["母亲"],"foreshadow":"婆媳之道"},{"id":"C-028","branch":"C","stage":2,"day":28,"shichen":"辰时","checkpoint":"冬至亚岁","scene":"冬至大如年。家里祭祖先、排家宴，你头一回以「待嫁之身」坐在了女眷席的上首。","options":[{"text":"依礼祭祖布菜","correct":true,"tags":["家世","名声"],"dims":{"家世":2,"名声":1},"feedback":"族中长辈夸你「进退有度」，母亲的笑藏都藏不住。","source":"冬至亚岁祭祖宴饮，见《东京梦华录》记冬至。"},{"text":"贪杯多饮了几盏","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"女儿红后劲足，你扶着丫鬟回房时脚步已经飘了。","source":"闺秀饮宴以节为礼，见《仪礼》妇容。"}],"difficulty":1,"npc":["母亲","族中长辈"],"foreshadow":null},{"id":"C-028-未","branch":"C","stage":2,"day":28,"shichen":"未时","checkpoint":"贺冬往来","scene":"贺冬的拜帖雪片似的来。母亲让你执笔回帖，字迹要端凝，措辞要得体。","options":[{"text":"一封封斟酌着回","correct":true,"tags":["才华","家世"],"dims":{"才华":1,"家世":1},"feedback":"有夫人见了你的回帖，特来问：「这是谁家的字？」","source":"贺冬拜帖往来，见《梦粱录》记冬至贺冬。"},{"text":"托族兄代笔","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"代笔的字锋藏不住，长辈们私下说李家女儿「惫懒」。","source":"闺翰亲笔为礼，见《琅嬛记》。"}],"difficulty":2,"npc":["母亲"],"foreshadow":"闺翰之名"},{"id":"C-028-戌","branch":"C","stage":2,"day":28,"shichen":"戌时","checkpoint":"冬夜听雪","scene":"夜里落了今冬第一场雪。你推窗看雪压海棠枝，想起春天那句「绿肥红瘦」，心里软软的。","options":[{"text":"就雪写一阕咏絮","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"写完了呵手再看，自觉比春时那首又进了一步。","source":"咏雪为闺中雅事，见《琅嬛记》。"},{"text":"只静静看雪落","correct":true,"tags":["自主","情缘"],"dims":{"自主":1,"情缘":1},"feedback":"不知城那头的赵家公子，此刻是不是也在看雪。","source":"闺中情思，见《琅嬛记》。"}],"difficulty":1,"npc":null,"foreshadow":null,"flavor":true},{"id":"C-029","branch":"C","stage":2,"day":29,"shichen":"辰时","checkpoint":"相国寺庙会","scene":"腊月相国寺大庙会，母亲带你去还愿。万姓交易，人山人海，轿子都挤不进去。","options":[{"text":"扶母亲缓步随人流","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"母亲一路看你护着她，心里很是受用。","source":"相国寺每月五次庙会万姓交易，见《东京梦华录》卷三。"},{"text":"自己先去钻书摊","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"人潮一冲，主仆失散了半个时辰，母亲脸都白了。","source":"闺秀出行不离仆从，见《仪礼》。"}],"difficulty":2,"npc":["母亲"],"foreshadow":"庙会偶遇"},{"id":"C-029-未","branch":"C","stage":2,"day":29,"shichen":"未时","checkpoint":"碑帖摊前","scene":"相国寺后殿碑帖摊前，一个青衫年轻人正为一卷古碑与摊主争价钱。丫鬟拽你袖子：「娘子你看——是赵家那位！」","options":[{"text":"侧身让母亲先走","correct":true,"tags":["名声","情缘"],"dims":{"名声":1,"情缘":1},"feedback":"你们擦肩而过。他眼里的碑，你眼底的他，谁也没看见谁。","source":"士女庙会各不相扰，见《东京梦华录》记相国寺。"},{"text":"驻足听他争价钱","correct":false,"tags":["名声","情缘"],"dims":{"名声":1,"情缘":2},"feedback":"他回头时，你来不及避——四目一对，两个人都怔住了。","source":"庙会男女偶遇为话柄，见《琅嬛记》。"}],"difficulty":3,"npc":["丫鬟","赵家公子"],"foreshadow":"碑摊偶遇"},{"id":"C-029-戌","branch":"C","stage":2,"day":29,"shichen":"戌时","checkpoint":"灯下古意","scene":"回家听说赵家公子到底买下了那卷碑，钱不够，把随身的玉佩押给了摊主。母亲摇头笑：「痴人。」","options":[{"text":"说这才是真性情","correct":true,"tags":["情缘","才华","感情"],"dims":{"情缘":2,"才华":1},"feedback":"母亲睨你一眼：「还没过门，胳膊肘就往外拐了？」","source":"士人典质以购金石，见《金石录后序》记质衣取碑。"},{"text":"只笑了笑没接话","correct":true,"tags":["自主","感情"],"dims":{"自主":1},"feedback":"可那枚押出去的玉佩，在你心里押了一整夜。","source":"闺中情态，见《琅嬛记》。"}],"difficulty":1,"npc":["母亲"],"foreshadow":"玉佩押碑","flavor":true},{"id":"C-030","branch":"C","stage":2,"day":30,"shichen":"辰时","checkpoint":"学做女红礼","scene":"母亲教你备给未来婆家的第一样针线——给婆母的暖耳。她说：「头一样活计，就是你的见面文章。」","options":[{"text":"一针一线不敢苟且","correct":true,"tags":["家世","才华"],"dims":{"家世":2,"才华":1},"feedback":"暖耳做成，滚边齐整，连挑剔的嬷嬷都挑不出错。","source":"新妇以女红见重于姑，见《梦粱录》记嫁娶针线。"},{"text":"让巧手的丫鬟代做","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"母亲摸出针脚不对：「你的心意，能找人代吗？」","source":"女红须亲制，见《仪礼》妇功。"}],"difficulty":2,"npc":["母亲","嬷嬷"],"foreshadow":"暖耳"},{"id":"C-030-未","branch":"C","stage":2,"day":30,"shichen":"未时","checkpoint":"赵家回礼","scene":"赵家送年礼来了，单子末尾另有一件不相干的东西——一卷碑帖的拓片，指名给「李家娘子清赏」。","options":[{"text":"收下郑重道谢","correct":true,"tags":["情缘","才华","感情"],"dims":{"情缘":2,"才华":1},"feedback":"正是相国寺那卷碑的拓片。他懂你。","source":"士人以碑帖相赠为雅事，见《金石录后序》。"},{"text":"怕嫌疑执意退回","correct":false,"tags":["名声","感情"],"dims":{"名声":1},"feedback":"父亲却说：「君子之赠，退之不恭。收下。」","source":"通家之好不避小物，见《仪礼》馈遗之义。"}],"difficulty":2,"npc":["母亲","父亲"],"foreshadow":"拓片定情"},{"id":"C-030-戌","branch":"C","stage":2,"day":30,"shichen":"戌时","checkpoint":"对帖如对人","scene":"夜里你把那卷拓片展开又卷起，卷起又展开。笔画瘦硬，如见其人。","options":[{"text":"在册尾题一行小字","correct":true,"tags":["才华","情缘"],"dims":{"才华":1,"情缘":2},"feedback":"「岁末得此，如对古人。」——其实你知道对的是谁。","source":"题跋以志岁月，见《金石录后序》记题跋之例。"},{"text":"收入奁册最上层","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"它躺在奁册第一页，成了你嫁妆里第一件「心头物」。","source":"书画入奁，见《金石录后序》。"}],"difficulty":1,"npc":null,"foreshadow":"奁册第一页","flavor":true},{"id":"C-031","branch":"C","stage":2,"day":31,"shichen":"辰时","checkpoint":"除夜馈岁","scene":"除夕日，家家馈岁。你照单分派各房的岁盘：果子、醎豉、压岁铜钱，一处都不能错。","options":[{"text":"照簿分派再核一遍","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"几十份岁盘无一错漏，母亲说：「今年可以放手了。」","source":"除夜馈岁盘，见《东京梦华录》记除夕。"},{"text":"交给管事媳妇去办","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"偏有一房漏了，年三十儿上门来补，面子上不好看。","source":"馈岁失礼招怨，见《梦粱录》记岁除。"}],"difficulty":2,"npc":["母亲","管事媳妇"],"foreshadow":null},{"id":"C-031-未","branch":"C","stage":2,"day":31,"shichen":"未时","checkpoint":"写桃符","scene":"午后换桃符。父亲写大门，把内院的几副留给你：「去岁是你母亲的字，今年换你的。」","options":[{"text":"写下新词当桃符","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"「千门万户曈曈日」——你的字挂上内院，比父亲那副还耐看。","source":"元日换桃符书吉语，见《东京梦华录》记元日。"},{"text":"照抄去年的旧句","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"父亲看了直摇头：「辞旧迎新，你倒好，一字未改。」","source":"桃符贵新制，见《梦粱录》记除夜。"}],"difficulty":1,"npc":["父亲"],"foreshadow":null},{"id":"C-031-戌","branch":"C","stage":2,"day":31,"shichen":"戌时","checkpoint":"守岁","scene":"守岁。一家人围着地炉，母亲说：「过了今夜，你就算进了待嫁的年份了。」窗外爆竹声一阵密似一阵。","options":[{"text":"陪双亲坐到五更","correct":true,"tags":["家世","情缘"],"dims":{"家世":1,"情缘":1},"feedback":"五更鼓响，父亲忽然说：「明年此时，你就是别人家守岁了。」满炉炭火都静了。","source":"守岁达旦，见《东京梦华录》记除夕守岁。"},{"text":"熬不住先去睡了","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"第二日母亲笑你：「在娘家最后一个守岁夜，你倒先睡了。」","source":"守岁以终年为孝，见《梦粱录》。"}],"difficulty":1,"npc":["父亲","母亲"],"foreshadow":"在娘家最后一年"},{"id":"C-032","branch":"C","stage":2,"day":32,"shichen":"辰时","checkpoint":"元日拜年","scene":"元日。晨起换新衣，先给父母拜年，再随母亲往各房贺正。满城爆竹纸红得像落了一场花。","options":[{"text":"依长幼次序行礼","correct":true,"tags":["家世","名声"],"dims":{"家世":1,"名声":1},"feedback":"长辈们给的压岁物比往年都厚——待嫁的姑娘，人人多疼三分。","source":"元日贺岁，见《东京梦华录》记正月年节。"},{"text":"偷懒少拜了两房","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"那两房的婶娘记到了清明：「大姑娘了，礼数反倒短了。」","source":"贺岁不可缺礼，见《梦粱录》记元旦。"}],"difficulty":1,"npc":["母亲","族中长辈"],"foreshadow":null},{"id":"C-032-未","branch":"C","stage":2,"day":32,"shichen":"未时","checkpoint":"屠苏酒","scene":"家中饮屠苏酒，规矩是从年少者饮起。轮到你时，母亲说：「明年此时，你就是赵家席上的人了。」","options":[{"text":"饮罢祝双亲康宁","correct":true,"tags":["家世","情缘"],"dims":{"家世":1,"情缘":1},"feedback":"一句话说得母亲眼圈红了，父亲连道「好、好」。","source":"屠苏酒幼者先饮，见《东京梦华录》记元日饮屠苏。"},{"text":"嫌药味只抿一口","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"嬷嬷在旁念叨：「屠苏不饮尽，一年病不离。」","source":"饮屠苏辟邪，见《梦粱录》。"}],"difficulty":1,"npc":["母亲","父亲"],"foreshadow":null},{"id":"C-032-戌","branch":"C","stage":2,"day":32,"shichen":"戌时","checkpoint":"元夕将近","scene":"晚间母亲翻着历书说：「再过几日就是上元。今年特许你随家眷去看灯——过了年，你也是要看一回灯的人了。」","options":[{"text":"问可要备什么","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"母亲笑了：「备一双好眼睛。汴京的上元，看不够。」","source":"上元灯节士女游观，见《东京梦华录》记元宵。"},{"text":"说灯会有什么好看","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"丫鬟在旁急了：「娘子没去过不知道，那才是汴京的脸面！」","source":"元宵为都中第一盛会，见《武林旧事》记元夕。"}],"difficulty":1,"npc":["母亲","丫鬟"],"foreshadow":"上元看灯"},{"id":"C-033","branch":"C","stage":2,"day":33,"shichen":"辰时","checkpoint":"赵家贺年","scene":"初三，赵家父子来贺年。你依礼在屏后奉茶，听见那年轻人向父亲求观新得的碑拓，声音清朗。","options":[{"text":"奉茶后安静退下","correct":true,"tags":["名声","情缘"],"dims":{"名声":1,"情缘":1},"feedback":"屏风上映着他的影子，长身玉立。你退下时，心跳得厉害。","source":"闺秀奉客以屏为隔，见《仪礼》内外之制。"},{"text":"忍不住多看了一眼","correct":false,"tags":["情缘","名声"],"dims":{"情缘":2,"名声":1},"feedback":"隔着屏纱看不真切，只记得一身青衫，和一双很亮的眼睛。","source":"屏后窥客为闺阁常情，见《琅嬛记》。"}],"difficulty":2,"npc":["赵家公子","父亲"],"foreshadow":"屏后一见"},{"id":"C-033-未","branch":"C","stage":2,"day":33,"shichen":"未时","checkpoint":"题画之请","scene":"前厅父亲取出新得的一幅《寒林图》共赏。你隔着屏风听见赵家公子说了句：「此画有诗意，恨不能题。」","options":[{"text":"提笔拟一首题画诗","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"写好了没敢送出去，只压在自己案头——有些心意，还没到见人的时候。","source":"宋人题画诗为雅事，见《金石录后序》记书画题跋。"},{"text":"只记下他说的话","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"「此画有诗意」四个字，你在心里题了一百遍。","source":"闺中情思，见《琅嬛记》。"}],"difficulty":2,"npc":["父亲","赵家公子"],"foreshadow":"题画诗"},{"id":"C-033-戌","branch":"C","stage":2,"day":33,"shichen":"戌时","checkpoint":"父亲品评","scene":"晚间父亲忽然说：「赵家这孩子，谈碑论画，句句在行。配你，不辱没。」","options":[{"text":"垂首说全凭父亲","correct":true,"tags":["家世","情缘"],"dims":{"家世":1,"情缘":2},"feedback":"父亲笑了：「嘴上说全凭我，耳朵红成这样做什么？」","source":"父为女相婿，见《仪礼》婚义。"},{"text":"问他酒量如何","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"父亲一愣，大笑：「你母亲教的么？头一样先问能不能喝！」","source":"相婿之问，见《琅嬛记》谐语。"}],"difficulty":1,"npc":["父亲"],"foreshadow":null},{"id":"C-034","branch":"C","stage":2,"day":34,"shichen":"辰时","checkpoint":"议相看","scene":"王媒婆来传话：赵太丞夫人想「相看相看」。母亲一口应下，回头对你说：「这一关过了，亲事就铁了。」","options":[{"text":"问相看要备什么","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"母亲道：「什么都不用备。她要看的，就是平日里的你。」","source":"相媳妇即女家受男方母眷相看，见《东京梦华录》记娶妇。"},{"text":"紧张得手脚冰凉","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"母亲点你额头：「没出息。你平日的涵养呢？」","source":"闺秀以镇静为贵，见《仪礼》妇容。"}],"difficulty":2,"npc":["王媒婆","母亲"],"foreshadow":"相看之日"},{"id":"C-034-未","branch":"C","stage":2,"day":34,"shichen":"未时","checkpoint":"嬷嬷授机宜","scene":"老嬷嬷把你拉到一边传授机宜：「夫人若考你活计，别逞能；若考你诗书，别藏拙。记住，丈母娘看媳妇，看的是实在。」","options":[{"text":"把话句句记下","correct":true,"tags":["家世","自主"],"dims":{"家世":1,"自主":1},"feedback":"你在心里过了三遍：不逞能，不藏拙，要实在。","source":"相看考较妇德妇言妇功，见《梦粱录》记嫁娶。"},{"text":"笑嬷嬷想太多","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"嬷嬷急得直拍腿：「娘子哎，这是关杀（关键）！」","source":"老仆多谙婚事关节，见《琅嬛记》。"}],"difficulty":1,"npc":["嬷嬷"],"foreshadow":"相看机宜"},{"id":"C-034-戌","branch":"C","stage":2,"day":34,"shichen":"戌时","checkpoint":"择衣之夜","scene":"相看定在初八。前一夜，母亲和你把衣裳铺了一床：哪件显得端重，哪件显得太俏，挑了半宿。","options":[{"text":"选藕色衫配素裙","correct":true,"tags":["家世","名声"],"dims":{"家世":1,"名声":1},"feedback":"母亲拍板：「就是这身。端庄里透出干净，错不了。」","source":"相看服饰宜淡雅端重，见《周氏墓》出土女装色样。"},{"text":"想穿那身新红衫","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"母亲收了红衫：「相看穿红，浮。压箱底去。」","source":"服饰以色分场合，见《宋会要辑稿》服制。"}],"difficulty":1,"npc":["母亲"],"foreshadow":null},{"id":"C-035","branch":"C","stage":2,"day":35,"shichen":"辰时","checkpoint":"相看之日","scene":"初八。赵太丞夫人到了。她拉着你的手上下看，问的第一句是：「姑娘平日在家，做些什么？」","options":[{"text":"答读书针线帮理家","correct":true,"tags":["家世","名声"],"dims":{"家世":2,"名声":1},"feedback":"夫人点头：「帮理家事」四个字，比什么诗名都中听。","source":"相看首重妇职，见《东京梦华录》记相媳妇。"},{"text":"答最爱填词读史","correct":false,"tags":["才华","名声"],"dims":{"才华":2,"名声":1},"feedback":"夫人笑容没变，眼底却掠过一丝犹疑——词名太盛，是福是祸？","source":"相看忌才名过露，见《宋会要辑稿》婚礼议德。"}],"difficulty":3,"npc":["赵夫人","母亲"],"foreshadow":"夫人之疑"},{"id":"C-035-未","branch":"C","stage":2,"day":35,"shichen":"未时","checkpoint":"奉茶考较","scene":"夫人留下用茶。你亲自点茶奉上，盏里的沫饽又细又匀。夫人接过，忽然问：「这汤候得几分熟？」","options":[{"text":"答蟹眼已过鱼眼生","correct":true,"tags":["家世","才华"],"dims":{"家世":1,"才华":1},"feedback":"夫人啜了一口，对母亲笑道：「这盏茶，我挑不出毛病。」","source":"点茶候汤之辨，见《东京梦华录》茶事。"},{"text":"答是嬷嬷教的规矩","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"答得老实，可夫人想听的不是规矩，是你自己懂不懂。","source":"相看考较亲身技艺，见《梦粱录》。"}],"difficulty":2,"npc":["赵夫人"],"foreshadow":null},{"id":"C-035-戌","branch":"C","stage":2,"day":35,"shichen":"戌时","checkpoint":"相看落定","scene":"送走客人，王媒婆连夜来报：赵夫人回去只说了四个字——「端庄，有才」。相看，过了。","options":[{"text":"与父母报喜","correct":true,"tags":["情缘","家世"],"dims":{"情缘":2,"家世":1},"feedback":"母亲合掌念佛，父亲捻须不语，眼里都是笑。","source":"相看过后议婚成，见《东京梦华录》记娶妇次第。"},{"text":"回房大哭了一场","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"也不知是欢喜还是害怕，哭完了，心里反倒踏实了。","source":"闺中情态，见《琅嬛记》。"}],"difficulty":1,"npc":["王媒婆","母亲"],"foreshadow":"亲事铁定","flavor":true},{"id":"C-036","branch":"C","stage":2,"day":36,"shichen":"辰时","checkpoint":"相看之后","scene":"相看过了，日子忽然闲下来。晨起对镜，丫鬟一边梳头一边笑：「娘子这几日，眉眼都不一样了。」","options":[{"text":"问她哪里不一样","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"「说不上来。」丫鬟想了想，「像是心里有了着落。」","source":"闺中情态，见《琅嬛记》。"},{"text":"嗔她多嘴","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"丫鬟缩缩脖子，可铜镜里你自己的嘴角，也是翘着的。","source":"闺中谐语，见《琅嬛记》。"}],"difficulty":1,"npc":["丫鬟"],"foreshadow":null},{"id":"C-036-未","branch":"C","stage":2,"day":36,"shichen":"未时","checkpoint":"学备奁衣","scene":"母亲开库选料做奁衣。她说嫁衣要备四季八套，连「三日回门」穿哪身都要提早定。","options":[{"text":"逐身试过记下尺寸","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"针线娘子量体时直夸：「娘子这身形，穿什么都好看。」","source":"嫁衣奁衣之备，见《梦粱录》记嫁娶。"},{"text":"嫌繁琐试两身就烦","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"母亲把你按回绣墩：「今日烦一寸，出阁那日就乱一尺。」","source":"奁具以先期周备为贵，见《东京梦华录》记嫁娶。"}],"difficulty":1,"npc":["母亲","针线娘子"],"foreshadow":"奁衣"},{"id":"C-036-戌","branch":"C","stage":2,"day":36,"shichen":"戌时","checkpoint":"灯下读礼","scene":"晚间母亲让你读《仪礼·士昏礼》。「六礼你都经过一半了，后头的一半，要读在事前。」","options":[{"text":"逐节读并问疑义","correct":true,"tags":["才华","家世"],"dims":{"才华":1,"家世":1},"feedback":"读到「妇至，婿揖妇以入」，你的声音不知不觉轻了下去。","source":"士昏礼亲迎以下诸节，见《仪礼》。"},{"text":"跳读只看亲迎一节","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"母亲笑骂：「哪有这样读书的！前头纳征请期都跳过？」","source":"读礼贵循序，见《仪礼》注疏。"}],"difficulty":2,"npc":["母亲"],"foreshadow":"士昏礼"},{"id":"C-037","branch":"C","stage":2,"day":37,"shichen":"辰时","checkpoint":"上元备妆","scene":"正月十五，上元夜。家里早早吃了饭，母亲亲自替你梳妆：「汴京一年就这一夜，满城男女都上街。」","options":[{"text":"淡妆梳同心髻","correct":true,"tags":["家世","名声"],"dims":{"家世":1,"名声":1},"feedback":"母亲给你鬓边簪上一朵小小的灯草花：「去了。」","source":"元夕妇女簪戴出游，见《武林旧事》记元夕。"},{"text":"想戴满头珠翠","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"母亲拦住：「灯节人多手杂，珠翠招贼也招眼。」","source":"元夕出游忌重饰，见《武林旧事》。"}],"difficulty":1,"npc":["母亲"],"foreshadow":"上元夜"},{"id":"C-037-未","branch":"C","stage":2,"day":37,"shichen":"未时","checkpoint":"灯山初上","scene":"灯初上。宣德楼前灯山万盏，金莲灯、走马灯、水灯，照得半座城如白昼。你随家眷沿御街缓缓行。","options":[{"text":"逐样看逐样问","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"走马灯上转的竟是「唐明皇游月宫」，你站着看了一整圈。","source":"元夕灯山万灯罗列，见《东京梦华录》记元宵灯山。"},{"text":"只顾找人少处躲","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"母亲拉你：「躲什么？这一年的好灯，就看今夜！」","source":"元夕倾城出游，见《武林旧事》。"}],"difficulty":1,"npc":["母亲"],"foreshadow":null},{"id":"C-037-戌","branch":"C","stage":2,"day":37,"shichen":"戌时","checkpoint":"灯夜即景","scene":"月上柳梢，灯影人声，满城如沸。你立在桥上看了一阵，心里忽然酿出一句话——「暖日晴风初破冻，柳眼梅腮，已觉春心动」。","options":[{"text":"把这句词默记在心","correct":true,"tags":["才华","情缘"],"dims":{"才华":2,"情缘":1},"feedback":"春心动。是春的，也是你的。你没有说出口。","source":"元夕感春为词家常题，见《琅嬛记》。"},{"text":"说与身旁丫鬟听","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"丫鬟只记住了「春心动」三个字，笑你：「娘子想姑爷了。」","source":"闺中谐谑，见《琅嬛记》。"}],"difficulty":1,"npc":["丫鬟"],"foreshadow":"上元词","flavor":true,"yishou":true},{"id":"C-038","branch":"C","stage":2,"day":38,"shichen":"辰时","checkpoint":"灯谜请柬","scene":"灯节第二日，几家世交女眷约在府里猜灯谜，也给你下了帖子。母亲准你去：「散散心也好。」","options":[{"text":"先温几则灯谜再去","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"到了席上，谜面一出你便连中三元，满座都敬你三分。","source":"元夕后猜谜为文戏，见《武林旧事》记灯品灯谜。"},{"text":"空手赴会","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"一轮下来你只猜中一个，倒也不丢人，只是有些闷闷的。","source":"灯谜以敏捷为上，见《武林旧事》。"}],"difficulty":2,"npc":["世交女眷"],"foreshadow":null},{"id":"C-038-未","branch":"C","stage":2,"day":38,"shichen":"未时","checkpoint":"谜会藏锋","scene":"猜到后来，一位夫人出谜打趣你：「谜面是『词女』，打一事——姑娘猜猜？」满座都笑看你。","options":[{"text":"答好事近","correct":true,"tags":["才华","名声"],"dims":{"才华":1,"名声":1},"feedback":"夫人拊掌：「答得妙！」——「好事近」，是词牌，也是你的事。","source":"词牌入谜为席上雅戏，见《琅嬛记》。"},{"text":"装猜不着","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你低了头，满座的笑更响了——这事儿，藏不住了。","source":"闺名外传为谈资，见《琅嬛记》。"}],"difficulty":2,"npc":["世交夫人"],"foreshadow":"词女之名"},{"id":"C-038-戌","branch":"C","stage":2,"day":38,"shichen":"戌时","checkpoint":"灯节余韵","scene":"夜里回想这两日的灯与人，你在小笺上记：「元夕之盛，盛不在灯，在一城的人都在兴头上。」","options":[{"text":"又添一句人与灯","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"「灯看人，人看灯。」写完你自己先笑了。","source":"记元夕者众，见《东京梦华录》元宵诸条。"},{"text":"搁笔听远远鼓声","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"城那头的灯还没散。你想，来年此时，你会在谁家看灯？","source":"闺中情思，见《琅嬛记》。"}],"difficulty":1,"npc":null,"foreshadow":null,"flavor":true},{"id":"C-039","branch":"C","stage":2,"day":39,"shichen":"辰时","checkpoint":"赵家回话","scene":"王媒婆来传赵家的话：相看甚满意，婚期照旧，只一样——赵夫人说「媳妇有才名是好事，望她过门后多陪我家那痴儿读书」。","options":[{"text":"说这正是我愿","correct":true,"tags":["情缘","才华"],"dims":{"情缘":2,"才华":1},"feedback":"话出口你才觉出害臊，母亲和王媒婆都笑了。","source":"士人家娶妇重同志，见《金石录后序》记夫妇同好。"},{"text":"垂首不语","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"媒婆笑道：「娘子不言语，就是千肯万肯了。」","source":"闺秀默许之态，见《琅嬛记》。"}],"difficulty":1,"npc":["王媒婆","母亲"],"foreshadow":"同好之约","flavor":true},{"id":"C-039-未","branch":"C","stage":2,"day":39,"shichen":"未时","checkpoint":"两家换帖","scene":"两家正式换定帖。男家帖上写三代名讳、田宅、官职；女家帖上写你的生辰、奁产数目。一换定帖，再无反悔。","options":[{"text":"听母亲念定帖","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"「赵氏」「李氏」两家姓氏落在纸上，你的婚事，白纸黑字定了。","source":"换定帖即定亲，见《东京梦华录》记娶妇定帖。"},{"text":"不敢听躲进里间","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"母亲进来寻你：「躲什么？这是你的大事，该听。」","source":"定帖为婚约之信，见《梦粱录》。"}],"difficulty":2,"npc":["母亲","王媒婆"],"foreshadow":"定帖"},{"id":"C-039-戌","branch":"C","stage":2,"day":39,"shichen":"戌时","checkpoint":"定帖之夜","scene":"夜里你取出那卷碑帖拓片，就着灯又看了一遍。定帖也换了，这个押玉佩买碑的人，往后就是你的良人了。","options":[{"text":"把拓片收入奁册","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"收入前你又看了一眼。「奁册第一页」——这个位置，永远是它的。","source":"书画入奁，见《金石录后序》。"},{"text":"提笔为拓片题跋","correct":true,"tags":["才华","情缘"],"dims":{"才华":1,"情缘":1},"feedback":"你只题了年月，没敢题名。可这笔字，他早晚认得出。","source":"题跋志岁月，见《金石录后序》。"}],"difficulty":1,"npc":null,"foreshadow":"奁册第一页","flavor":true},{"id":"C-040","branch":"C","stage":2,"day":40,"shichen":"辰时","checkpoint":"见过世面","scene":"晨起梳妆，你忽然发现镜中的人不一样了——及笄、提亲、风波、相看、定帖，这几十天把你从女孩磨成了「见过世面」的待嫁娘子。","options":[{"text":"对镜郑重一拜","correct":true,"tags":["自主","家世"],"dims":{"自主":1,"家世":1},"feedback":"这一拜，是谢爹娘，也是谢这些日子里没慌没乱的自己。","source":"闺中自励，见《琅嬛记》。"},{"text":"去给父母请早安","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"母亲看你神清气定，点头道：「像个要当家理事的样子了。」","source":"妇德以安定为贵，见《仪礼》。"}],"difficulty":1,"npc":["母亲"],"foreshadow":"里程碑·见过世面","flavor":true},{"id":"C-040-未","branch":"C","stage":2,"day":40,"shichen":"未时","checkpoint":"嬷嬷盘点","scene":"老嬷嬷掰着指头替你盘点这几十天：「课也上了，亲也定了，世面也见了。娘子如今缺的，就剩一门——出阁前的规矩课。」","options":[{"text":"问规矩课教什么","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"嬷嬷眯眼笑：「教你怎么做媳妇，怎么做主母，怎么做娘。」","source":"嫁前教以妇道，见《仪礼》婚前之教。"},{"text":"说这些母亲都教了","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"嬷嬷摇头：「夫人教的是娘家的理，老身教的是婆家的道。不一样。」","source":"妇道之别，见《仪礼》妇事舅姑。"}],"difficulty":1,"npc":["嬷嬷"],"foreshadow":"规矩课"},{"id":"C-040-戌","branch":"C","stage":2,"day":40,"shichen":"戌时","checkpoint":"夜话将来","scene":"晚间母亲在你房中坐了许久。她说：「往后的日子，娘教你的会越来越快——因为能教你的日子，越来越少了。」","options":[{"text":"说女儿会用心学","correct":true,"tags":["家世","情缘"],"dims":{"家世":2,"情缘":1},"feedback":"母亲拍拍你的手背，什么也没再说。烛花爆了一声。","source":"母女惜别之情，见《琅嬛记》。"},{"text":"强笑说日子还长","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"母亲看了你一会儿：「傻孩子，日子是一天天短下去的。」","source":"待嫁惜时，见《琅嬛记》。"}],"difficulty":1,"npc":["母亲"],"foreshadow":"规矩课"},{"id":"C-041","branch":"C","stage":2,"day":41,"shichen":"辰时","checkpoint":"春日园戏","scene":"春来。你在园中荡秋千，罗衣轻飏，蹴罢秋千，起来慵整纤纤手。正喘息着，墙外忽有马蹄声由远而近。","options":[{"text":"下秋千整理衣衫","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"你刚拢好鬓发，墙外的马蹄声却在门前停住了。","source":"闺中园戏见客须整仪，见《仪礼》妇容。"},{"text":"不管不顾再荡一回","correct":false,"tags":["自主"],"dims":{"自主":2},"feedback":"秋千荡得正高，门房来报：「赵家公子奉父命来送东西。」","source":"春日园戏，见《琅嬛记》记闺中秋千。"}],"difficulty":2,"npc":["丫鬟","门房"],"foreshadow":"青梅初见"},{"id":"C-041-未","branch":"C","stage":2,"day":41,"shichen":"未时","checkpoint":"倚门回首","scene":"他随父亲在前厅。你本要回避，走到院门边，却鬼使神差地回了头——「见有人来，袜刬金钗溜，和羞走。倚门回首，却把青梅嗅。」","options":[{"text":"嗅着青梅不敢回看","correct":true,"tags":["情缘","感情"],"dims":{"情缘":3},"feedback":"青梅的酸涩沾在指尖，你看清了他，又好像什么也没看清。","source":"闺中情态，见《琅嬛记》。"},{"text":"快步回到内院","correct":true,"tags":["名声","感情"],"dims":{"名声":1,"情缘":1},"feedback":"回到内院，心还在跳。方才那一眼，太短，也太长。","source":"男女避面之礼，见《仪礼》。"}],"difficulty":1,"npc":["赵家公子","父亲"],"foreshadow":"青梅词","flavor":true,"yishou":true},{"id":"C-041-戌","branch":"C","stage":2,"day":41,"shichen":"戌时","checkpoint":"青梅入词","scene":"夜里你翻来覆去，白日那一幕在眼前过了几十遍。索性披衣起来，把「倚门回首」的心事写进了小词。","options":[{"text":"写完仔细藏进奁底","correct":true,"tags":["才华","情缘"],"dims":{"才华":2,"情缘":1},"feedback":"这一阕，不传，不抄，不给任何人看——至少现在。","source":"闺词有秘不示人者，见《琅嬛记》。"},{"text":"写完自己先臊得慌","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"臊归臊，笔却停不下来。原来心动是藏不住的。","source":"闺中情思，见《琅嬛记》。"}],"difficulty":1,"npc":null,"foreshadow":"青梅词"},{"id":"C-042","branch":"C","stage":2,"day":42,"shichen":"辰时","checkpoint":"规矩课开讲","scene":"老嬷嬷的规矩课正式开讲。头一课：「进了婆家门，头三个月最要紧。晨昏定省，比鸡早，比佛诚。」","options":[{"text":"问定省的细处","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"嬷嬷细讲：问安的时辰、站立的位置、回话的字数，一一有谱。","source":"妇事舅姑晨昏定省，见《仪礼》。"},{"text":"说这些我都懂","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"嬷嬷冷笑：「懂和做到，隔着一辈子呢。」","source":"知易行难，见《仪礼》义疏。"}],"difficulty":1,"npc":["嬷嬷"],"foreshadow":"规矩课"},{"id":"C-042-未","branch":"C","stage":2,"day":42,"shichen":"未时","checkpoint":"规矩课二","scene":"第二课讲「话」：「在婆家，话分三种——必须说的、可说的、烂在肚里的。娘子分分看。」","options":[{"text":"答委屈烂在肚里","correct":true,"tags":["自主","家世"],"dims":{"自主":1,"家世":1},"feedback":"嬷嬷点头又摇头：「对了一半。大委屈回娘家说，小委屈才烂在肚里。」","source":"妇言以慎为德，见《仪礼》妇言。"},{"text":"答该说就说","correct":false,"tags":["自主"],"dims":{"自主":2},"feedback":"嬷嬷叹气：「这样的人家媳妇，三年要吃十年的亏。」","source":"妇言贵慎，见《仪礼》。"}],"difficulty":2,"npc":["嬷嬷"],"foreshadow":null},{"id":"C-042-戌","branch":"C","stage":2,"day":42,"shichen":"戌时","checkpoint":"夜读女诫","scene":"晚间你翻出《女诫》，往日读它只觉得闷，今日重读「卑弱」「敬顺」，忽然读出些别的滋味。","options":[{"text":"批注自己的见解","correct":true,"tags":["才华","自主"],"dims":{"才华":1,"自主":1},"feedback":"你在页边写：「敬顺非卑，以敬立身，以顺处世。」","source":"《女诫》为宋闺训要籍，见《仪礼》妇学相承之教。"},{"text":"读三行便打瞌睡","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"嬷嬷明日要考，你只好强撑着又点了一根烛。","source":"闺训日课，见《琅嬛记》。"}],"difficulty":2,"npc":null,"foreshadow":"女诫批注"},{"id":"C-043","branch":"C","stage":2,"day":43,"shichen":"辰时","checkpoint":"学乘轿马","scene":"嬷嬷说新妇回门要乘轿，走亲戚要乘车，上下轿的仪态都有讲究。你抬着裙角在院里练了一上午。","options":[{"text":"练到不扶不晃","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"落轿、敛袖、垂目、移步，一套做下来行云流水，嬷嬷直呼「成了」。","source":"妇人乘舆之仪，见《东京梦华录》记舆轿之制。"},{"text":"笑这些虚礼无用","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"嬷嬷正色：「头一日下轿失了态，满汴京的婆子能笑你三年。」","source":"新妇仪态为众目所瞩，见《梦粱录》记亲迎。"}],"difficulty":1,"npc":["嬷嬷"],"foreshadow":null},{"id":"C-043-未","branch":"C","stage":2,"day":43,"shichen":"未时","checkpoint":"春日游宴","scene":"族中女眷在别业办春日小宴，有投壶、有斗茶。你与族妹一队斗茶，对手是族里有名的厉害婶娘。","options":[{"text":"稳着点茶以质胜","correct":true,"tags":["才华","家世"],"dims":{"才华":1,"家世":1},"feedback":"你的茶汤咬盏最久，婶娘认赌服输：「这手艺，赵家婆婆有福了。」","source":"斗茶以水痕先退为负，见《东京梦华录》茶事。"},{"text":"求快失手泼了盏","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"茶泼了半裙，你强笑着退席——春宴的第一件糗事。","source":"斗茶贵稳，见《梦粱录》。"}],"difficulty":2,"npc":["族中婶娘","族妹"],"foreshadow":null},{"id":"C-043-戌","branch":"C","stage":2,"day":43,"shichen":"戌时","checkpoint":"宴归夜话","scene":"宴罢归家，母亲说今日席上人人夸你，也有人问「词还写不写」。她问你：「你自己怎么想？」","options":[{"text":"答写但不轻传","correct":true,"tags":["才华","自主"],"dims":{"才华":1,"自主":1},"feedback":"母亲点头：「笔是你的，传不传，也是你的。这个分寸，把得好。」","source":"闺词传与不传之辨，见《琅嬛记》。"},{"text":"答过门后便不写","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"母亲却道：「倒也不必。你是你，词是词，别丢了。」","source":"才不可废，见《金石录后序》记文事相得。"}],"difficulty":2,"npc":["母亲"],"foreshadow":"词之存废"},{"id":"C-044","branch":"C","stage":2,"day":44,"shichen":"辰时","checkpoint":"卖花声里","scene":"清明前后，汴京满城卖花声。一早巷口传来叫卖，丫鬟买回一枝含苞的春花，还带着露水。","options":[{"text":"插花对镜比一比","correct":true,"tags":["才华","情缘"],"dims":{"才华":1,"情缘":1},"feedback":"「卖花担上，买得一枝春欲放」——花也精神，你也精神。","source":"汴京清明卖花满市，见《东京梦华录》记清明。"},{"text":"让丫鬟插到瓶中","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"花插在瓶里，你隔窗看了一会儿，到底还是过去扶正了它。","source":"闺中插花之好，见《梦粱录》记花事。"}],"difficulty":1,"npc":["丫鬟"],"foreshadow":"卖花词","flavor":true,"yishou":true},{"id":"C-044-未","branch":"C","stage":2,"day":44,"shichen":"未时","checkpoint":"清明家祭","scene":"清明家祭，你随父母出城扫墓。纸灰飞作白蝴蝶，母亲一路说起外祖母当年的旧事。","options":[{"text":"扶母亲细听她讲","correct":true,"tags":["家世","情缘"],"dims":{"家世":1,"情缘":1},"feedback":"母亲说完叹道：「你出嫁后，这样的路，娘就不能陪你走了。」","source":"清明扫墓出城，见《东京梦华录》记清明节。"},{"text":"只顾看陌上春色","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"春色是好春色，只是母亲的旧事，你错过了就没处补了。","source":"祭扫以哀思为本，见《仪礼》祭义。"}],"difficulty":1,"npc":["母亲","父亲"],"foreshadow":null},{"id":"C-044-戌","branch":"C","stage":2,"day":44,"shichen":"戌时","checkpoint":"夜祭词","scene":"夜归。你把白日的纸灰、春色和母亲的话揉在一起，写了一阕清明词。写完读了一遍，自己先湿了眼眶。","options":[{"text":"把词焚在外祖母灵位前","correct":true,"tags":["情缘","才华"],"dims":{"情缘":1,"才华":1},"feedback":"纸灰飞起，像一只白蝴蝶。外祖母若识字，一定会夸你。","source":"焚词告祭为闺中私礼，见《琅嬛记》。"},{"text":"收进奁册","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"奁册又厚了一页。你的嫁妆，一半是物，一半是这些字。","source":"闺词入奁，见《琅嬛记》。"}],"difficulty":1,"npc":null,"foreshadow":null},{"id":"C-045","branch":"C","stage":2,"day":45,"shichen":"辰时","checkpoint":"赵公子来访","scene":"赵家公子又来拜访父亲，这回带了一册新得的金石拓本求教。父亲唤你：「去，把你挑的那几张帖取来同看。」","options":[{"text":"取帖奉茶依礼周旋","correct":true,"tags":["家世","名声"],"dims":{"家世":1,"名声":1},"feedback":"你放下帖子便退。他道了谢，声音比礼数更郑重。","source":"通家之女得周旋于客次，见《仪礼》馈遗之义。"},{"text":"借故多留了一刻","correct":false,"tags":["情缘","名声"],"dims":{"情缘":2,"名声":1},"feedback":"父亲咳了一声。你退下时，耳根烧了一路。","source":"闺秀不久留客次，见《仪礼》。"}],"difficulty":3,"npc":["赵家公子","父亲"],"foreshadow":"金石论交"},{"id":"C-045-未","branch":"C","stage":2,"day":45,"shichen":"未时","checkpoint":"金石之谈","scene":"前厅的谈笑声隐隐传来。父亲说「此碑当在元祐年间」，那年轻人接「碑阴有渤损，拓工却极好」。你立在廊下听入了神。","options":[{"text":"记下他们的论碑要点","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"「碑阴渤损」四个字，你回头就查——下回，你也想接得上话。","source":"金石考据之学，见《金石录后序》记考碑。"},{"text":"只听了个人声热闹","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"学问没记住，只记住他说话时，语速一快就有点急，很可爱。","source":"闺中情态，见《琅嬛记》。"}],"difficulty":2,"npc":["父亲","赵家公子"],"foreshadow":"论碑"},{"id":"C-045-戌","branch":"C","stage":2,"day":45,"shichen":"戌时","checkpoint":"父亲论婿","scene":"送走客人，父亲对你说：「这孩子论碑的眼力，在我那些同年之上。你们往后，有的可谈。」","options":[{"text":"问父亲可还满意","correct":true,"tags":["情缘","家世"],"dims":{"情缘":1,"家世":1},"feedback":"父亲笑了：「我若不满意，今日这帖子就不会让你送出来。」","source":"父为女择同志之配，见《金石录后序》记夫妇同好。"},{"text":"说我也想学考碑","correct":false,"tags":["才华"],"dims":{"才华":2},"feedback":"父亲大喜：「好！从明日起，每日教你看一张拓片。」","source":"家学相传，见《金石录后序》。"}],"difficulty":1,"npc":["父亲"],"foreshadow":"日课考碑"},{"id":"C-046","branch":"C","stage":2,"day":46,"shichen":"辰时","checkpoint":"考碑日课","scene":"父亲果真开了考碑日课。头一日讲《石鼓文》拓本，从字形讲到拓工，你听得两眼发亮。","options":[{"text":"当堂问出三个疑义","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"父亲答了两个，第三个他自己也要查：「问得好，明日给你答案。」","source":"金石日课，见《金石录后序》记考订之乐。"},{"text":"怕露怯只听不问","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"父亲道：「学问不问，如灯不点。下回须问。」","source":"问学之法，见《续资治通鉴长编》记太学学规。"}],"difficulty":2,"npc":["父亲"],"foreshadow":"考碑日课"},{"id":"C-046-未","branch":"C","stage":2,"day":46,"shichen":"未时","checkpoint":"习帖进益","scene":"午后临帖，你忽然发现手不抖了——《兰亭》的那几个「之」字，个个有了筋骨。","options":[{"text":"把进益说与父亲","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"父亲看了半晌：「笔随人长。人是待嫁的人，字也是。」","source":"书法以日课进，见《金石录后序》记书画之乐。"},{"text":"自己偷偷高兴","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"高兴归高兴，没人指点，有几处败笔你自己看不出来。","source":"习字需师友指正，见《仪礼》师教之义。"}],"difficulty":1,"npc":["父亲"],"foreshadow":null},{"id":"C-046-戌","branch":"C","stage":2,"day":46,"shichen":"戌时","checkpoint":"夜校奁册","scene":"夜里你把奁册里的书画又理了一遍，给每件写了小签：名目、来历、心得。册子快理出章法了。","options":[{"text":"仿藏书目做凡例","correct":true,"tags":["才华","自主"],"dims":{"才华":2,"自主":1},"feedback":"凡例一成，这册子就不只是嫁妆，是一部小小的藏目了。","source":"私人藏目之例，见《金石录后序》记归来堂簿录。"},{"text":"只按大小排了排","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"排完看着齐整，可找起东西来，还是得一页页翻。","source":"簿录贵有例，见《金石录后序》。"}],"difficulty":2,"npc":null,"foreshadow":"奁册凡例"},{"id":"C-047","branch":"C","stage":2,"day":47,"shichen":"辰时","checkpoint":"词女之名","scene":"一早闺伴捎话：你的海棠词和咏絮词在汴京闺秀圈子里传遍了，大家不称你「李家姑娘」，改称「词女」了。","options":[{"text":"听了只淡淡一笑","correct":true,"tags":["名声","自主"],"dims":{"名声":2,"自主":1},"feedback":"名声这个东西，你渐渐明白了：它来时不拒，它去时不追。","source":"才名流传为闺誉，见《琅嬛记》。"},{"text":"得意连写三阕","correct":false,"tags":["才华","名声"],"dims":{"才华":2,"名声":2},"feedback":"词是好词，可传得太快太广，连茶楼的说书人都知道了。","source":"词名过盛招议，见《宋会要辑稿》婚礼议德。"}],"difficulty":2,"npc":["闺伴"],"foreshadow":"词女之名"},{"id":"C-047-未","branch":"C","stage":2,"day":47,"shichen":"未时","checkpoint":"太学传词","scene":"族兄自太学来信：「词女之词，太学诸生传抄殆遍。有人问：词女何人？吾笑而不答。」","options":[{"text":"回信谢他守口","correct":true,"tags":["名声","家世"],"dims":{"名声":1,"家世":1},"feedback":"族兄回信：「守住这个秘密，比考中经义还难。」","source":"闺词入太学，见《琅嬛记》。"},{"text":"回信让他猜猜","correct":false,"tags":["自主"],"dims":{"自主":2},"feedback":"族兄回信哭笑不得：「妹妹，这事儿能拿来玩吗？」","source":"闺名不可为戏，见《仪礼》。"}],"difficulty":2,"npc":["族兄"],"foreshadow":"词入太学"},{"id":"C-047-戌","branch":"C","stage":2,"day":47,"shichen":"戌时","checkpoint":"母亲问名","scene":"晚间母亲问你：「『词女』这个名声，如今满城都是。你说是好事还是坏事？」","options":[{"text":"答看用在何处","correct":true,"tags":["自主","才华"],"dims":{"自主":1,"才华":1},"feedback":"母亲点头：「用在笔墨上是好，用在口舌上是坏。你懂了。」","source":"才名之辨，见《琅嬛记》。"},{"text":"答是坏事要收敛","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"母亲却道：「倒也不必自废武功。刀要收在鞘里，不是熔了它。」","source":"才不废而藏，见《金石录后序》记文事。"}],"difficulty":2,"npc":["母亲"],"foreshadow":null},{"id":"C-048","branch":"C","stage":2,"day":48,"shichen":"辰时","checkpoint":"一梦传回","scene":"王媒婆清早登门，喜笑颜开：「奇事！赵家公子前夜得一梦，梦中人告他四个字——『词女之夫』！」","options":[{"text":"听罢红了脸","correct":true,"tags":["情缘","感情"],"dims":{"情缘":3},"feedback":"满汴京谁不知「词女」？这个梦，等于把心事喊上了街。","source":"梦兆之说盛行于宋，见《琅嬛记》记异闻。"},{"text":"说梦话当不得真","correct":false,"tags":["名声","感情"],"dims":{"名声":1},"feedback":"王媒婆笑得打跌：「娘子嘴上说不当真，耳朵尖都红了！」","source":"闺中情态，见《琅嬛记》。"}],"difficulty":1,"npc":["王媒婆","母亲"],"foreshadow":"词女之夫之梦"},{"id":"C-048-未","branch":"C","stage":2,"day":48,"shichen":"未时","checkpoint":"满城佳话","scene":"「词女之夫」的梦不知怎的传了出去，两家交情深的都知道了。人人说这是一桩「天定的文字姻缘」。","options":[{"text":"由它传去不加理会","correct":true,"tags":["名声","自主"],"dims":{"名声":1,"自主":1},"feedback":"佳话传了三日，反倒把衙内家那些流言彻底压了下去。","source":"佳话能辟流言，见《宋会要辑稿》清议之力。"},{"text":"担心太招摇","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"母亲宽慰你：「这门亲已是铁定的，佳话比流言好一万倍。」","source":"婚姻已定则物议不侵，见《仪礼》婚义。"}],"difficulty":2,"npc":["母亲"],"foreshadow":"文字姻缘"},{"id":"C-048-戌","branch":"C","stage":2,"day":48,"shichen":"戌时","checkpoint":"灯下遥想","scene":"夜里你想：他做了那样的梦，醒来时是什么神情？会不会也披衣坐起，把四个字在心里念了一遍又一遍？","options":[{"text":"把遥想写进词","correct":true,"tags":["情缘","才华"],"dims":{"情缘":2,"才华":1},"feedback":"词成。这一阕，也许有朝一日，你会念给他听。","source":"闺词寄怀，见《琅嬛记》。"},{"text":"笑着熄了灯","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"梦里若有四个字，你的梦里，大约也是那四个字。","source":"闺中情思，见《琅嬛记》。"}],"difficulty":1,"npc":null,"foreshadow":null,"flavor":true},{"id":"C-049","branch":"C","stage":2,"day":49,"shichen":"辰时","checkpoint":"婚期落定","scene":"两家把婚期正式敲定：来年金秋。算命的说金秋金水相生，大利「文字之合」。母亲已开始倒排嫁妆的工期。","options":[{"text":"帮母亲排工期","correct":true,"tags":["家世","自主"],"dims":{"家世":2,"自主":1},"feedback":"奁衣、木器、铜器、漆器，一样样排进月份牌，井井有条。","source":"婚期既定则奁具赶工，见《东京梦华录》记嫁娶备办。"},{"text":"只记住了金秋二字","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"母亲问你话你连问了三遍才回神——魂儿已经飞到明年秋天了。","source":"待嫁情态，见《琅嬛记》。"}],"difficulty":2,"npc":["母亲"],"foreshadow":"婚期金秋"},{"id":"C-049-未","branch":"C","stage":2,"day":49,"shichen":"未时","checkpoint":"添妆之议","scene":"族中女眷来议「添妆」的章程：哪家送头面，哪家送床帐，哪家送厨具。你的奁单眼看着又要厚三分。","options":[{"text":"逐笔登记造册","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"母亲夸你：「添妆也是人情，记清了，往后才还得清。」","source":"添妆为亲族助嫁之礼，见《梦粱录》记嫁娶。"},{"text":"说由母亲看着办","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"母亲道：「这是你的人情，你不经心，往后怎么做人？」","source":"人情须亲历，见《仪礼》馈遗之义。"}],"difficulty":1,"npc":["族中女眷","母亲"],"foreshadow":null},{"id":"C-049-戌","branch":"C","stage":2,"day":49,"shichen":"戌时","checkpoint":"灯下排奁","scene":"夜里你把奁册、奁单、添妆册摊了一桌。看着这些，你忽然明白了母亲那句话——「嫁妆是底气」。","options":[{"text":"给每册题了名字","correct":true,"tags":["才华","自主"],"dims":{"才华":1,"自主":1},"feedback":"《衣食册》《人情册》《书画册》——你的半生，都在这几册里了。","source":"奁籍之别，见《金石录后序》记簿录。"},{"text":"看着看着走了神","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"你想的是：这些册子抬进赵家那日，会是什么光景。","source":"待嫁情思，见《琅嬛记》。"}],"difficulty":1,"npc":null,"foreshadow":null},{"id":"C-050","branch":"C","stage":2,"day":50,"shichen":"辰时","checkpoint":"半年之约","scene":"晨起翻历书，距婚期还有大半年。母亲在旁道：「这大半年，是你做姑娘的最后大半年。一日都别虚过。」","options":[{"text":"应下不负光阴","correct":true,"tags":["自主","家世"],"dims":{"自主":1,"家世":1},"feedback":"你在心里给自己排了课：考碑、读书、理家、写字。","source":"惜时为闺训，见《琅嬛记》。"},{"text":"说想得心里发慌","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"母亲笑：「慌就对了。不慌的，那不是嫁人，是搬家。」","source":"待嫁之心，见《琅嬛记》谐语。"}],"difficulty":1,"npc":["母亲"],"foreshadow":"最后大半年"},{"id":"C-050-未","branch":"C","stage":2,"day":50,"shichen":"未时","checkpoint":"回望相看","scene":"午后独坐，从相国寺碑摊到倚门青梅，从「词女」之名到「词女之夫」之梦——这五十日像一轴画，徐徐展开又卷起。","options":[{"text":"把这轴画记成词","correct":true,"tags":["才华","情缘"],"dims":{"才华":2,"情缘":1},"feedback":"词里没有名字，可你自己知道，字字是谁。","source":"闺词记事，见《琅嬛记》。"},{"text":"去园中看新绿","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"柳眼梅腮，春已深了。你的春天，也深了。","source":"闺中感时，见《琅嬛记》。"}],"difficulty":1,"npc":null,"foreshadow":"阶段二毕","flavor":true},{"id":"C-050-戌","branch":"C","stage":2,"day":50,"shichen":"戌时","checkpoint":"双亲夜谈","scene":"晚间你经过父母窗下，听见父亲说：「女儿这五十日，长进比前十六年都大。」母亲答：「因为她知道要去做别人家的顶梁柱了。」","options":[{"text":"在窗外站了一会儿","correct":true,"tags":["家世","情缘"],"dims":{"家世":1,"情缘":2},"feedback":"你没有进去。有些体己话，听在窗外，比听在当面更暖心。","source":"父母之爱子，见《仪礼》亲亲之义。"},{"text":"推门进去撒娇","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"父母都笑了。这样的夜晚，过一个，少一个。","source":"闺门之乐，见《金石录后序》记闺中事。"}],"difficulty":1,"npc":["父亲","母亲"],"foreshadow":"阶段二毕","flavor":true},{"id":"C-051","branch":"C","stage":3,"day":51,"shichen":"辰时","checkpoint":"规矩课三","scene":"规矩课第三讲讲「迎送」：客人到门，迎几步、让几盏、送出门还是送到轿，按亲疏各有尺寸。","options":[{"text":"拿家中来客对照着学","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"午后正好有客，你一应一送，嬷嬷在廊下看得直点头。","source":"妇主中馈兼司迎送，见《仪礼》妇职。"},{"text":"嫌繁文缛节","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"嬷嬷道：「繁文缛节？这些就是婆家人的脸面。」","source":"礼以敬为本，见《仪礼》。"}],"difficulty":1,"npc":["嬷嬷"],"foreshadow":null},{"id":"C-051-未","branch":"C","stage":3,"day":51,"shichen":"未时","checkpoint":"学祭祀","scene":"午后学祭祀陈设：几筵怎么摆，笾豆怎么列，祝版上的字怎么写。赵家是大族，祭祀比李家还隆重。","options":[{"text":"按图样亲手摆一遍","correct":true,"tags":["家世","才华"],"dims":{"家世":1,"才华":1},"feedback":"笾豆次序一丝不乱，嬷嬷说：「这手艺，宗妇都做得。」","source":"祭器陈设之序，见《仪礼》祭礼。"},{"text":"只看不动手","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"到了真摆的时候，笾和豆还是拿反了。","source":"祭以躬亲为敬，见《仪礼》。"}],"difficulty":3,"npc":["嬷嬷"],"foreshadow":"宗妇之任"},{"id":"C-051-戌","branch":"C","stage":3,"day":51,"shichen":"戌时","checkpoint":"课毕有感","scene":"晚间你回想这一日学的：迎送、祭祀、问安。原来做别人家的媳妇，是一门比诗书还深的学问。","options":[{"text":"把课目写成条目","correct":true,"tags":["自主","才华"],"dims":{"自主":1,"才华":1},"feedback":"条目写完，你心里那本《居家须知》又厚了几页。","source":"闺中自记妇学，见《琅嬛记》。"},{"text":"感叹当女儿真好","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"话虽这么说，可你知道，女儿的日子是倒着数的。","source":"待嫁之情，见《琅嬛记》。"}],"difficulty":1,"npc":null,"foreshadow":"居家须知"},{"id":"C-052","branch":"C","stage":3,"day":52,"shichen":"辰时","checkpoint":"认亲族","scene":"母亲展开赵家的亲族图：太丞公、夫人、几房叔伯、几位妯娌，一一给你讲谁好相处、谁要敬而远之。","options":[{"text":"按图记人记性子","correct":true,"tags":["家世","自主"],"dims":{"家世":2,"自主":1},"feedback":"你默画了一张小图收进奁册——进门前先识人，进门后不吃亏。","source":"新妇先识夫家亲族，见《东京梦华录》记亲迎后庙见。"},{"text":"说见过就记住了","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"母亲考你三房的排行，你支吾了——纸上功夫省不得。","source":"识亲为妇职，见《仪礼》。"}],"difficulty":2,"npc":["母亲"],"foreshadow":"亲族图"},{"id":"C-052-未","branch":"C","stage":3,"day":52,"shichen":"未时","checkpoint":"妯娌之学","scene":"母亲重点讲妯娌：「赵家二房有两位嫂嫂。妯娌之间，不比母女，不比姐妹，要亲而有间。」","options":[{"text":"问怎样算亲而有间","correct":true,"tags":["家世","自主"],"dims":{"家世":1,"自主":1},"feedback":"母亲道：「好事让她三分，闲话一句不传，难处帮在暗处。」","source":"妯娌相处之道，见《仪礼》妇顺之训。"},{"text":"说以诚待人就好","correct":false,"tags":["自主"],"dims":{"自主":2},"feedback":"母亲摇头：「诚要诚在里头，分寸要在外头。」","source":"妇言妇行之辨，见《仪礼》。"}],"difficulty":2,"npc":["母亲"],"foreshadow":"妯娌之道"},{"id":"C-052-戌","branch":"C","stage":3,"day":52,"shichen":"戌时","checkpoint":"灯下温书","scene":"夜里温《仪礼·士昏礼》，读到「庙见」一节：新妇入门三月，方得见庙祭告祖先。你忽然觉得「三月」好长。","options":[{"text":"把三月章程排出来","correct":true,"tags":["家世","自主"],"dims":{"家世":1,"自主":1},"feedback":"哪日定省、哪日习厨、哪日庙见——你在心里先过了一遍。","source":"三月庙见之礼，见《仪礼》士昏礼。"},{"text":"合书不想了","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"不想归不想，「三月」两个字，在灯下晃了很久。","source":"待嫁情思，见《琅嬛记》。"}],"difficulty":1,"npc":null,"foreshadow":"三月庙见"},{"id":"C-053","branch":"C","stage":3,"day":53,"shichen":"辰时","checkpoint":"端午百索","scene":"五月初五，端午。一早嬷嬷给你腕上系百索，又在你衣襟别了个小香囊：「避五毒，也避小人。」","options":[{"text":"亲手给双亲也系上","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"母亲腕上的百索是你缠的，她摸了又摸。","source":"端午系百索佩香囊，见《东京梦华录》记端午。"},{"text":"嫌孩子气不肯戴","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"嬷嬷不依：「这是规矩！娘子过了门，还得给小辈们做呢。」","source":"端午佩物之俗，见《梦粱录》。"}],"difficulty":1,"npc":["嬷嬷","母亲"],"foreshadow":null},{"id":"C-053-未","branch":"C","stage":3,"day":53,"shichen":"未时","checkpoint":"裹粽试手","scene":"午时全家裹粽。去年你裹的还散，今年嬷嬷说你的手艺可以出师了——赵家那边，端午要送新妇亲手裹的角黍。","options":[{"text":"裹了二十只全合格","correct":true,"tags":["家世","才华"],"dims":{"家世":1,"才华":1},"feedback":"四角端正，绳结齐整。母亲挑了最好的十只，装进描金盒送赵家。","source":"端午角黍馈亲，见《东京梦华录》记端午物事。"},{"text":"裹了几只就手酸","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"送去赵家的角黍，到底混了几只嬷嬷的手笔。","source":"馈礼贵亲制，见《仪礼》妇功。"}],"difficulty":2,"npc":["嬷嬷","母亲"],"foreshadow":"角黍馈赵"},{"id":"C-053-戌","branch":"C","stage":3,"day":53,"shichen":"戌时","checkpoint":"赵家回礼","scene":"傍晚赵家回礼到了：一匣五色新丝缠的绣品，附一句「谢娘子角黍」。母亲笑道：「这是夫人亲手挑的。」","options":[{"text":"收礼记下这份情","correct":true,"tags":["情缘","家世"],"dims":{"情缘":1,"家世":1},"feedback":"一来一往之间，你和那位未谋面的婆母，已经交了一次手——是暖的。","source":"节礼往来通两家之好，见《梦粱录》记端午馈送。"},{"text":"只留意匣中绣样","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"绣样是好绣样，可这份礼的分量，比绣样重得多。","source":"馈遗见人情，见《仪礼》。"}],"difficulty":1,"npc":["母亲"],"foreshadow":"婆母之情"},{"id":"C-054","branch":"C","stage":3,"day":54,"shichen":"辰时","checkpoint":"观竞渡","scene":"端午次日，全家去金明池边看竞渡。画舫旌旗，鼓声震水，满城的人都来了。","options":[{"text":"随家眷坐船中看","correct":true,"tags":["家世","名声"],"dims":{"家世":1,"名声":1},"feedback":"你端坐船中，看满池喧腾——这是待嫁姑娘少有的公开出游了。","source":"端午竞渡之盛，见《东京梦华录》记驾幸金明池。"},{"text":"挤到船头去呐喊","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"风头是出了，可「李家姑娘看龙舟喊红了脸」也传开了。","source":"闺秀游观以静为体，见《仪礼》妇容。"}],"difficulty":2,"npc":["母亲"],"foreshadow":null},{"id":"C-054-未","branch":"C","stage":3,"day":54,"shichen":"未时","checkpoint":"池边偶遇","scene":"画舫交错时，对面官船上一道熟悉的目光扫过来——是赵家的船。隔着半池水，你们远远「见」了一面。","options":[{"text":"垂眸敛衽端坐","correct":true,"tags":["名声","情缘"],"dims":{"名声":1,"情缘":1},"feedback":"你端坐着没抬头，可那半池水的距离，忽然变得很近。","source":"男女舟中不相视，见《仪礼》。"},{"text":"忍不住望回去","correct":false,"tags":["情缘","名声"],"dims":{"情缘":2,"名声":1},"feedback":"两船交错的一瞬，你看见他也站了起来——然后被你母亲按住了。","source":"游观之戒，见《琅嬛记》。"}],"difficulty":3,"npc":["赵家公子","母亲"],"foreshadow":"池上一面"},{"id":"C-054-戌","branch":"C","stage":3,"day":54,"shichen":"戌时","checkpoint":"竞渡词","scene":"夜里你把白日所见写进词：画桡、旌旗、鼓声，还有半池水那头的官船。写到末句，你搁了笔。","options":[{"text":"末句留白不写尽","correct":true,"tags":["才华","情缘"],"dims":{"才华":2,"情缘":1},"feedback":"有些句子，写尽了反倒浅。留白处，只有你自己看得见。","source":"词贵有不尽之意，见《琅嬛记》。"},{"text":"把官船也写进去","correct":false,"tags":["情缘"],"dims":{"情缘":2},"feedback":"写完你警觉地数了一遍：七个「舟」字，六个「水」字——藏是藏不住了。","source":"闺词避嫌，见《琅嬛记》。"}],"difficulty":2,"npc":null,"foreshadow":null},{"id":"C-055","branch":"C","stage":3,"day":55,"shichen":"辰时","checkpoint":"销夏","scene":"入伏。府里发了冰，母亲教你做冰盘：沙糖冰酪、雪泡豆儿水。你忽然想起「绛绡缕薄冰肌莹」这句旧词。","options":[{"text":"亲手调冰酪奉双亲","correct":true,"tags":["家世","才华"],"dims":{"家世":1,"才华":1},"feedback":"父亲吃了半碗：「今年这冰酪，比往年多一味——是孝心。」","source":"夏日冰盘冰酪，见《东京梦华录》记六月物事。"},{"text":"自己先吃了一大碗","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"冰是好吃，就是入夜闹了半宿肚子。","source":"冰食宜节，见《梦粱录》记暑月。"}],"difficulty":1,"npc":["父亲","母亲"],"foreshadow":null,"flavor":false},{"id":"C-055-未","branch":"C","stage":3,"day":55,"shichen":"未时","checkpoint":"荷亭午梦","scene":"午后荷亭歇晌，风送荷香。你半梦半醒间，听得蝉声如雨——「晚来一阵风兼雨，洗尽炎光」。","options":[{"text":"醒后把午梦记下","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"梦里有荷，有雨，还有一句没写完的词。醒来你补上了它。","source":"夏日即景入词，见《琅嬛记》。"},{"text":"一觉睡到日西斜","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"这样的午觉，嫁了人怕就难得有了——你多睡了一刻。","source":"闺中消夏，见《琅嬛记》。"}],"difficulty":1,"npc":["丫鬟"],"foreshadow":"荷亭词","flavor":true,"yishou":true},{"id":"C-055-戌","branch":"C","stage":3,"day":55,"shichen":"戌时","checkpoint":"夜课不辍","scene":"暑夜难耐，考碑日课却不曾停。今夜父亲讲一方汉印，说到「金石比人心长久」，忽然有些出神。","options":[{"text":"问父亲为何出神","correct":true,"tags":["情缘","才华"],"dims":{"情缘":1,"才华":1},"feedback":"父亲道：「想到这些印传到你们手里，再传下去——金石长久，是因为有人爱惜。」","source":"金石传承之叹，见《金石录后序》。"},{"text":"只顾看印没留意","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"印是好印，可父亲那一刻的神情，你错过了。","source":"家学之传，见《金石录后序》。"}],"difficulty":2,"npc":["父亲"],"foreshadow":"金石传承"},{"id":"C-056","branch":"C","stage":3,"day":56,"shichen":"辰时","checkpoint":"裁夏衣","scene":"嬷嬷教你裁夏衣：「纱罗怎么量、缝份怎么留，嫁了人给夫君做中衣，都在这点功夫上。」","options":[{"text":"一板一眼学剪裁","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"第一件成品是给父亲的中衣，针脚细得看不见。","source":"妇功以衣裳为本，见《仪礼》妇功。"},{"text":"说买成衣也一样","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"嬷嬷啐道：「夫君贴身的衣裳也买？那叫什么媳妇！」","source":"中衣亲制为妇职，见《梦粱录》记嫁娶针线。"}],"difficulty":1,"npc":["嬷嬷"],"foreshadow":null},{"id":"C-056-未","branch":"C","stage":3,"day":56,"shichen":"未时","checkpoint":"绣帕寄意","scene":"你给自己绣一方帕子，绣的是一枝小小的青梅。绣到一半，自己先笑了。","options":[{"text":"绣完收进奁册","correct":true,"tags":["情缘","才华"],"dims":{"情缘":1,"才华":1},"feedback":"这方帕子不送人，不示人，是你自己的。","source":"闺中女红寄意，见《琅嬛记》。"},{"text":"绣完送给母亲","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"母亲一看那青梅，睨你一眼：「哟，这花样有出处吧？」","source":"母女谐语，见《琅嬛记》。"}],"difficulty":1,"npc":["母亲"],"foreshadow":"青梅帕"},{"id":"C-056-戌","branch":"C","stage":3,"day":56,"shichen":"戌时","checkpoint":"纳凉夜话","scene":"夜里全家在院中纳凉。父亲讲他年轻时赶考住僧寺的旧事，母亲摇着蒲扇笑他穷酸。你听着听着入了神。","options":[{"text":"问父亲苦不苦","correct":true,"tags":["家世","情缘"],"dims":{"家世":1,"情缘":1},"feedback":"父亲说：「苦。可你母亲在岳家替我抄书寄来，就不苦了。」","source":"士人寒微之事，见《续资治通鉴长编》记士风。"},{"text":"只顾打瞌睡","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"醒来时身上多了母亲的薄毯，故事已经讲完了。","source":"闺中纳凉，见《琅嬛记》。"}],"difficulty":1,"npc":["父亲","母亲"],"foreshadow":"父母旧事"},{"id":"C-057","branch":"C","stage":3,"day":57,"shichen":"辰时","checkpoint":"六月晒书","scene":"六月六，晒书日。全家把藏书搬出来晒，你负责书画碑帖那一棚——包括你的奁册。","options":[{"text":"逐件翻晒登记","correct":true,"tags":["才华","家世"],"dims":{"才华":1,"家世":1},"feedback":"晒书晒出一张虫蛀的旧帖，你抢在父亲发现前补好了。","source":"六月六晒书曝画，见《梦粱录》记六月。"},{"text":"交给仆妇去晒","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"仆妇不懂轻重，一册宋版书的函套磕了个角。","source":"典籍须亲自护持，见《金石录后序》记护书。"}],"difficulty":2,"npc":["父亲","仆妇"],"foreshadow":"补帖"},{"id":"C-057-未","branch":"C","stage":3,"day":57,"shichen":"未时","checkpoint":"晒书雅事","scene":"晒书棚下，父亲指着满架书说：「这些，一半随你进赵家。书比人长寿，你们替我看着它们。」","options":[{"text":"应下这份托付","correct":true,"tags":["才华","情缘"],"dims":{"才华":2,"情缘":1},"feedback":"你忽然懂了：陪嫁的不是书，是父亲半生的心。","source":"以书为奁，见《金石录后序》。"},{"text":"说太重了少带些","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"父亲摆手：「嫁妆可以少，书不能少。」","source":"士人以书为重，见《金石录后序》。"}],"difficulty":1,"npc":["父亲"],"foreshadow":"以书为奁"},{"id":"C-057-戌","branch":"C","stage":3,"day":57,"shichen":"戌时","checkpoint":"夜整书目","scene":"夜里你把晒过的书重新上架，顺手把奁册的书目又校了一遍。烛火下，一卷卷都是老朋友。","options":[{"text":"给书目加注心得","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"注完一看，某卷某页有你的小字——这书目，带着你的体温。","source":"簿录加注，见《金石录后序》记归来堂簿录。"},{"text":"按大小归架了事","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"归是归齐了，只是少了点什么——少了你和它们的交情。","source":"藏读之别，见《金石录后序》。"}],"difficulty":1,"npc":null,"foreshadow":null},{"id":"C-058","branch":"C","stage":3,"day":58,"shichen":"辰时","checkpoint":"七夕乞巧","scene":"七月初七。府里女眷都要乞巧。嬷嬷把九孔针和五色线备下：「娘子手巧，今年必能穿得进。」","options":[{"text":"屏息一气穿过","correct":true,"tags":["才华","家世"],"dims":{"才华":1,"家世":1},"feedback":"一线穿九孔，满院叫好——今年的巧，你乞到了。","source":"七夕穿针乞巧，见《东京梦华录》记七夕。"},{"text":"穿不进索性罢手","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"嬷嬷把针塞回你手里：「乞巧不诚心，巧娘娘要恼的。」","source":"乞巧之俗，见《梦粱录》。"}],"difficulty":1,"npc":["嬷嬷"],"foreshadow":null},{"id":"C-058-未","branch":"C","stage":3,"day":58,"shichen":"未时","checkpoint":"陈瓜祭星","scene":"午后在庭中陈瓜果祭牵牛织女。你摆上自己雕的「花瓜」，母亲又添了一对磨喝乐。","options":[{"text":"祭罢默许一愿","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"愿的内容你不说。天上那条河太宽，可你的河，有人正蹚过来。","source":"七夕陈瓜祭星乞愿，见《东京梦华录》记七夕。"},{"text":"只顾看磨喝乐","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"泥偶是可爱，可母亲说：「这对磨喝乐，是盼你早生贵子的。」你臊跑了。","source":"七夕陈磨喝乐，见《东京梦华录》。"}],"difficulty":1,"npc":["母亲"],"foreshadow":"七夕愿"},{"id":"C-058-戌","branch":"C","stage":3,"day":58,"shichen":"戌时","checkpoint":"星桥鹊驾","scene":"入夜，满天星斗，银河斜挂。你倚窗看那道星河，想起「星桥鹊驾，经年才见」——人间的分离尚且难熬，何况天上。","options":[{"text":"庆幸自己的河不宽","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"你的牛郎就在汴京城里，隔几重坊墙而已。想到这，星河都不那么冷了。","source":"七夕感怀，见《琅嬛记》。"},{"text":"替牛郎织女难过","correct":true,"tags":["情缘","才华"],"dims":{"情缘":1,"才华":1},"feedback":"你替他们写了一阕词，末句是「人间自有相逢处」。","source":"咏七夕词，见《琅嬛记》。"}],"difficulty":1,"npc":null,"foreshadow":"七夕词","flavor":true,"yishou":true},{"id":"C-059","branch":"C","stage":3,"day":59,"shichen":"辰时","checkpoint":"巧果馈送","scene":"七夕次日，各房互赠巧果。你做的花瓜和巧果被婶娘们抢着要，说是「给自家姑娘也沾沾巧」。","options":[{"text":"多做一些分送","correct":true,"tags":["家世","名声"],"dims":{"家世":1,"名声":1},"feedback":"分了一圈，连平日酸你的那位婶娘都夸：「手是真巧。」","source":"七夕巧果馈赠，见《梦粱录》记七夕。"},{"text":"只送相熟几房","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"没送到的那房婶娘，话里又带了刺。","source":"馈赠宜周，见《仪礼》。"}],"difficulty":1,"npc":["族中婶娘"],"foreshadow":null},{"id":"C-059-未","branch":"C","stage":3,"day":59,"shichen":"未时","checkpoint":"学理妆匣","scene":"母亲教你在婆家怎么活用自己的月例：「夫家的月例是面子，奁产的出息是里子。面子给人看，里子给自己留。」","options":[{"text":"问出息怎么打理","correct":true,"tags":["自主","家世"],"dims":{"自主":1,"家世":1},"feedback":"母亲细讲：田租、铺租、放债的利钱，哪样能动、哪样要留着生息。","source":"奁产出息为妇私财，见《宋刑统》户婚律。"},{"text":"说够花就行","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"母亲正色：「说这话的，都是没缺过钱的。」","source":"治生之道，见《宋会要辑稿》记奁产。"}],"difficulty":3,"npc":["母亲"],"foreshadow":"奁产生息"},{"id":"C-059-戌","branch":"C","stage":3,"day":59,"shichen":"戌时","checkpoint":"灯下心事","scene":"夜里你想：还有小半年就要做赵家的人了。诗书写得再好，账本看得再清，心里到底还是有一点点慌。","options":[{"text":"把慌也写下来","correct":true,"tags":["自主","才华"],"dims":{"自主":1,"才华":1},"feedback":"写完了读一遍——慌，原来也是可以落笔成章的。","source":"闺中自记心迹，见《琅嬛记》。"},{"text":"去母亲房中坐","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"母亲什么也没问，只让你靠了一会儿。","source":"母女之情，见《琅嬛记》。"}],"difficulty":1,"npc":["母亲"],"foreshadow":null},{"id":"C-060","branch":"C","stage":3,"day":60,"shichen":"辰时","checkpoint":"半程回望","scene":"晨起对镜，你忽然想起及笄那天——一百二十日的路，走完一半了。镜中的人，眉眼沉静了许多。","options":[{"text":"对镜拜谢双亲","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"这一拜谢的是养育，也是他们教你的这一身本事。","source":"闺中自励，见《琅嬛记》。"},{"text":"给自己一句鼓励","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"「后半程，也要走得漂亮。」你对着镜子里的自己说。","source":"闺中自勉，见《琅嬛记》。"}],"difficulty":1,"npc":null,"foreshadow":"半程","flavor":true},{"id":"C-060-未","branch":"C","stage":3,"day":60,"shichen":"未时","checkpoint":"母亲盘点","scene":"母亲替你盘点：规矩课将满、奁单已成、嫁衣开工在即。她说：「后半程只剩一件事——把心收一收，准备做人媳妇。」","options":[{"text":"问心要怎么收","correct":true,"tags":["家世","自主"],"dims":{"家世":1,"自主":1},"feedback":"母亲道：「把娘家的娇气收一半，把赵家的责任拾起来。」","source":"妇德之教，见《仪礼》。"},{"text":"说舍不得娘家","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"母亲眼圈也红了：「舍不得，才要过好。过好了，两家都安心。」","source":"母女惜别，见《琅嬛记》。"}],"difficulty":1,"npc":["母亲"],"foreshadow":"收心"},{"id":"C-060-戌","branch":"C","stage":3,"day":60,"shichen":"戌时","checkpoint":"半程夜记","scene":"夜里你翻开那本《居家须知》，从头看到尾。前半程的每一笔，都是今天的自己给昨天的批注。","options":[{"text":"在册尾写半程二字","correct":true,"tags":["自主","才华"],"dims":{"自主":1,"才华":1},"feedback":"「半程」二字写完，你搁笔笑了——后半程，请多指教。","source":"闺中自记，见《琅嬛记》。"},{"text":"合册安心睡去","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"这一夜睡得格外沉。明天起，是新的六十日。","source":"闺中情态，见《琅嬛记》。"}],"difficulty":1,"npc":null,"foreshadow":null,"flavor":true},{"id":"C-061","branch":"C","stage":3,"day":61,"shichen":"辰时","checkpoint":"嫁衣开工","scene":"嫁衣正式开工。针线娘子铺开大红云锦，光是花样就让你选了半个时辰：缠枝莲、折枝梅、还是百子图？","options":[{"text":"选缠枝莲配金线","correct":true,"tags":["家世","才华"],"dims":{"家世":1,"才华":1},"feedback":"母亲拍板：「缠枝莲，连绵不断——好意头，也衬你。」","source":"嫁衣纹饰尚缠枝，见《周氏墓》出土嫁衣纹样。"},{"text":"让母亲看着定","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"母亲选了百子图，你看着那一百个小娃娃，脸先红了。","source":"百子图祈多子，见《梦粱录》记嫁娶。"}],"difficulty":1,"npc":["母亲","针线娘子"],"foreshadow":"嫁衣"},{"id":"C-061-未","branch":"C","stage":3,"day":61,"shichen":"未时","checkpoint":"量体裁衣","scene":"针线娘子给你量体。量到肩宽时她笑道：「娘子比及笄那日，肩打开了——是要挑担子的人了。」","options":[{"text":"问嫁衣要做多久","correct":true,"tags":["家世"],"dims":{"家世":1},"feedback":"「前前后后两个月。」娘子说，「好衣裳跟好日子一样，急不得。」","source":"嫁衣工期，见《梦粱录》记嫁娶。"},{"text":"嫌量体麻烦","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"针线娘子不依：「差一分，上身就差一寸。嫁衣可没有改的机会。」","source":"量体裁衣之慎，见《周氏墓》服饰制度。"}],"difficulty":1,"npc":["针线娘子"],"foreshadow":null},{"id":"C-061-戌","branch":"C","stage":3,"day":61,"shichen":"戌时","checkpoint":"灯下试线","scene":"夜里你拿起一缕嫁衣用的金线，就着灯看。它在你指间闪着光——再过几个月，它就穿在你身上了。","options":[{"text":"把金线绕回线板","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"你现在还舍不得想那个画面。可金线的光，已经在心里了。","source":"待嫁情态，见《琅嬛记》。"},{"text":"问嬷嬷盖头多重","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"嬷嬷笑了：「不重。等盖上了，你就不嫌它重了。」","source":"盖头之俗，见《东京梦华录》记亲迎。"}],"difficulty":1,"npc":["嬷嬷"],"foreshadow":null},{"id":"C-062","branch":"C","stage":3,"day":62,"shichen":"辰时","checkpoint":"打首饰","scene":"银楼师傅上门打首饰。母亲取出老料：一副祖传的金镯、几锭新金。打什么花式，让你自己拿主意。","options":[{"text":"打喜鹊登梅钗","correct":true,"tags":["才华","家世"],"dims":{"才华":1,"家世":1},"feedback":"师傅赞好：「喜鹊登梅，喜上眉梢——娘子会挑！」","source":"宋婚首饰尚喜鹊纹，见《东京梦华录》记嫁娶首饰。"},{"text":"全打最重最实的","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"师傅委婉道：「压手。首饰是戴的，不是称的。」","source":"首饰以工巧为贵，见《梦粱录》。"}],"difficulty":1,"npc":["银楼师傅","母亲"],"foreshadow":"首饰"},{"id":"C-062-未","branch":"C","stage":3,"day":62,"shichen":"未时","checkpoint":"祖镯","scene":"母亲把那副祖传金镯放在你手心：「这是你外祖母给我的，现在给你。它不值多少钱，值钱的是它没断过。」","options":[{"text":"郑重收下贴身藏","correct":true,"tags":["情缘","家世"],"dims":{"情缘":1,"家世":2},"feedback":"镯子贴着你的手腕，凉凉的，又好像带着两代人的体温。","source":"传家之物为奁，见《琅嬛记》。"},{"text":"推说太贵重不敢收","correct":true,"tags":["家世"],"dims":{"家世":1},"feedback":"母亲把镯子套进你腕上：「它就是要一代代传下去的。」","source":"传奁之义，见《琅嬛记》。"}],"difficulty":1,"npc":["母亲"],"foreshadow":"祖镯","flavor":true},{"id":"C-062-戌","branch":"C","stage":3,"day":62,"shichen":"戌时","checkpoint":"夜试新钗","scene":"首饰打好了，丫鬟替你插上那支喜鹊登梅钗。你对着镜中盛装的自己，陌生又熟悉。","options":[{"text":"对镜端详良久","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"镜里的人要出嫁了。你对她笑了笑，她也对你笑了笑。","source":"待嫁情态，见《琅嬛记》。"},{"text":"试完立刻取下","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"「没过门不能久戴喜饰。」嬷嬷在旁念叨，手比你还快。","source":"喜饰不预戴，见《梦粱录》婚仪之忌。"}],"difficulty":1,"npc":["丫鬟","嬷嬷"],"foreshadow":null},{"id":"C-063","branch":"C","stage":3,"day":63,"shichen":"辰时","checkpoint":"盖头课","scene":"嬷嬷教你盖头的讲究：「盖头一蒙，路看不见，脚要稳，心更要稳。牵巾的人引一步，你走一步。」","options":[{"text":"蒙头试走一圈","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"眼前一片红，你走得又稳又慢。嬷嬷满意：「就是这个步子。」","source":"亲迎盖头牵巾之俗，见《东京梦华录》记娶妇。"},{"text":"觉得蒙头好笑","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你笑场了三次，嬷嬷叹气：「到了正日子可不许笑！」","source":"婚仪以庄为礼，见《仪礼》。"}],"difficulty":1,"npc":["嬷嬷"],"foreshadow":"盖头"},{"id":"C-063-未","branch":"C","stage":3,"day":63,"shichen":"未时","checkpoint":"哭嫁之教","scene":"嬷嬷又教一样你没想到的：哭嫁。「上轿前要哭，哭爹娘养育恩。不哭，人家说你不孝；嚎啕，又失体统。」","options":[{"text":"问要哭到什么分寸","correct":true,"tags":["家世","自主"],"dims":{"家世":1,"自主":1},"feedback":"嬷嬷道：「眼泪要真，声音要收。难就难在——都是真的，反而收不住。」","source":"哭嫁之俗，见《梦粱录》记嫁娶。"},{"text":"说我肯定哭不出","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"嬷嬷看你一眼：「到了那日，由不得你。」","source":"临别之情，见《琅嬛记》。"}],"difficulty":2,"npc":["嬷嬷"],"foreshadow":"哭嫁"},{"id":"C-063-戌","branch":"C","stage":3,"day":63,"shichen":"戌时","checkpoint":"夜话别期","scene":"晚间母亲算起日子：「还有个把月就入秋了。你的好日子，在桂花开的时候。」","options":[{"text":"说想看家中桂花","correct":true,"tags":["情缘","家世"],"dims":{"情缘":1,"家世":1},"feedback":"母亲道：「看得到的。你出阁前几日，正是桂花开得最盛的时候。」","source":"秋日婚期，见《东京梦华录》记中秋前后嫁娶。"},{"text":"忽然鼻酸","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"母亲拍拍你：「傻孩子，桂花开得好，是喜事。」","source":"母女惜别，见《琅嬛记》。"}],"difficulty":1,"npc":["母亲"],"foreshadow":"桂花婚期"},{"id":"C-064","branch":"C","stage":3,"day":64,"shichen":"辰时","checkpoint":"奁具齐备","scene":"大木器抬进库房：拔步床、顶箱柜、镜台、官皮箱，一新到底。管家来报：奁具七十二抬，齐了。","options":[{"text":"逐抬验看登记","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"七十二抬验完，你在奁单上画下最后一个勾。","source":"奁具以抬计，见《东京梦华录》记嫁娶奁具。"},{"text":"看了一半就眼花","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"母亲接手验完剩下的，只说了句：「往后这些都是你的管家娘子了。」","source":"奁具验收，见《梦粱录》。"}],"difficulty":2,"npc":["母亲","管家"],"foreshadow":"七十二抬"},{"id":"C-064-未","branch":"C","stage":3,"day":64,"shichen":"未时","checkpoint":"铺房之学","scene":"嬷嬷讲「铺房」：婚前一日，你这边要派人去赵家新房铺陈。「床怎么安，帐怎么挂，都有说法。」","options":[{"text":"问由谁去铺","correct":true,"tags":["家世"],"dims":{"家世":1},"feedback":"「由你乳母领班。」嬷嬷道，「铺得好不好，是你的脸面先进门。」","source":"婚前铺房之俗，见《东京梦华录》记娶妇铺房。"},{"text":"说让赵家自己弄","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"嬷嬷瞪眼：「新房里的每一件，都是娘家的体面，岂能假手？」","source":"铺房为女家之责，见《梦粱录》。"}],"difficulty":2,"npc":["嬷嬷","乳母"],"foreshadow":"铺房"},{"id":"C-064-戌","branch":"C","stage":3,"day":64,"shichen":"戌时","checkpoint":"奁册定稿","scene":"夜里你把奁册最后校订一遍：书目、画目、碑帖目，外加一页「凡例」。一册在手，半生心血俱在。","options":[{"text":"题「归来」二字于扉页","correct":true,"tags":["才华","情缘"],"dims":{"才华":2,"情缘":1},"feedback":"「归来」——愿它伴你归来仍是此心。题完，你吹了灯。","source":"藏书室名之志，见《金石录后序》记归来堂。"},{"text":"只写了名字日期","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"中规中矩，也好。只是这册子配得上一句更好的。","source":"簿录题记，见《金石录后序》。"}],"difficulty":2,"npc":null,"foreshadow":"归来册"},{"id":"C-065","branch":"C","stage":3,"day":65,"shichen":"辰时","checkpoint":"洗手作羹汤","scene":"嬷嬷的规矩课到了最实际的一节：新妇三日入厨。「三日入厨下，洗手作羹汤」——这一课，躲不掉。","options":[{"text":"挽袖跟嬷嬷学","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"一锅羹汤火候正好，嬷嬷尝了：「可以见公婆了。」","source":"新妇三日入厨之俗，见《梦粱录》记嫁娶。"},{"text":"说家里有厨娘","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"嬷嬷道：「头三日的羹汤是礼，不是饭。这口汤，必须是你做的。」","source":"入厨为妇职之礼，见《仪礼》妇职。"}],"difficulty":1,"npc":["嬷嬷"],"foreshadow":"三日入厨"},{"id":"C-065-未","branch":"C","stage":3,"day":65,"shichen":"未时","checkpoint":"学调众口","scene":"嬷嬷又教一层：「羹汤难不在做，在调。公婆的口、夫君的口、妯娌的口，一锅汤要调一屋子人。」","options":[{"text":"问怎么调众口","correct":true,"tags":["家世","自主"],"dims":{"家世":1,"自主":1},"feedback":"嬷嬷道：「记住一句：宁可淡，不可咸；宁可慢，不可乱。」","source":"中馈调羹之喻，见《仪礼》妇职之义。"},{"text":"说各吃各的不行吗","correct":false,"tags":["自主"],"dims":{"自主":2},"feedback":"嬷嬷气笑：「一大家子各吃各的，那还叫家吗？」","source":"共食为家之义，见《仪礼》。"}],"difficulty":2,"npc":["嬷嬷"],"foreshadow":"调羹之喻"},{"id":"C-065-戌","branch":"C","stage":3,"day":65,"shichen":"戌时","checkpoint":"羹汤夜话","scene":"晚间你把白日学的「调羹」说与母亲听。母亲笑道：「羹汤是学问，调羹是道。嬷嬷把她的看家本事都教你了。」","options":[{"text":"谢嬷嬷用心","correct":true,"tags":["家世","情缘"],"dims":{"家世":1,"情缘":1},"feedback":"你专给嬷嬷送了一盏自己调的羹。她喝完抹抹嘴：「成了。」","source":"师事之礼，见《仪礼》。"},{"text":"只当玩笑听过","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"玩笑归玩笑，「调一屋子人」这句话，你记下了。","source":"闺中夜话，见《琅嬛记》。"}],"difficulty":1,"npc":["母亲","嬷嬷"],"foreshadow":null},{"id":"C-066","branch":"C","stage":3,"day":66,"shichen":"辰时","checkpoint":"持家以俭","scene":"父亲难得管一回内宅事，把你叫去说：「赵家门第比咱家高，排场比咱家大。你记着四个字——持家以俭。」","options":[{"text":"问俭到什么分寸","correct":true,"tags":["家世","自主"],"dims":{"家世":1,"自主":1},"feedback":"父亲道：「该省的一文不花，该花的一文不省。分寸在心里，不在账上。」","source":"士人家训尚俭，见《续资治通鉴长编》记士风。"},{"text":"说太俭会失礼","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"父亲道：「失礼的从来是怠慢，不是俭省。这两样，别混。」","source":"俭与吝之辨，见《仪礼》义疏。"}],"difficulty":2,"npc":["父亲"],"foreshadow":"持家以俭"},{"id":"C-066-未","branch":"C","stage":3,"day":66,"shichen":"未时","checkpoint":"看嫁妆田","scene":"管家带你出城看奁田。站在自家田埂上，看佃户收割，你头一回觉得奁单上的「田五十亩」是活的。","options":[{"text":"向佃户问收成","correct":true,"tags":["自主","家世"],"dims":{"自主":1,"家世":1},"feedback":"佃户老丈说得实在：年成、水旱、租子几成，你记了一路。","source":"奁田收租为妇私入，见《宋会要辑稿》记奁产。"},{"text":"远远站着怕踩泥","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"田是看过了，可这五十亩到底能出多少粮，你心里还是没数。","source":"主家巡田之常，见《宋刑统》田制。"}],"difficulty":2,"npc":["管家","佃户"],"foreshadow":"奁田"},{"id":"C-066-戌","branch":"C","stage":3,"day":66,"shichen":"戌时","checkpoint":"夜算田租","scene":"夜里你把白日问的收成折算成租子，一笔笔算清。原来奁单上轻飘飘一行字，是这么来的。","options":[{"text":"把算法记入奁册","correct":true,"tags":["自主","才华"],"dims":{"自主":1,"才华":1},"feedback":"奁册里从此多了「田课」一页——嫁妆自己会生息了。","source":"田租之算，见《宋刑统》户婚律记妻财。"},{"text":"算完揉了纸团","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"算明白了就行。可写下来，才是一辈子的东西。","source":"闺中理财，见《琅嬛记》。"}],"difficulty":2,"npc":null,"foreshadow":"田课"},{"id":"C-067","branch":"C","stage":3,"day":67,"shichen":"辰时","checkpoint":"暑后小恙","scene":"出伏后贪了凉，你晨起头重，嗓子发紧。母亲来看，立刻吩咐熬药，规矩课也停了。","options":[{"text":"乖乖吃药静养","correct":true,"tags":["家世"],"dims":{"家世":1},"feedback":"两日便好了。母亲说：「将出嫁的人，最病不得。」","source":"婚前调护，见《梦粱录》记嫁娶前禁忌。"},{"text":"硬撑着要上课","correct":false,"tags":["自主"],"dims":{"自主":2},"feedback":"撑到午后烧起来了，反多躺了三日。","source":"病宜早治，见《琅嬛记》闺中调理。"}],"difficulty":1,"npc":["母亲"],"foreshadow":null},{"id":"C-067-未","branch":"C","stage":3,"day":67,"shichen":"未时","checkpoint":"病中探视","scene":"病里各房都来探视，连赵家也遣人送了药材。乳母在你床前絮絮念着各房送的是什么。","options":[{"text":"记下该谢的人情","correct":true,"tags":["家世"],"dims":{"家世":1},"feedback":"病好后你一一回了谢帖，一笔人情都没欠。","source":"馈药答礼，见《仪礼》馈遗之义。"},{"text":"病中懒得理会","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"药材收了，谢帖忘了——三房的婶娘又记了一笔。","source":"人情应答，见《琅嬛记》。"}],"difficulty":1,"npc":["乳母"],"foreshadow":null},{"id":"C-067-戌","branch":"C","stage":3,"day":67,"shichen":"戌时","checkpoint":"病中夜话","scene":"夜里母亲在床边守着。你昏昏沉沉说：「娘，我要是嫁过去了，病了谁守我？」母亲半天没说话。","options":[{"text":"握住母亲的手","correct":true,"tags":["情缘","家世"],"dims":{"情缘":2,"家世":1},"feedback":"母亲反手握紧你：「有夫君，有婆母。可娘的手，随时都在。」","source":"母女之情，见《琅嬛记》。"},{"text":"转过身去装睡","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"你装睡，母亲就静静地坐着，坐到更鼓响了二遍。","source":"母女之情，见《琅嬛记》。"}],"difficulty":1,"npc":["母亲"],"foreshadow":null,"flavor":true},{"id":"C-068","branch":"C","stage":3,"day":68,"shichen":"辰时","checkpoint":"病愈复课","scene":"病好了，规矩课复课。嬷嬷的功课表排到月底，她说：「误了的课要补，好日子不等人。」","options":[{"text":"加倍用功补上","correct":true,"tags":["自主","家世"],"dims":{"自主":1,"家世":1},"feedback":"三日补回五日的课，嬷嬷嘴上不说，茶里给你加了蜜。","source":"闺学日课，见《琅嬛记》。"},{"text":"慢慢来不着急","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"嬷嬷叹气：「娘子啊，嫁人的日子是钉死的。」","source":"婚期不可改，见《仪礼》请期之义。"}],"difficulty":1,"npc":["嬷嬷"],"foreshadow":null},{"id":"C-068-未","branch":"C","stage":3,"day":68,"shichen":"未时","checkpoint":"赵家问候","scene":"赵家又遣人来问安，这回带来的是一篓新摘的鲜莲蓬，附了赵夫人的口信：「给娘子补补。」","options":[{"text":"剥莲子亲手制羹","correct":true,"tags":["家世","情缘"],"dims":{"家世":1,"情缘":1},"feedback":"莲子羹熬好，先奉母亲，再谢来使。一来一往，又是人情。","source":"馈食答礼，见《仪礼》。"},{"text":"收下道谢便罢","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"礼是收了，可夫人的心思想要你一句「知冷知热」的回应。","source":"馈赠贵有回应，见《琅嬛记》。"}],"difficulty":1,"npc":["母亲","赵家来使"],"foreshadow":"婆母之情"},{"id":"C-068-戌","branch":"C","stage":3,"day":68,"shichen":"戌时","checkpoint":"莲心","scene":"夜里你剥着剩下的莲蓬。莲心苦，莲子甜。你忽然觉得这个很像待嫁的日子。","options":[{"text":"把莲心泡茶喝了","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"苦尽，回甘。你把这句话写在了奁册的空白处。","source":"闺中感物，见《琅嬛记》。"},{"text":"把莲心都挑出来扔掉","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"甜的留下，苦的扔掉——可日子不会依你这么过。","source":"闺中情态，见《琅嬛记》。"}],"difficulty":1,"npc":null,"foreshadow":null,"flavor":true},{"id":"C-069","branch":"C","stage":3,"day":69,"shichen":"辰时","checkpoint":"中秋将近","scene":"八月将半，满城已见月饼、螯蟹、新酒。母亲说这个中秋要办得格外齐整——是你在娘家的最后一个中秋。","options":[{"text":"帮着张罗家宴","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"宴席单子是你拟的，连赏月亭的灯你都添了几盏。","source":"中秋家宴之盛，见《东京梦华录》记中秋。"},{"text":"听了心里发堵","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"「最后一个」这四个字，比月饼的馅还沉。","source":"待嫁惜别，见《琅嬛记》。"}],"difficulty":1,"npc":["母亲"],"foreshadow":"最后的中秋"},{"id":"C-069-未","branch":"C","stage":3,"day":69,"shichen":"未时","checkpoint":"赵家节礼","scene":"赵家的中秋节礼到了：宫里式的月饼、一对活蟹，另有一柄团扇，扇面是赵家公子自绘的桂花。","options":[{"text":"收下细赏扇面","correct":true,"tags":["情缘","才华"],"dims":{"情缘":2,"才华":1},"feedback":"桂花画得清瘦，题了二字「秋信」。他的信，你收到了。","source":"中秋馈扇绘事，见《东京梦华录》记中秋物事。"},{"text":"把扇交给母亲收","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"母亲笑：「给你的，给我做什么？」又把扇塞回你手里。","source":"馈赠品有所归，见《仪礼》。"}],"difficulty":1,"npc":["母亲"],"foreshadow":"秋信团扇"},{"id":"C-069-戌","branch":"C","stage":3,"day":69,"shichen":"戌时","checkpoint":"回节礼","scene":"母亲备回礼，让你添一样「你亲手的东西」。你挑来挑去，选了自己抄的一卷《月令》小楷。","options":[{"text":"附上亲手抄的月令","correct":true,"tags":["才华","情缘"],"dims":{"才华":1,"情缘":1},"feedback":"赵家回话：公子把那卷字挂在了书房。","source":"以笔墨相酬为雅，见《金石录后序》记文事相得。"},{"text":"觉得拿不出手","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"母亲道：「你的心意比什么都拿得出手。」最终礼单上还是添了它。","source":"馈礼重心意，见《仪礼》。"}],"difficulty":1,"npc":["母亲"],"foreshadow":"小楷月令"},{"id":"C-070","branch":"C","stage":3,"day":70,"shichen":"辰时","checkpoint":"中秋日","scene":"八月十五。晨起祭月宫，府里张灯。今年家里的灯比往年都多——人人都知道，这是团圆给离别看的。","options":[{"text":"依礼拜月","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"你在月前站定，忽然明白「团圆」两个字为什么这么重。","source":"中秋拜月，见《东京梦华录》记中秋。"},{"text":"嫌麻烦躲进房","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"母亲亲自来把你拉出去：「这样的月亮，你还能在家看几回？」","source":"拜月为中秋正礼，见《梦粱录》。"}],"difficulty":1,"npc":["母亲"],"foreshadow":null},{"id":"C-070-未","branch":"C","stage":3,"day":70,"shichen":"未时","checkpoint":"团圆宴","scene":"团圆宴上，父亲难得红了眼眶，举杯说：「今年人月两圆。」全桌都安静了。","options":[{"text":"起身敬双亲一杯","correct":true,"tags":["家世","情缘"],"dims":{"家世":1,"情缘":2},"feedback":"你敬了父母，又敬了满桌亲人。这杯酒里的滋味，你要记一辈子。","source":"家宴行酒之礼，见《东京梦华录》记中秋宴饮。"},{"text":"低头扒饭忍泪","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"眼泪还是掉进了碗里。母亲给你夹了一筷子菜，什么也没说。","source":"惜别之情，见《琅嬛记》。"}],"difficulty":1,"npc":["父亲","母亲"],"foreshadow":null,"flavor":true},{"id":"C-070-戌","branch":"C","stage":3,"day":70,"shichen":"戌时","checkpoint":"中秋月","scene":"夜里你独自在亭中看月。月还是那轮月，可看月的人，明年就要在别家的庭院里了。","options":[{"text":"写一阕中秋词","correct":true,"tags":["才华","情缘"],"dims":{"才华":2,"情缘":1},"feedback":"词成，末句是「此夜清光，分与两家看」。","source":"中秋咏月，见《琅嬛记》。"},{"text":"对月坐到夜深","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"月光落了你一身。远处隐隐有赵家方向的更鼓声。","source":"闺中赏月，见《琅嬛记》。"}],"difficulty":1,"npc":null,"foreshadow":"中秋词","flavor":true},{"id":"C-071","branch":"C","stage":3,"day":71,"shichen":"辰时","checkpoint":"桂花开了","scene":"一夜风过，满城的桂花都开了。晨起推窗，甜香涌进屋里——婚期，就在花香最浓的那几天。","options":[{"text":"折一枝供在奁册上","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"奁册染了桂香。往后翻它，每一页都是这个秋天的味道。","source":"中秋前后桂花为都中盛景，见《武林旧事》记秋桂。"},{"text":"只觉得香得发慌","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"香越浓，日子越近。你深吸一口气，还是甜的。","source":"闺中感物，见《琅嬛记》。"}],"difficulty":1,"npc":null,"foreshadow":"桂花婚期"},{"id":"C-071-未","branch":"C","stage":3,"day":71,"shichen":"未时","checkpoint":"嫁衣初成","scene":"嫁衣上身试了第一回。大红云锦压身，金线缠枝莲从肩头开到裙角。针线娘子围着你转了三圈。","options":[{"text":"听她讲穿着规矩","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"衣领怎么抿、裙摆怎么提、坐下怎么收——嫁衣不是穿的，是「行」的。","source":"嫁衣穿着之仪，见《东京梦华录》记亲迎。"},{"text":"只顾照镜子","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"镜子里的人明艳得陌生。你多看了两眼，被嬷嬷笑：「留给正日子看！」","source":"嫁衣不预着，见《梦粱录》婚仪之忌。"}],"difficulty":1,"npc":["针线娘子","嬷嬷"],"foreshadow":"嫁衣"},{"id":"C-071-戌","branch":"C","stage":3,"day":71,"shichen":"戌时","checkpoint":"夜读家信","scene":"夜里收到族兄的信，说太学里已经有人开赌盘：「词女」出阁那日，赵家公子会不会当街赋催妆诗。","options":[{"text":"回信嗔他胡闹","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"族兄回信连声告罪，末尾还是问：「到底赋不赋？」","source":"催妆诗之俗，见《梦粱录》记亲迎催妆。"},{"text":"暗想他赋什么","correct":false,"tags":["情缘"],"dims":{"情缘":2},"feedback":"想了一圈没答案。可若他真当街赋诗……你不敢想，又忍不住想。","source":"待嫁情思，见《琅嬛记》。"}],"difficulty":1,"npc":["族兄"],"foreshadow":"催妆诗"},{"id":"C-072","branch":"C","stage":3,"day":72,"shichen":"辰时","checkpoint":"上头礼","scene":"婚前上头：母亲为你梳起妇人的发髻，插上银簪。镜中的「姑娘」从此就要盘起头发做人妇了。","options":[{"text":"坐定让母亲慢慢梳","correct":true,"tags":["家世","情缘"],"dims":{"家世":1,"情缘":2},"feedback":"母亲的手很稳，梳一下，说一句叮嘱。你都记下了。","source":"上头是婚前改笄为髻之礼，见《梦粱录》记嫁娶。"},{"text":"催她快些","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"母亲不理你，照旧一下一下梳：「这头发，娘梳不了几回了。」","source":"上头惜别，见《琅嬛记》。"}],"difficulty":1,"npc":["母亲"],"foreshadow":"上头","flavor":true},{"id":"C-072-未","branch":"C","stage":3,"day":72,"shichen":"未时","checkpoint":"开脸","scene":"午后开脸。开脸娘子用丝线绞去你面上绒毛，疼是真疼。她说：「开了脸，就是大人了。」","options":[{"text":"咬牙受完不吭声","correct":true,"tags":["家世","自主"],"dims":{"家世":1,"自主":1},"feedback":"铜镜里皮肤光润如新。疼过之后，确实像个大人了。","source":"婚前开脸之俗，见《梦粱录》记嫁娶。"},{"text":"疼得直躲","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"丝线绞了三回才绞完。娘子笑你：「这点疼都忍不得？」","source":"开脸之痛为常情，见《琅嬛记》。"}],"difficulty":1,"npc":["开脸娘子"],"foreshadow":null},{"id":"C-072-戌","branch":"C","stage":3,"day":72,"shichen":"戌时","checkpoint":"照镜之夜","scene":"夜里你对镜看自己：妇人的髻，开过脸的光洁面皮。从哪一刻起，你不再是那个荡秋千的姑娘了？","options":[{"text":"对旧我道一声别","correct":true,"tags":["自主","情缘"],"dims":{"自主":1,"情缘":1},"feedback":"「谢谢这十六年的你。」你在心里说，「剩下的路，换我来走。」","source":"闺中自别，见《琅嬛记》。"},{"text":"吹灯不看","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"不看也在那里。明日的你，照样要顶着这个髻出门。","source":"待嫁情态，见《琅嬛记》。"}],"difficulty":1,"npc":null,"foreshadow":null,"flavor":true},{"id":"C-073","branch":"C","stage":3,"day":73,"shichen":"辰时","checkpoint":"催妆前奏","scene":"赵家送来催妆礼：花粉、头面、五男二女花。满城都知道，李家的「词女」要出阁了。","options":[{"text":"依礼受礼记单","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"催妆礼单收入奁册——这是夫家催你过门的信。","source":"婚前催妆之礼，见《东京梦华录》记娶妇催妆。"},{"text":"羞得不肯出来","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"母亲替你受了礼，回头点你：「这样的日子，羞也要羞在人前。」","source":"受礼之仪，见《仪礼》。"}],"difficulty":2,"npc":["母亲","赵家使者"],"foreshadow":"催妆"},{"id":"C-073-未","branch":"C","stage":3,"day":73,"shichen":"未时","checkpoint":"铺房之日","scene":"乳母领着人往赵家铺房去了。奁具七十二抬先走一步，你的奁册、书画、碑帖，都由你亲手装箱。","options":[{"text":"逐箱封缄画押","correct":true,"tags":["家世","自主"],"dims":{"家世":1,"自主":1},"feedback":"最后一箱封的是奁册。你的半生，装进了一口描金箱子。","source":"铺房奁具先行，见《东京梦华录》记娶妇铺房。"},{"text":"舍不得那几卷碑帖","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"乳母笑：「娘子是嫁过去，又不是卖了它们——在那边照样天天见。」","source":"奁物随人，见《梦粱录》。"}],"difficulty":2,"npc":["乳母"],"foreshadow":"铺房"},{"id":"C-073-戌","branch":"C","stage":3,"day":73,"shichen":"戌时","checkpoint":"空了一半的房","scene":"夜里你的房间空了一半。住了十六年的屋子，忽然露出陌生的底色。","options":[{"text":"在空房里坐了很久","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"墙上挂画的地方留着浅浅的痕。原来告别是从墙上开始的。","source":"闺中惜别，见《琅嬛记》。"},{"text":"去母亲房里挤着睡","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"母亲没赶你。这一夜，你们像小时候一样，头挨着头。","source":"母女之情，见《琅嬛记》。"}],"difficulty":1,"npc":["母亲"],"foreshadow":null,"flavor":true},{"id":"C-074","branch":"C","stage":3,"day":74,"shichen":"辰时","checkpoint":"亲迎前一日","scene":"明日就是正日子。全家上下都在最后的忙碌：喜烛、喜联、喜棚，连门槛都擦了三遍。","options":[{"text":"各处再走看一遍","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"喜棚的结、烛台的位、待客的席，你都过了眼。明日，你只负责美。","source":"婚前一日诸事齐备，见《东京梦华录》记娶妇。"},{"text":"紧张得帮不上忙","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"母亲把你按回房里：「今日你的活儿只有一件——把自己睡好。」","source":"婚前养容，见《梦粱录》。"}],"difficulty":1,"npc":["母亲"],"foreshadow":"正日子"},{"id":"C-074-未","branch":"C","stage":3,"day":74,"shichen":"未时","checkpoint":"闺伴送别","scene":"闺伴们都来了，塞给你各种小物件：香囊、帕子、同心结。有人笑着笑着就哭了。","options":[{"text":"一一收下抱住她们","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"「嫁了也要来往！」你们拉着手，说了一下午的傻话。","source":"闺伴送别之情，见《琅嬛记》。"},{"text":"强撑着不哭","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"撑到她们走了，你一个人对着满床的小物件，哭了一场。","source":"惜别之情，见《琅嬛记》。"}],"difficulty":1,"npc":["闺伴"],"foreshadow":null},{"id":"C-074-戌","branch":"C","stage":3,"day":74,"shichen":"戌时","checkpoint":"最后一夜","scene":"在娘家的最后一夜。母亲在你房中坐到三更。谁也不说话，可谁也知道对方在想什么。","options":[{"text":"偎着母亲直到夜深","correct":true,"tags":["情缘","家世"],"dims":{"情缘":2,"家世":1},"feedback":"母亲走时替你掖了被角，像过去的六千个夜晚一样。","source":"母女之别，见《琅嬛记》。"},{"text":"早早催母亲去睡","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"母亲是走了，可你听见她回房的脚步，在门口停了三停。","source":"惜别之情，见《琅嬛记》。"}],"difficulty":1,"npc":["母亲"],"foreshadow":"最后一夜","flavor":true},{"id":"C-075","branch":"C","stage":3,"day":75,"shichen":"辰时","checkpoint":"正日子·晨起","scene":"天没亮你就被叫起。喜娘、嬷嬷、丫鬟围着你团团转：沐浴、梳妆、穿嫁衣。今日，你出阁。","options":[{"text":"稳住心神任她们忙","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"一层层嫁衣上身，你的心跳反而慢下来——这一日，你等了三百六十五日。","source":"亲迎日新娘晨起梳妆，见《东京梦华录》记娶妇。"},{"text":"紧张得手脚冰凉","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"喜娘笑着搓热你的手：「都这样。上了轿，就好了。」","source":"新嫁娘之态，见《梦粱录》。"}],"difficulty":2,"npc":["喜娘","嬷嬷"],"foreshadow":"出阁"},{"id":"C-075-未","branch":"C","stage":3,"day":75,"shichen":"未时","checkpoint":"催妆诗","scene":"花轿到门，外头鼓乐喧天。果然有人当街拦轿赋诗催妆——一首、两首、三首。第七首的句子，清越得像他的人。","options":[{"text":"听完才肯上头加髻","correct":true,"tags":["情缘","才华","感情"],"dims":{"情缘":2,"才华":1},"feedback":"催妆诗催的是妆，你等的是他。第七首，值回这一年的等待。","source":"催妆诗以多为荣，见《梦粱录》记亲迎催妆。"},{"text":"依礼不迟不早","correct":true,"tags":["家世","感情"],"dims":{"家世":1},"feedback":"礼数一丝不差，满街都说李家娘子「端凝」。只有你知道自己心跳多快。","source":"新妇迟速有度，见《仪礼》士昏礼。"}],"difficulty":2,"npc":["喜娘","赵家公子"],"foreshadow":"第七首","flavor":true},{"id":"C-075-戌","branch":"C","stage":3,"day":75,"shichen":"戌时","checkpoint":"哭别上轿","scene":"拜别双亲。母亲的泪先掉下来，你的也跟着掉——哭嫁不用教，到了这一刻，都是真的。","options":[{"text":"拜别时记住爹娘的脸","correct":true,"tags":["情缘","家世"],"dims":{"情缘":2,"家世":2},"feedback":"盖头落下前最后一眼，是父亲挺直的背和母亲挥着的手。","source":"新妇拜别父母，见《仪礼》士昏礼。"},{"text":"哭得说不出话","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"说不说都一样。盖头落下的那一刻，你已经是赵家的人了。","source":"哭嫁之情，见《梦粱录》。"}],"difficulty":1,"npc":["父亲","母亲","喜娘"],"foreshadow":"阶段三毕","flavor":true},{"id":"C-076","branch":"C","stage":4,"day":76,"shichen":"辰时","checkpoint":"花烛之夜","scene":"拜堂、牵巾、合卺。喧闹散尽，洞房里只剩一对花烛，和烛影里那个掀了你盖头的人。","options":[{"text":"抬眼看清了他的脸","correct":true,"tags":["情缘","感情"],"dims":{"情缘":3},"feedback":"比屏风上的影子好看。他也正看你，说：「原来是你。」","source":"亲迎合卺之礼，见《东京梦华录》记娶妇。"},{"text":"垂着头不敢看","correct":true,"tags":["名声","感情"],"dims":{"名声":1,"情缘":1},"feedback":"他轻声笑：「词写得那样大胆，人倒害羞。」你更不敢抬头了。","source":"新婚之态，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":"洞房","flavor":true},{"id":"C-076-未","branch":"C","stage":4,"day":76,"shichen":"未时","checkpoint":"合卺酒","scene":"合卺酒是早上合的，此刻回想，那瓢一分为二、又合二为一的甜酒，像极了两家人的意思。","options":[{"text":"把卺礼记进奁册","correct":true,"tags":["情缘","才华"],"dims":{"情缘":1,"才华":1},"feedback":"奁册添了新一页，抬头写着「嘉礼」二字。","source":"合卺为婚礼之重，见《仪礼》士昏礼。"},{"text":"只回味那口甜","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"甜是真甜。你想，这日子，大概也是甜的。","source":"新婚情态，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":null,"flavor":true},{"id":"C-076-戌","branch":"C","stage":4,"day":76,"shichen":"戌时","checkpoint":"烛下初谈","scene":"花烛高烧。他指着墙上挂的一卷碑拓问你可识得——竟是你在相国寺看他争价的那卷。","options":[{"text":"说出那卷碑的来历","correct":true,"tags":["才华","情缘"],"dims":{"才华":1,"情缘":2},"feedback":"你补了那日的下半句：「我当时就在旁边。」他怔住，而后大笑。","source":"以金石为话，见《金石录后序》记夫妇同好。"},{"text":"装作头一回见","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"他讲了一路碑的来历，讲得眉飞色舞。你忍住没说，相国寺那天你也在。","source":"闺中情态，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":"碑帖重逢"},{"id":"C-077","branch":"C","stage":4,"day":77,"shichen":"辰时","checkpoint":"拜见公婆","scene":"次日晨起，拜见公婆。你一夜没睡踏实，就怕今早这一拜出差错。","options":[{"text":"依嬷嬷所教行礼","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"三拜、献茶、受贽，一丝不乱。夫人接过茶，说了句「好孩子」。","source":"新妇见舅姑之礼，见《仪礼》士昏礼。"},{"text":"紧张得忘了献茶","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"喜娘在旁小声提醒。茶是献上了，你的脸比嫁衣还红。","source":"新妇之仪，见《梦粱录》。"}],"difficulty":2,"npc":["婆母","公公"],"foreshadow":"公婆"},{"id":"C-077-未","branch":"C","stage":4,"day":77,"shichen":"未时","checkpoint":"认亲族","scene":"接着认亲族：叔伯妯娌一屋子人。你掏出默记的亲族图，一个个对上号，称呼没叫错一个。","options":[{"text":"按图称呼不乱","correct":true,"tags":["家世","才华"],"dims":{"家世":1,"才华":1},"feedback":"二嫂悄声说：「新妇做了功课。」这话是夸，也是试。","source":"新妇遍谒亲族，见《东京梦华录》记娶妇。"},{"text":"跟着喜娘现学","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"三房排行还是叫岔了一个，满屋笑声里你记下了这一笔。","source":"亲族之礼，见《仪礼》。"}],"difficulty":2,"npc":["妯娌","亲族"],"foreshadow":"妯娌"},{"id":"C-077-戌","branch":"C","stage":4,"day":77,"shichen":"戌时","checkpoint":"新房夜话","scene":"夜里他说起白日认亲：「难为你了，我们家人多。」你说起了那张亲族图，他听得直笑。","options":[{"text":"笑说做了功课","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"他说：「娘子用心。」四个字，比满堂彩都暖。","source":"新婚相得，见《琅嬛记》。"},{"text":"抱怨人太多","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"他替家人赔了个礼，又说：「往后我陪你慢慢认。」","source":"新婚夜话，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":null},{"id":"C-078","branch":"C","stage":4,"day":78,"shichen":"辰时","checkpoint":"三日入厨","scene":"婚后第三日，入厨。你挽袖下厨作羹汤——嬷嬷教的「宁可淡，不可咸」，就在今日见真章。","options":[{"text":"照嬷嬷的方子做","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"羹汤上桌，公婆都添了第二碗。嬷嬷的方子，管用。","source":"三日入厨作羹汤，见《梦粱录》记嫁娶。"},{"text":"自作主张加料","correct":false,"tags":["自主"],"dims":{"自主":2},"feedback":"鲜是鲜，就是咸了半分。婆母没说什么，只多用了半碗饭。","source":"调羹之慎，见《仪礼》妇职。"}],"difficulty":2,"npc":["婆母","厨娘"],"foreshadow":"羹汤"},{"id":"C-078-未","branch":"C","stage":4,"day":78,"shichen":"未时","checkpoint":"入厨余波","scene":"午后妯娌来串门，绕着弯儿打听你入厨的事。你说羹汤是厨娘们帮衬，只报了一个方子。","options":[{"text":"谦说大家帮衬","correct":true,"tags":["名声","家世"],"dims":{"名声":1,"家世":1},"feedback":"话传出去是「新妇谦和」。妯娌间的第一阵，你守住了。","source":"妇言以谦为德，见《仪礼》。"},{"text":"说都是自己所做","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"当夜小厨房就传出话：新妇「抢功」。","source":"新妇忌显己，见《琅嬛记》闺戒。"}],"difficulty":2,"npc":["妯娌"],"foreshadow":"妯娌"},{"id":"C-078-戌","branch":"C","stage":4,"day":78,"shichen":"戌时","checkpoint":"他尝羹汤","scene":"晚间他说：「白日那碗羹，我吃了两碗。」你说咸了。他说：「咸的也是你做的。」","options":[{"text":"记下他的口味","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"你在心里添了一页「他的口味」：口重，爱浓汤，不喜甜。","source":"闺中记夫君之好，见《琅嬛记》。"},{"text":"嗔他惯会说嘴","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"嘴上嗔着，心里是甜的。新婚的日子，咸淡都是蜜。","source":"新婚情态，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":null},{"id":"C-079","branch":"C","stage":4,"day":79,"shichen":"辰时","checkpoint":"回门","scene":"三日回门。马车刚进巷口，你就望见家门口母亲张望的身影——才三日，像隔了三年。","options":[{"text":"下车先拜双亲","correct":true,"tags":["家世","情缘"],"dims":{"家世":1,"情缘":2},"feedback":"母亲拉着你上下看，半天说出一句：「气色好。」三个字，千斤重。","source":"三日回门归宁，见《东京梦华录》记娶妇。"},{"text":"一进门就哭了","correct":false,"tags":["情缘"],"dims":{"情缘":2},"feedback":"哭是真哭，可回门哭得凶，夫家脸上不好看——母亲替你描了妆。","source":"归宁之礼以喜为体，见《梦粱录》。"}],"difficulty":2,"npc":["母亲","父亲"],"foreshadow":"回门"},{"id":"C-079-未","branch":"C","stage":4,"day":79,"shichen":"未时","checkpoint":"归宁宴","scene":"归宁宴上，父亲问他金石，母亲问你起居。你看见他把那卷《月令》小楷的来历讲给父亲听。","options":[{"text":"看翁婿相谈甚欢","correct":true,"tags":["情缘","家世"],"dims":{"情缘":1,"家世":1},"feedback":"父亲看你的眼神透着放心。这一场相看，是父亲相的最后一次。","source":"归宁宴之乐，见《琅嬛记》。"},{"text":"只顾给母亲夹菜","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"母亲按住你：「傻丫头，今日你是客。」","source":"归宁为客，见《仪礼》。"}],"difficulty":1,"npc":["父亲","母亲","夫君"],"foreshadow":null},{"id":"C-079-戌","branch":"C","stage":4,"day":79,"shichen":"戌时","checkpoint":"回赵家","scene":"傍晚回赵家。车过巷口，你没回头——回门的规矩，不回头。可你在心里跟那扇门说了声再见。","options":[{"text":"向前看不回头","correct":true,"tags":["自主","情缘"],"dims":{"自主":1,"情缘":1},"feedback":"他在车里握住你的手。娘家在身后，日子在前头。","source":"归宁不回头之俗，见《梦粱录》婚仪。"},{"text":"还是没忍住回头","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"回头也无妨——那扇门还亮着灯，爹娘还站在灯下。","source":"惜别之情，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":null,"flavor":true},{"id":"C-080","branch":"C","stage":4,"day":80,"shichen":"辰时","checkpoint":"画眉","scene":"晨起梳妆，他倚在门边看你画眉，忽然说：「我来。」眉笔在你眉上颤巍巍地落下去。","options":[{"text":"由他画不笑话","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"画完一看，一高一低。你们对着铜镜笑了半天。","source":"闺房画眉之趣，见《琅嬛记》。"},{"text":"躲开说自己来","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"他讪讪收了笔。夜里你想，那一高一低，或许也不坏。","source":"新婚情态，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":"画眉","flavor":true},{"id":"C-080-未","branch":"C","stage":4,"day":80,"shichen":"未时","checkpoint":"午后赌书","scene":"午后他翻出一册书考你出处，你答上来，便要他罚茶一盏。一来一往，茶泼了半袖，满室大笑。","options":[{"text":"越玩越起劲","correct":true,"tags":["才华","情缘","感情"],"dims":{"才华":1,"情缘":2},"feedback":"你说某事在某书某卷某页，他翻书一对——果然。他叹：「我娶了个书库。」","source":"赌书记诵之戏，见《金石录后序》记夫妇赌书。"},{"text":"让他三局收着玩","correct":false,"tags":["名声","感情"],"dims":{"名声":1},"feedback":"他赢了倒不痛快：「娘子让我，就没意思了。」","source":"夫妇以真见情，见《金石录后序》。"}],"difficulty":2,"npc":["夫君"],"foreshadow":"赌书泼茶"},{"id":"C-080-戌","branch":"C","stage":4,"day":80,"shichen":"戌时","checkpoint":"泼茶之夜","scene":"夜里你还想着午后的赌书。泼湿的茶渍留在袖口，你不舍得换——「赌书消得泼茶香」，原来是这样的香。","options":[{"text":"把这日写进词","correct":true,"tags":["才华","情缘"],"dims":{"才华":2,"情缘":1},"feedback":"词成。你把「泼茶」两个字圈了又圈。","source":"新婚词记闺中乐，见《琅嬛记》。"},{"text":"只闻着茶香睡","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"茶香混着墨香，这大概就是「日子」的味道。","source":"闺中情态，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":"泼茶词","flavor":true,"yishou":true},{"id":"C-081","branch":"C","stage":4,"day":81,"shichen":"辰时","checkpoint":"开奁共赏","scene":"晨起他说：「听闻娘子的奁册极有章法，可否一开？」你取出七十二抬里最沉的那口描金箱。","options":[{"text":"开箱与他共赏","correct":true,"tags":["情缘","才华"],"dims":{"情缘":1,"才华":2},"feedback":"他一页页翻过去，翻到碑帖目时停住：「这些……你都懂？」","source":"夫妇共赏书画，见《金石录后序》记归来堂。"},{"text":"只说些寻常物件","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"他有些失望，随即笑道：「来日方长，慢慢给我看。」","source":"夫妇以文相示，见《金石录后序》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":"开奁"},{"id":"C-081-未","branch":"C","stage":4,"day":81,"shichen":"未时","checkpoint":"为题奁册","scene":"午后他主动要为你的奁册题跋。提笔想了很久，只写了八个字：「物有其主，主得其人。」","options":[{"text":"珍重收好这页跋","correct":true,"tags":["情缘","才华"],"dims":{"情缘":2,"才华":1},"feedback":"「主得其人」——他是在说奁册，也是在说你们。","source":"题跋相赠，见《金石录后序》。"},{"text":"请他再题一首词","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他笑着搁笔：「好跋一字千金，今日这八个字，够用了。」","source":"题跋贵简贵真，见《金石录后序》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":"奁册题跋"},{"id":"C-081-戌","branch":"C","stage":4,"day":81,"shichen":"戌时","checkpoint":"灯下论藏","scene":"夜里你们头一回认真讨论：两家之藏合到一处，该怎么编目、怎么存放、怎么传下去。","options":[{"text":"提议合编一部簿录","correct":true,"tags":["才华","情缘"],"dims":{"才华":2,"情缘":1},"feedback":"他眼睛一亮：「好！你我合编一部金石簿录，传之后世。」","source":"夫妇合编簿录之志，见《金石录后序》。"},{"text":"说各管各的就好","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"他怔了怔：「也好……」可那盏灯，好像暗了一点。","source":"夫妇同好之乐，见《金石录后序》。"}],"difficulty":2,"npc":["夫君"],"foreshadow":"金石簿录"},{"id":"C-082","branch":"C","stage":4,"day":82,"shichen":"辰时","checkpoint":"晨起定省","scene":"在赵家的第一堂日常课：晨省。你赶在婆母起身前备好温水，在廊下恭立等候。","options":[{"text":"日日如此不怠","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"婆母起身后看见你，颔首：「难为你起得早。」","source":"晨昏定省之礼，见《仪礼》妇事舅姑。"},{"text":"睡过了头","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"赶到时婆母已盥洗毕。她没说重话，只道：「新妇贪睡，常情。」","source":"定省以时为敬，见《仪礼》。"}],"difficulty":2,"npc":["婆母"],"foreshadow":"定省"},{"id":"C-082-未","branch":"C","stage":4,"day":82,"shichen":"未时","checkpoint":"妯娌茶叙","scene":"午后二房两位嫂嫂来茶叙。大嫂温和，二嫂言语带钩：「听闻弟妹词名满汴京，我们这种人，只配管家了。」","options":[{"text":"接话说家最难得","correct":true,"tags":["名声","家世"],"dims":{"名声":1,"家世":1},"feedback":"你道：「词是玩的，家才是真的。往后还要嫂嫂们多教。」二嫂的钩子松了。","source":"妯娌相处以谦为先，见《仪礼》妇顺。"},{"text":"含笑不接话","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"不接话也是一种接话。二嫂回去说：新妇「拿大」。","source":"言默皆有锋，见《琅嬛记》。"}],"difficulty":3,"npc":["大嫂","二嫂"],"foreshadow":"妯娌"},{"id":"C-082-戌","branch":"C","stage":4,"day":82,"shichen":"戌时","checkpoint":"灯下说妯娌","scene":"夜里你与他说起妯娌茶叙。他说：「二嫂那个人，刀子嘴。你别往心里去，也别一味让。」","options":[{"text":"记下不怨不让","correct":true,"tags":["自主","家世"],"dims":{"自主":1,"家世":1},"feedback":"不怨，不让。四个字，是妯娌间的尺度。","source":"处妯娌之道，见《琅嬛记》。"},{"text":"抱怨她带钩","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"他静了静说：「在我跟前可以说，人前一个字也不能漏。」","source":"闺房私语之戒，见《仪礼》妇言。"}],"difficulty":2,"npc":["夫君"],"foreshadow":"不怨不让"},{"id":"C-083","branch":"C","stage":4,"day":83,"shichen":"辰时","checkpoint":"婆母考教","scene":"婆母把你叫去，指着账上一个月的开销：「这家里的账，你看看，看出什么说什么。」","options":[{"text":"指出三处可省","correct":true,"tags":["家世","才华"],"dims":{"家世":2,"才华":1},"feedback":"婆母一一看过：「嗯，眼力不错。可这处不能省——是人情。」她又教了你一层。","source":"家计之课，见《仪礼》妇职。"},{"text":"只说样样都好","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"婆母笑了：「样样都好，要你新妇看什么账？」","source":"考教贵有见地，见《琅嬛记》。"}],"difficulty":3,"npc":["婆母"],"foreshadow":"看账"},{"id":"C-083-未","branch":"C","stage":4,"day":83,"shichen":"未时","checkpoint":"接管小厨房","scene":"婆母把小厨房的对牌交给你：「先管一处，管好了再管大的。」这是你进门后接的第一份权。","options":[{"text":"接牌先盘旧账","correct":true,"tags":["家世","自主"],"dims":{"家世":1,"自主":1},"feedback":"旧账盘出两个窟窿，你没声张，先用自己的法子补上了。","source":"新妇渐预家政，见《仪礼》妇职。"},{"text":"接牌就换规矩","correct":false,"tags":["自主"],"dims":{"自主":2},"feedback":"新规矩出了三日，采买的媳妇先撂了挑子。","source":"新官忌骤改，见《宋刑统》家令之义。"}],"difficulty":3,"npc":["婆母","厨娘"],"foreshadow":"对牌"},{"id":"C-083-戌","branch":"C","stage":4,"day":83,"shichen":"戌时","checkpoint":"夜报夫君","scene":"夜里你把对牌的事说与他听。他听了只说一句：「我娘轻易不交对牌。她信你。」","options":[{"text":"说不敢辜负","correct":true,"tags":["家世","情缘"],"dims":{"家世":1,"情缘":1},"feedback":"他笑道：「你管厨房，我管书房。咱们各管一摊。」","source":"夫妇相勉，见《琅嬛记》。"},{"text":"说压力很大","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他说：「怕什么，做不好，还有我这个吃白饭的替你尝菜。」","source":"新婚相得，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":null},{"id":"C-084","branch":"C","stage":4,"day":84,"shichen":"辰时","checkpoint":"采买风波","scene":"小厨房第一桩事：采买的媳妇报虚账。你盘了三日，证据在手，如今要处置。","options":[{"text":"罚得明白又给台阶","correct":true,"tags":["家世","自主"],"dims":{"家世":2,"自主":1},"feedback":"按例罚月钱，又许她将功折罪。满厨房的仆妇都看见了新妇的手段。","source":"驭下恩威并施，见《仪礼》家治。"},{"text":"直接撵出去","correct":false,"tags":["自主"],"dims":{"自主":2},"feedback":"撵是撵了，可仆妇们从此对你敬而远之——威立住了，恩没跟上。","source":"御下过峻则离，见《宋刑统》家令之义。"}],"difficulty":3,"npc":["采买媳妇"],"foreshadow":"立威"},{"id":"C-084-未","branch":"C","stage":4,"day":84,"shichen":"未时","checkpoint":"婆母问案","scene":"婆母听闻处置，把你叫去问：「为何不撵？」你把盘算一五一十说了。","options":[{"text":"答撵不如用","correct":true,"tags":["家世","才华"],"dims":{"家世":1,"才华":1},"feedback":"婆母点头：「撵人是痛快，用人是本事。你想得比我远。」","source":"治家以用人为上，见《仪礼》义疏。"},{"text":"答第一次留情面","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"婆母道：「情面要留，账也要清。下回记住先说账。」","source":"治家之情理，见《琅嬛记》。"}],"difficulty":2,"npc":["婆母"],"foreshadow":null},{"id":"C-084-戌","branch":"C","stage":4,"day":84,"shichen":"戌时","checkpoint":"灯下记账","scene":"夜里你把小厨房的账理出个头绪，誊在一本新册子上。册子的格式，用的是你奁册的凡例。","options":[{"text":"把凡例推及家事","correct":true,"tags":["才华","自主"],"dims":{"才华":1,"自主":1},"feedback":"管书和管账，原来是一个道理——都要清清楚楚。","source":"簿录之法通于治家，见《金石录后序》记簿录。"},{"text":"记完就撂开","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"记是记了，可你总想起白日那媳妇的眼神——立威容易，收心难。","source":"闺中自省，见《琅嬛记》。"}],"difficulty":1,"npc":null,"foreshadow":null},{"id":"C-085","branch":"C","stage":4,"day":85,"shichen":"辰时","checkpoint":"庙见之日","scene":"入门满三月，庙见。你随公婆拜过赵家祖先。从今日起，你的名字正式写进了赵家的香火。","options":[{"text":"依礼行庙见","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"礼成。婆母扶你起来时，手上用了力——这一扶，就是一家人了。","source":"三月庙见方为成妇，见《仪礼》士昏礼。"},{"text":"紧张得几乎失仪","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"拜错了方位，喜娘悄悄拉正。祖宗面前的这一错，你记下了。","source":"庙见之礼，见《仪礼》。"}],"difficulty":3,"npc":["婆母","公公"],"foreshadow":"庙见成妇"},{"id":"C-085-未","branch":"C","stage":4,"day":85,"shichen":"未时","checkpoint":"庙见宴","scene":"庙见后家宴。你如今已名正言顺是赵家妇，席上的位置变了——不再是最末，是「长房新妇」。","options":[{"text":"敬每位尊长一盏","correct":true,"tags":["家世","名声"],"dims":{"家世":1,"名声":1},"feedback":"一圈敬下来，长房新妇的位置，坐稳了。","source":"家宴之礼，见《仪礼》。"},{"text":"只顾应酬同辈","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"婆母提醒：「先敬长。」座次即人伦，错了次序就是错了心。","source":"宴饮之序，见《仪礼》。"}],"difficulty":2,"npc":["亲族","婆母"],"foreshadow":null},{"id":"C-085-戌","branch":"C","stage":4,"day":85,"shichen":"戌时","checkpoint":"成妇之夜","scene":"夜里他说：「今日起，娘子便是我赵家列祖列宗认下的人了。」你忽然觉得「妇」这个字，又重又暖。","options":[{"text":"说会好好做赵家妇","correct":true,"tags":["情缘","家世"],"dims":{"情缘":1,"家世":1},"feedback":"他道：「我也是头一回做人夫君，咱们一起学。」","source":"新婚相勉，见《琅嬛记》。"},{"text":"问做不好怎么办","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他笑道：「做不好，就关起门来改。反正这辈子长着呢。」","source":"新婚情态，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":null,"flavor":true},{"id":"C-086","branch":"C","stage":4,"day":86,"shichen":"辰时","checkpoint":"花市买花","scene":"晨起他出门办公，临去从巷口卖花担上买回一枝春花，往你妆匣边一放就走。","options":[{"text":"簪花对镜","correct":true,"tags":["情缘","才华"],"dims":{"情缘":1,"才华":1},"feedback":"花在鬓边，人在镜中——「卖花担上，买得一枝春欲放」。","source":"汴京卖花之俗，见《东京梦华录》记花事。"},{"text":"插入瓶中供着","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"瓶中花是好，可他买的意思，是想看你戴。","source":"闺中情态，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":"花面词"},{"id":"C-086-未","branch":"C","stage":4,"day":86,"shichen":"未时","checkpoint":"比并看花","scene":"午后他回来得早，看见你鬓边的花，故意端详半晌。你偏头问他：「花好看，还是我好看？」","options":[{"text":"逗他比一比","correct":true,"tags":["情缘"],"dims":{"情缘":3},"feedback":"「云鬓斜簪，徒要教郎比并看。」他端详许久，说：「花输了。」","source":"新婚闺房之趣，见《琅嬛记》。"},{"text":"自己先不好意思","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"话出口就臊了。他笑着替你扶正花枝：「都好看。」","source":"新婚情态，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":"花面词","flavor":true,"yishou":true},{"id":"C-086-戌","branch":"C","stage":4,"day":86,"shichen":"戌时","checkpoint":"灯下小词","scene":"夜里你把「花与面」的事写成小词。写到「怕郎猜道，奴面不如花面好」，自己先笑出了声。","options":[{"text":"念给他听","correct":true,"tags":["才华","情缘"],"dims":{"才华":1,"情缘":2},"feedback":"他听完大笑：「冤枉！我几时那样猜过？」笑闹到二更。","source":"新婚词戏，见《琅嬛记》。"},{"text":"收进奁册不示人","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"奁册又厚一页。有些词，写出来就是念给一个人听的。","source":"闺词自娱，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":null},{"id":"C-087","branch":"C","stage":4,"day":87,"shichen":"辰时","checkpoint":"当袍买碑","scene":"他一早出门时兴冲冲：相国寺出了一卷旧碑，价钱谈不拢，他打算——当掉冬袍。","options":[{"text":"给他添些奁中金","correct":true,"tags":["情缘","家世"],"dims":{"情缘":2,"家世":1},"feedback":"你道：「袍子要穿，碑也要买。用我的。」他怔住，深深揖了一躬。","source":"夫妇相济以成所好，见《金石录后序》记质衣购碑。"},{"text":"劝他算了","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"他应了，可一整天魂不守舍。你明白，有些痴，是劝不掉的。","source":"士人金石之癖，见《金石录后序》。"}],"difficulty":2,"npc":["夫君"],"foreshadow":"奁金买碑"},{"id":"C-087-未","branch":"C","stage":4,"day":87,"shichen":"未时","checkpoint":"得碑而归","scene":"他抱着碑拓回来，像抱着全世界。顾不上掸尘，先拉你看：「你看这碑阴！你看这笔意！」","options":[{"text":"与他一同展卷","correct":true,"tags":["才华","情缘"],"dims":{"才华":1,"情缘":2},"feedback":"你们头碰头看到日影西斜，茶凉了三回。","source":"共赏碑拓之乐，见《金石录后序》。"},{"text":"笑他痴","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他也不恼：「娘子不痴？你那些词，也是这么来的。」","source":"夫妇互谑，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":null},{"id":"C-087-戌","branch":"C","stage":4,"day":87,"shichen":"戌时","checkpoint":"夜话知己","scene":"夜里他忽然认真道：「我从前想，娶个不拦我买碑的就知足了。谁知娶回来一个一起买的。」","options":[{"text":"说这叫志同道合","correct":true,"tags":["情缘","感情"],"dims":{"情缘":3},"feedback":"烛花爆了一声。你们看着对方，都觉得这一世，值了。","source":"知己之感，见《金石录后序》记夫妇同好。"},{"text":"说碑可买钱要省","correct":true,"tags":["家世","感情"],"dims":{"家世":1},"feedback":"他应着「是是是」，可你们都知道，下回遇见好碑，还是拦不住。","source":"金石之癖，见《金石录后序》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":"志同道合","flavor":true},{"id":"C-088","branch":"C","stage":4,"day":88,"shichen":"辰时","checkpoint":"对账","scene":"奁金贴补了碑钱，你要把这笔账记清楚。他凑过来看，说：「这笔我来还。」","options":[{"text":"记作共同之好","correct":true,"tags":["自主","情缘"],"dims":{"自主":1,"情缘":1},"feedback":"你在账上写：「奁金若干，购碑一卷，夫妇共赏。」这不是开销，是投资。","source":"奁金助夫之好，见《金石录后序》。"},{"text":"记作他欠的","correct":false,"tags":["自主"],"dims":{"自主":2},"feedback":"他认了账，笑着说要以拓片抵债。账是玩笑，情分是真的。","source":"闺中谐账，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":null},{"id":"C-088-未","branch":"C","stage":4,"day":88,"shichen":"未时","checkpoint":"妯娌过话","scene":"二嫂听闻你拿嫁妆给夫君买碑，来「关心」：「弟妹，嫁妆可是女人的命根子，哪能这么贴？」","options":[{"text":"答买碑即买日子","correct":true,"tags":["自主","名声"],"dims":{"自主":1,"名声":1},"feedback":"你道：「贴给一件两个人都爱的事，不叫贴，叫合。」二嫂没接住。","source":"妇财自主之辨，见《宋刑统》户婚律记妻财。"},{"text":"含糊带过","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"含糊也是种回答，可二嫂的版本已经传遍各房了。","source":"妇言招尤，见《琅嬛记》。"}],"difficulty":3,"npc":["二嫂"],"foreshadow":"妯娌"},{"id":"C-088-戌","branch":"C","stage":4,"day":88,"shichen":"戌时","checkpoint":"婆母的态度","scene":"晚间接见时，婆母忽然说：「听说你贴了奁金给他买碑？」你一凛，不知风向。","options":[{"text":"坦然说明缘由","correct":true,"tags":["家世","自主"],"dims":{"家世":1,"自主":1},"feedback":"婆母听完道：「他爹年轻时也这样。你们的钱你们做主，但记着——也要给自己留底。」","source":"奁产自主，见《宋刑统》户婚律。"},{"text":"急忙认错","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"婆母反道：「认什么错？我是怕他得寸进尺，败了你的底。」","source":"婆媳之常，见《琅嬛记》。"}],"difficulty":2,"npc":["婆母"],"foreshadow":"婆母之明"},{"id":"C-089","branch":"C","stage":4,"day":89,"shichen":"辰时","checkpoint":"他奋发","scene":"晨起他铺纸磨墨：「不能再白拿娘子的奁金。我要把这些年见的碑都考订成文，换润笔，也立言。」","options":[{"text":"替他研墨理纸","correct":true,"tags":["才华","情缘"],"dims":{"才华":1,"情缘":1},"feedback":"他写考据，你在旁校字。一室之内，两盏灯、两管笔。","source":"夫妇同撰之乐，见《金石录后序》记共勘校。"},{"text":"笑他三分钟热度","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"他急了：「这回是真的！」——是真是假，日子会作证。","source":"闺中谐语，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":"金石录之志"},{"id":"C-089-未","branch":"C","stage":4,"day":89,"shichen":"未时","checkpoint":"共校","scene":"午后他写考订，你帮着核对拓片上的字。有一处漫漶不清，你们争了半个时辰。","options":[{"text":"据理说出己见","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"最后查书证明你对。他击节：「从今往后，我校碑，我校不过你。」","source":"考据之争，见《金石录后序》记勘校。"},{"text":"让他一步算了","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"他反倒不乐意：「学问上你让我，是看不起我。」","source":"夫妇以学相敬，见《金石录后序》。"}],"difficulty":2,"npc":["夫君"],"foreshadow":"校碑"},{"id":"C-089-戌","branch":"C","stage":4,"day":89,"shichen":"戌时","checkpoint":"灯下同窗","scene":"夜里你们又坐到灯下，一人一段地校。他忽然说：「像不像在太学的同窗？」","options":[{"text":"答比同窗更好","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"同窗有别离，你们没有。这一张书案，是一辈子的。","source":"闺房之乐，见《金石录后序》。"},{"text":"说同窗不会分心","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他认了：「是，同窗不会看砚边人的侧脸。」","source":"新婚情态，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":"同窗","flavor":true},{"id":"C-090","branch":"C","stage":4,"day":90,"shichen":"辰时","checkpoint":"新婚满月","scene":"晨起丫鬟提醒：今日是你进门满月。婆母一早送来一对喜饼，二嫂也来了，难得的没带钩子。","options":[{"text":"谢过婆母妯娌","correct":true,"tags":["家世","名声"],"dims":{"家世":1,"名声":1},"feedback":"一个月了。从「新妇」到「家里人」，就差这一场满月。","source":"满月之礼，见《梦粱录》记嫁娶。"},{"text":"觉得不过尔尔","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"「尔尔」也是日子攒的。你收下饼，就是收下了这个家。","source":"妇事之常，见《仪礼》。"}],"difficulty":1,"npc":["婆母","二嫂"],"foreshadow":"满月"},{"id":"C-090-未","branch":"C","stage":4,"day":90,"shichen":"未时","checkpoint":"满月盘点","scene":"午后你独自盘点这一个月：规矩、人情、账目、碑帖，还有他。你头一回觉得「赵家妇」这个身份，合身穿了。","options":[{"text":"在奁册记满月","correct":true,"tags":["自主","才华"],"dims":{"自主":1,"才华":1},"feedback":"奁册翻到「嘉礼」那页，你在旁添了一行：「满月，心安。」","source":"闺中自记，见《琅嬛记》。"},{"text":"去园中走了走","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"这是赵家的园子。桂花明年还会开，你就是在这儿看它开的人。","source":"闺中情态，见《琅嬛记》。"}],"difficulty":1,"npc":null,"foreshadow":"里程碑·心安","flavor":true},{"id":"C-090-戌","branch":"C","stage":4,"day":90,"shichen":"戌时","checkpoint":"满月夜话","scene":"夜里他说：「一月了，委屈不委屈？」你想了想：「不委屈。就是——偶尔想娘家的桂花香。」","options":[{"text":"他说明年陪你回","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"他认真记下：「明年中秋，陪你回娘家看桂花。」这个约，立下了。","source":"归宁之约，见《梦粱录》。"},{"text":"你说说而已","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"他却当了真：「说出口的，就是约。我记下了。」","source":"夫妇之信，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":"桂花之约"},{"id":"C-091","branch":"C","stage":4,"day":91,"shichen":"辰时","checkpoint":"他忘了一件事","scene":"晨起你等他同去给婆母请安——说好的。可他的影子在书房，对着一卷碑，把这事忘了个干净。","options":[{"text":"先去请安再提","correct":true,"tags":["家世","自主"],"dims":{"家世":1,"自主":1},"feedback":"请安没误，回头你只说了句：「碑在，娘也在。分个先后。」他惭愧了半天。","source":"夫妇相处以分为先，见《仪礼》义疏。"},{"text":"当场去书房理论","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"声音传到前院，婆母听见了。理论赢了，体面输了。","source":"闺房之争不外人知，见《琅嬛记》闺戒。"}],"difficulty":2,"npc":["夫君","婆母"],"foreshadow":"磨合"},{"id":"C-091-未","branch":"C","stage":4,"day":91,"shichen":"未时","checkpoint":"赔礼","scene":"午后他抱着一卷新拓片来赔罪，说是「给娘子的奁册添的」。你板着的脸绷不住了。","options":[{"text":"收下但不轻饶","correct":true,"tags":["情缘","自主"],"dims":{"情缘":1,"自主":1},"feedback":"你收下拓片，记了他一笔：「再犯，罚抄《礼记》十遍。」","source":"闺房谐谑，见《琅嬛记》。"},{"text":"当场就笑了","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"笑是笑了，可他若觉得一卷拓片就能抵错，下回还敢。","source":"闺房之教，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":null},{"id":"C-091-戌","branch":"C","stage":4,"day":91,"shichen":"戌时","checkpoint":"夜话磨合","scene":"夜里你们都睡不着，说起白日的事。他说：「我这个人，看见金石就看不见别的。这毛病，你得帮我。」","options":[{"text":"说一起立个规矩","correct":true,"tags":["自主","情缘"],"dims":{"自主":1,"情缘":1},"feedback":"你们立了「先看人，再看碑」的约。他把这六个字写在了书房墙上。","source":"夫妇立约，见《琅嬛记》。"},{"text":"说改不了就算了","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"他摇头：「不能算了。你嫁的是我，不是碑。」这话你记住了。","source":"夫妇之省，见《琅嬛记》。"}],"difficulty":2,"npc":["夫君"],"foreshadow":"先看人再看碑"},{"id":"C-092","branch":"C","stage":4,"day":92,"shichen":"辰时","checkpoint":"重阳登高","scene":"九月初九，重阳。全家登高宴饮，佩茱萸、饮菊花酒。你如今的身份是「长房新妇」，张罗了半日。","options":[{"text":"把宴席张罗布妥","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"茱萸分遍各房，菊花酒温得正好。婆母当众夸：「新妇能当半个家了。」","source":"重阳登高宴饮，见《东京梦华录》记重阳。"},{"text":"只顾自己看菊","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"菊是好菊，可席面上的事，终究要有人管。","source":"妇预家政，见《仪礼》妇职。"}],"difficulty":2,"npc":["婆母","亲族"],"foreshadow":null},{"id":"C-092-未","branch":"C","stage":4,"day":92,"shichen":"未时","checkpoint":"登高望远","scene":"登高台上，满城秋色。他指给你看远处的相国寺、金明池，还有你们擦肩而过的那半池水。","options":[{"text":"与他说碑摊旧事","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"相国寺、半池水、当袍的玉佩——你们把缘分从头数了一遍。","source":"夫妇话旧，见《琅嬛记》。"},{"text":"只顾看秋色","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"秋色年年有，一起数缘分的话头，可不多。","source":"闺中情态，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":"缘分细数"},{"id":"C-092-戌","branch":"C","stage":4,"day":92,"shichen":"戌时","checkpoint":"重阳词","scene":"夜来风凉。你想起白日登高所见，写了一阕重阳词。写到「佳节又重阳」，笔停了停。","options":[{"text":"写完给他看","correct":true,"tags":["才华","情缘"],"dims":{"才华":2,"情缘":1},"feedback":"他读罢说：「比我写得好。」你说：「那当然。」","source":"重阳词，见《琅嬛记》。"},{"text":"只写给自己","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"「玉枕纱厨，半夜凉初透」——这词留着，日后自有去处。","source":"闺词自藏，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":"重阳词","flavor":true,"yishou":true},{"id":"C-093","branch":"C","stage":4,"day":93,"shichen":"辰时","checkpoint":"金石录开工","scene":"他郑重宣布：即日起编《金石录》，把平生所藏两千卷碑帖一一考订成书。他要你「共其事」。","options":[{"text":"应下共编之约","correct":true,"tags":["才华","情缘"],"dims":{"才华":2,"情缘":1},"feedback":"从此你们的书房多了一张大案，案上摊着一个两人才懂的天下。","source":"夫妇共编金石录，见《金石录后序》。"},{"text":"说自己才力不够","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"他正色：「相国寺补帖的眼力，满汴京找不出第二个。非你不可。」","source":"夫妇相成，见《金石录后序》。"}],"difficulty":2,"npc":["夫君"],"foreshadow":"金石录"},{"id":"C-093-未","branch":"C","stage":4,"day":93,"shichen":"未时","checkpoint":"编目分工","scene":"你们分工：他考订碑的源流，你校文字、理编目。两千卷，一天三卷，也要两年。","options":[{"text":"排下编目章程","correct":true,"tags":["才华","自主"],"dims":{"才华":1,"自主":1},"feedback":"章程定下：每日午后一个时辰，雷打不动。这部书，从今日起有命了。","source":"簿录编目之法，见《金石录后序》。"},{"text":"被两千卷吓住","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"他道：「两千卷多，可一天三卷不多。路是走出来的。」","source":"为学之志，见《续资治通鉴长编》记士风。"}],"difficulty":2,"npc":["夫君"],"foreshadow":"编目章程"},{"id":"C-093-戌","branch":"C","stage":4,"day":93,"shichen":"戌时","checkpoint":"首卷之夜","scene":"夜里你们校完《金石录》的第一卷。他郑重在卷末落笔，写完把笔递给你：「这卷，你我同署。」","options":[{"text":"推辞只校不署","correct":true,"tags":["名声","才华"],"dims":{"名声":1,"才华":1},"feedback":"他不依：「没有你的校，这卷出不来。」争到最后，署了「同校」二字。","source":"夫妇共校之谊，见《金石录后序》。"},{"text":"欣然同署","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"笔落下的那一刻，你忽然想：这一卷，会长过你们两个人。","source":"著述传世之志，见《金石录后序》。"}],"difficulty":2,"npc":["夫君"],"foreshadow":"同署","flavor":true},{"id":"C-094","branch":"C","stage":4,"day":94,"shichen":"辰时","checkpoint":"太学差事","scene":"他接到太学的差事，要离家小住旬日。晨起他收拾书箧，你帮着打点行装，一样样检点。","options":[{"text":"打点周到送出门","correct":true,"tags":["家世","情缘"],"dims":{"家世":1,"情缘":1},"feedback":"箧里寒衣、伤药、你爱吃的巷子口那家点心——最后一样是他塞给你的。","source":"士人赴学之常，见《东京梦华录》记太学。"},{"text":"舍不得拉着不放","correct":false,"tags":["情缘"],"dims":{"情缘":2},"feedback":"他笑着掰开你的手：「旬日就回。你校你的碑，我念我的人。」","source":"暂别之情，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":"小别"},{"id":"C-094-未","branch":"C","stage":4,"day":94,"shichen":"未时","checkpoint":"独校碑","scene":"午后你独自校碑。往日两个人的大案，今日空了一半。你把他校过的卷子又核了一遍。","options":[{"text":"核出两处错留笺","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"你留笺：「此处疑误，候君归议。」案头少了人，学问没少。","source":"校勘之严，见《金石录后序》记勘校。"},{"text":"没心思校搁下了","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"搁下笔你才知道，这部书已经是两个人的了——一个人校不动。","source":"共学之益，见《金石录后序》。"}],"difficulty":2,"npc":null,"foreshadow":null},{"id":"C-094-戌","branch":"C","stage":4,"day":94,"shichen":"戌时","checkpoint":"独眠之夜","scene":"夜里灯花爆了两回。你对着半边空榻想：「才一日。」原来人惯起来，比墨惯起来还快。","options":[{"text":"写小词寄太学","correct":true,"tags":["情缘","才华"],"dims":{"情缘":2,"才华":1},"feedback":"词短情长。明日托人带去——「一日不见」这四个字，古人诚不我欺。","source":"闺词寄远，见《琅嬛记》。"},{"text":"早早吹灯睡了","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"睡得早，醒得也早。天没亮你就在想，太学的更鼓是什么声。","source":"闺中情思，见《琅嬛记》。"}],"difficulty":1,"npc":null,"foreshadow":"寄词"},{"id":"C-095","branch":"C","stage":4,"day":95,"shichen":"辰时","checkpoint":"婆母交心","scene":"夫君不在，婆母唤你去说话，说的却是掏心窝子的话：「我年轻时也这样，他爹一进书斋就忘了人。男人痴起来，都这样。」","options":[{"text":"问婆母怎么过来的","correct":true,"tags":["家世","情缘"],"dims":{"家世":1,"情缘":1},"feedback":"婆母道：「他痴他的，你立你的。家是两个人的，一人塌了另一人得立住。」","source":"婆媳夜话，见《琅嬛记》。"},{"text":"只陪笑不接话","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"婆母看你一眼：「与我说话不用绕。我交的是心，你接不接？」","source":"婆媳之诚，见《仪礼》义疏。"}],"difficulty":2,"npc":["婆母"],"foreshadow":"婆母交心"},{"id":"C-095-未","branch":"C","stage":4,"day":95,"shichen":"未时","checkpoint":"掌中馈","scene":"他不在，小厨房加堂上三餐都归你调度。你按婆母旧例操持，只添了一样——给各房多送一盏汤。","options":[{"text":"添汤又添了情","correct":true,"tags":["家世","名声"],"dims":{"家世":1,"名声":1},"feedback":"一盏汤不值钱，可「长房新妇周到」这句话，传遍了各房。","source":"中馈之和，见《仪礼》妇职。"},{"text":"照旧例不多事","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"无过便是功。只是这半月，本可以是你立起来的时候。","source":"妇职之守，见《仪礼》。"}],"difficulty":2,"npc":["婆母","仆妇"],"foreshadow":null},{"id":"C-095-戌","branch":"C","stage":4,"day":95,"shichen":"戌时","checkpoint":"灯下自处","scene":"夜里你忽然想明白：嫁了人，不是把自己交给一个家，是把自己立在一个家里。","options":[{"text":"把这话写进奁册","correct":true,"tags":["自主","才华"],"dims":{"自主":2,"才华":1},"feedback":"「立」字写完，你觉得这个家，你又多懂了三分。","source":"闺中自省，见《琅嬛记》。"},{"text":"想了半宿","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"想是想了，没落笔的话，天亮就散了。","source":"闺中情思，见《琅嬛记》。"}],"difficulty":1,"npc":null,"foreshadow":"立字诀"},{"id":"C-096","branch":"C","stage":4,"day":96,"shichen":"辰时","checkpoint":"他回来了","scene":"旬日未满，他提前回来了。进门先去给婆母请了安，然后直奔书房——你正在那里校碑。","options":[{"text":"起身相迎","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"他站在门口看了你一会儿，说：「案头的碑长高了，你清减了。」","source":"归家之情，见《琅嬛记》。"},{"text":"嗔他怎么才回","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"他作揖：「是是是，为夫知罪。」你绷不住，先笑了。","source":"新婚谐语，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":null,"flavor":true},{"id":"C-096-未","branch":"C","stage":4,"day":96,"shichen":"未时","checkpoint":"案头留笺","scene":"他在案头看见你留的笺：「此处疑误，候君归议。」他展开拓片，对着你的小字看了半晌。","options":[{"text":"与他当面对证","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"核书半日，两处错都定了案。他说：「旬日不见，娘子的眼力又长了。」","source":"校勘之谊，见《金石录后序》。"},{"text":"只看他什么反应","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他的反应是：立刻磨墨，把两处都改了，边改边笑。","source":"夫妇共校，见《金石录后序》。"}],"difficulty":2,"npc":["夫君"],"foreshadow":null},{"id":"C-096-戌","branch":"C","stage":4,"day":96,"shichen":"戌时","checkpoint":"灯下重逢","scene":"夜里他把太学带回的新拓片铺了满桌，一张张讲给你听。旬日的话，一夕讲不完。","options":[{"text":"听他讲到更深","correct":true,"tags":["情缘","才华"],"dims":{"情缘":1,"才华":1},"feedback":"烛芯剪了三回。你们的话，比碑上的字还密。","source":"夫妇夜话，见《琅嬛记》。"},{"text":"催他早些安置","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"他应着，可讲到得意处，又忘了时辰。","source":"新婚情态，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":null},{"id":"C-097","branch":"C","stage":4,"day":97,"shichen":"辰时","checkpoint":"岁暮将近","scene":"十月过半，街上开始卖年画、历本。婆母把你叫去：「今年家里的年节，你来帮着我操办。」","options":[{"text":"应下先排章程","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"你按娘家的旧例加赵家的规矩，排出一份年节章程，婆母只改了两笔。","source":"岁暮备年，见《东京梦华录》记十月后节物。"},{"text":"推说头一年不懂","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"婆母道：「头一年不学，第二年还是不会。来，看着学。」","source":"妇预家政，见《仪礼》妇职。"}],"difficulty":2,"npc":["婆母"],"foreshadow":"年节章程"},{"id":"C-097-未","branch":"C","stage":4,"day":97,"shichen":"未时","checkpoint":"备冬衣","scene":"你督着针线房备全家的冬衣。夫君的那件棉袍——就是差点当掉的那件——你让人絮了双倍的棉。","options":[{"text":"加倍絮棉","correct":true,"tags":["情缘","家世"],"dims":{"情缘":1,"家世":1},"feedback":"他试穿时直说暖。你没告诉他，这袍子里絮的是上回没让你贴出去的奁金。","source":"冬衣之备，见《梦粱录》记十月。"},{"text":"按例制备","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"制是制齐了，只是他那件，到底薄了些。","source":"妇职备衣，见《仪礼》。"}],"difficulty":1,"npc":["针线娘子"],"foreshadow":"棉袍"},{"id":"C-097-戌","branch":"C","stage":4,"day":97,"shichen":"戌时","checkpoint":"冬夜校书","scene":"夜里书房烧了炭。你们校到一册五代人的墓志，字迹漫漶，他呵手，你添炭，谁也没说冷。","options":[{"text":"坚持校完这一卷","correct":true,"tags":["才华","自主"],"dims":{"才华":1,"自主":1},"feedback":"校完已近三更。他说：「有娘子在，再冷的夜也校得完。」","source":"冬夜校书，见《金石录后序》。"},{"text":"劝明日再校","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"他依了你。收卷时他说：「这活儿一个人干是苦，两个人干是乐。」","source":"共学之乐，见《金石录后序》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":null},{"id":"C-098","branch":"C","stage":4,"day":98,"shichen":"辰时","checkpoint":"夫家冬至","scene":"冬至。这是你以赵家妇身份过的第一个大节。晨起祭祖，你站在长房媳妇的位置上，排得笔直。","options":[{"text":"依礼助祭","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"礼成，婆母在祖宗牌位前说了句：「列祖列宗看着呢，咱们家添了个好媳妇。」","source":"冬至祭祖，见《东京梦华录》记冬至。"},{"text":"紧张得忘了词","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"祝词是婆母替你接的。她没说什么，可你夜里背了三遍。","source":"祭礼之辞，见《仪礼》。"}],"difficulty":2,"npc":["婆母","公公"],"foreshadow":null},{"id":"C-098-未","branch":"C","stage":4,"day":98,"shichen":"未时","checkpoint":"冬至宴","scene":"冬至宴上，你的位置又往前挪了。二嫂举杯敬你：「弟妹来了这些日子，家里是暖和了。」","options":[{"text":"回敬她一盏","correct":true,"tags":["名声","家世"],"dims":{"名声":1,"家世":1},"feedback":"钩子化了。你们对饮一盏，妯娌这一页，翻过去了。","source":"家宴之礼，见《仪礼》。"},{"text":"只笑了笑","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"笑是笑了，可她递过来的台阶，你总得踩一脚。","source":"妯娌之礼，见《琅嬛记》。"}],"difficulty":1,"npc":["二嫂"],"foreshadow":"妯娌冰释"},{"id":"C-098-戌","branch":"C","stage":4,"day":98,"shichen":"戌时","checkpoint":"冬至夜","scene":"夜里他说：「去年冬至，你还是李家待嫁的姑娘。今年，你是我赵家的人了。快不快？」","options":[{"text":"说快也慢","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"快的是日子，慢的是那些一个字一个字、一件事一件事过出来的心。","source":"夫妇话旧，见《琅嬛记》。"},{"text":"问他想念去年么","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他说：「不想。去年你还在别人家。我只往后看。」","source":"新婚情态，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":null,"flavor":true},{"id":"C-099","branch":"C","stage":4,"day":99,"shichen":"辰时","checkpoint":"腊月初","scene":"入了腊月，各房的节礼单子、祭品单子都送到你案头。你如今是婆母的「副手」了。","options":[{"text":"分轻重一一批复","correct":true,"tags":["家世","自主"],"dims":{"家世":1,"自主":1},"feedback":"一上午批复了三十几单，无一处错漏。管家娘子背地里说：「新妇是把好手。」","source":"腊日备节，见《东京梦华录》记十二月。"},{"text":"照去年单子批","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"有两房今年境况变了，照抄旧例，失了些分寸。","source":"馈送随时损益，见《梦粱录》。"}],"difficulty":2,"npc":["管家娘子"],"foreshadow":null},{"id":"C-099-未","branch":"C","stage":4,"day":99,"shichen":"未时","checkpoint":"熬腊八粥","scene":"腊月初八将近，你督着小厨房试熬腊八粥。豆、枣、栗、胡桃，一样样都是你亲手配的。","options":[{"text":"配好送各房尝","correct":true,"tags":["家世","名声"],"dims":{"家世":1,"名声":1},"feedback":"婆母尝了半碗，说：「比我年轻时配的还周全。」","source":"腊八熬粥馈亲，见《东京梦华录》记十二月八日。"},{"text":"交给厨娘配方子","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"粥是好粥，可这是你在赵家头一回熬腊八——该亲手。","source":"腊日亲馈，见《梦粱录》。"}],"difficulty":1,"npc":["婆母","厨娘"],"foreshadow":null},{"id":"C-099-戌","branch":"C","stage":4,"day":99,"shichen":"戌时","checkpoint":"腊夜小词","scene":"夜里窗外落了今冬头一场雪。你在灯下写腊日小词，他从背后看，念出声：「年年雪里，常插梅花醉。」","options":[{"text":"回头与他同看","correct":true,"tags":["情缘","才华"],"dims":{"情缘":1,"才华":1},"feedback":"「这句好。」他说，「雪里插梅——明年我们也去。」","source":"咏雪词，见《琅嬛记》。"},{"text":"合上不给看","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"他也不恼：「好词经得起藏。等你肯给我看，我再来讨。」","source":"闺词自珍，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":"插梅之约","yishou":true},{"id":"C-100","branch":"C","stage":4,"day":100,"shichen":"辰时","checkpoint":"成婚百日","scene":"晨起丫鬟道喜：今日是你过门百日。你从妆匣里取出奁册，翻到「嘉礼」那页——一百日了。","options":[{"text":"在册上记百日","correct":true,"tags":["自主","情缘"],"dims":{"自主":1,"情缘":1},"feedback":"你在「嘉礼」旁添了三个字：「百日，安。」","source":"闺中自记，见《琅嬛记》。"},{"text":"与他说一声","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"他愣了愣，随即笑道：「百日了？怎么像昨日才掀的盖头。」","source":"新婚情态，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":"百日","flavor":true},{"id":"C-100-未","branch":"C","stage":4,"day":100,"shichen":"未时","checkpoint":"百日盘点","scene":"午后你盘点这一百日：金石录校完四十卷，小厨房井井有条，婆母信任，妯娌和睦，他——很好。","options":[{"text":"觉此生可寄","correct":true,"tags":["情缘","自主"],"dims":{"情缘":1,"自主":1},"feedback":"「可寄」两个字，你写得很慢。这一生，可以托付了。","source":"闺中自省，见《琅嬛记》。"},{"text":"觉得还差得远","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"差得远是对的。日子还长，你的本事，才使出来三成。","source":"闺中自励，见《琅嬛记》。"}],"difficulty":1,"npc":null,"foreshadow":"阶段四半程","flavor":true},{"id":"C-100-戌","branch":"C","stage":4,"day":100,"shichen":"戌时","checkpoint":"百日之夜","scene":"夜里他神神秘秘拿出一个小锦匣：「百日之礼。」打开——是那枚当年押给摊主的玉佩，他赎回来了。","options":[{"text":"接过玉佩","correct":true,"tags":["情缘"],"dims":{"情缘":3},"feedback":"「押出去的时候，我就想要赎回来给你。」他说，「今日正好。」","source":"玉佩之赎，见《琅嬛记》记赠答。"},{"text":"认出是那块玉佩","correct":true,"tags":["情缘","才华"],"dims":{"情缘":2,"才华":1},"feedback":"你认出来了——相国寺碑摊，玉佩，押出去换碑的那一枚。兜兜转转，到了你手里。","source":"信物之遇，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":"玉佩归","flavor":true},{"id":"C-101","branch":"C","stage":4,"day":101,"shichen":"辰时","checkpoint":"除夕在赵家","scene":"除夕。今年你在赵家守岁。祭祖、分岁、守岁，一样样你都站到了该站的位置上。","options":[{"text":"依新妇之礼周旋","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"爆竹声里，婆母对你说：「明年，这些事就该你领着办了。」","source":"除夕诸仪，见《东京梦华录》记除夕。"},{"text":"心里想着娘家","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"想是真想。可你在心里说：今年，先当好赵家的人。","source":"岁暮之情，见《琅嬛记》。"}],"difficulty":1,"npc":["婆母","亲族"],"foreshadow":"领办年节"},{"id":"C-101-未","branch":"C","stage":4,"day":101,"shichen":"未时","checkpoint":"压岁","scene":"午后给各房小辈发压岁钱。你准备的岁钱每个红封里都多压了一枚小铜钱，叫「添岁」。","options":[{"text":"小辈们欢天喜地","correct":true,"tags":["名声","家世"],"dims":{"名声":1,"家世":1},"feedback":"孩子们满院喊「新婶娘最好」。妯娌们看你，眼神都软了。","source":"岁首分岁钱，见《梦粱录》记岁除。"},{"text":"按例分派","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"中规中矩。孩子们谢了礼，跑开了。","source":"岁钱之俗，见《东京梦华录》。"}],"difficulty":1,"npc":["各房小辈"],"foreshadow":null},{"id":"C-101-戌","branch":"C","stage":4,"day":101,"shichen":"戌时","checkpoint":"守岁夜话","scene":"守岁。地炉烧得正旺。他忽然说：「去年除夕，我在想，来年能不能娶到你。今年，你就在我身边。」","options":[{"text":"说我也一样","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"炉火哔剥。你们谁也没再说话，就这样坐到了五更。","source":"守岁之情，见《琅嬛记》。"},{"text":"笑他当时就想了","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他认了：「从相国寺碑摊那天起。」原来那日，他也看见了你。","source":"宿缘之语，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":"碑摊他也看见了","flavor":true},{"id":"C-102","branch":"C","stage":4,"day":102,"shichen":"辰时","checkpoint":"元日朝贺","scene":"元日。全家朝贺，你随婆母立在内眷之首。礼成后，婆母把一串钥匙递给你——库房的钥匙。","options":[{"text":"郑重接过","correct":true,"tags":["家世","自主"],"dims":{"家世":2,"自主":1},"feedback":"钥匙沉，责任更沉。婆母说：「这家，我交一半给你了。」","source":"新妇渐掌家事，见《仪礼》妇职。"},{"text":"推辞不敢接","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"婆母把钥匙塞进你手里：「让你接，就是信得过。」","source":"授事之信，见《琅嬛记》。"}],"difficulty":2,"npc":["婆母"],"foreshadow":"掌钥"},{"id":"C-102-未","branch":"C","stage":4,"day":102,"shichen":"未时","checkpoint":"开库","scene":"午后你拿着钥匙开了库房：器玩、绸缎、银钱、历年的账册，一库的家底。","options":[{"text":"按册点验一遍","correct":true,"tags":["家世","才华"],"dims":{"家世":1,"才华":1},"feedback":"点验三日才完。这个家的底，你心里从此有了一本清账。","source":"主母掌库，见《仪礼》妇职。"},{"text":"只大致看了一圈","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"看是看过了，可哪口箱子装的什么，你还说不上来。","source":"掌库贵明晰，见《琅嬛记》。"}],"difficulty":3,"npc":["婆母","管家"],"foreshadow":"掌库"},{"id":"C-102-戌","branch":"C","stage":4,"day":102,"shichen":"戌时","checkpoint":"元夜感怀","scene":"夜里你想起去年今日——那时你还是屏后奉茶的李家姑娘。一年，就一年，天翻地覆。","options":[{"text":"写词记这一年","correct":true,"tags":["才华","情缘"],"dims":{"才华":2,"情缘":1},"feedback":"一阕词写了又改，改了又写。这一年的分量，词都快盛不下了。","source":"岁首感怀，见《琅嬛记》。"},{"text":"与他说说而已","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他说：「再过十年，我们回头看今年，大概也是这样。」","source":"夫妇话旧，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":null},{"id":"C-103","branch":"C","stage":4,"day":103,"shichen":"辰时","checkpoint":"上元将近","scene":"正月十五将近，满城又张灯。今年你与他是「夫妇同游」——去年只能遥遥一望，今年可以并肩。","options":[{"text":"盼与他同看灯","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"去年是「众里寻他」，今年是「并肩看灯」。中间只隔了一年。","source":"上元夫妇同游，见《武林旧事》记元夕。"},{"text":"说人多不想去","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"他笑道：「去年你隔着半条街看我，今年倒不肯去了？」","source":"元夕游观，见《东京梦华录》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":"上元同游"},{"id":"C-103-未","branch":"C","stage":4,"day":103,"shichen":"未时","checkpoint":"备灯谜","scene":"午后他备了几个灯谜，说是今晚要在灯下考你。你也不甘示弱，回敬了三个。","options":[{"text":"谜面嵌了词牌","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"你的谜面是「灯前一诺」，谜底——「好事近」。他看了直拍案。","source":"灯谜雅戏，见《武林旧事》记灯品。"},{"text":"备了寻常的谜","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"寻常谜也中，只是灯节这样的夜，该配不寻常的谜。","source":"灯谜之戏，见《武林旧事》。"}],"difficulty":2,"npc":["夫君"],"foreshadow":null},{"id":"C-103-戌","branch":"C","stage":4,"day":103,"shichen":"戌时","checkpoint":"并肩看灯","scene":"夜灯如昼。你和他并肩走在灯山里，走到去年你站过的那座桥。他停下说：「去年今日，我在这里看见了你。」","options":[{"text":"说我也看见了你","correct":true,"tags":["情缘","感情"],"dims":{"情缘":3},"feedback":"灯影人声里，你们站了很久。去年的一眼，换来今年的并肩。","source":"上元定情，见《武林旧事》记元夕。"},{"text":"靠在他肩上","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"满城灯火都是陪衬。这一夜，你只记住了身边这个人。","source":"闺中情态，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":"上元定情","flavor":true},{"id":"C-104","branch":"C","stage":4,"day":104,"shichen":"辰时","checkpoint":"娘家送灯","scene":"正月十六，娘家送来灯节礼，还有母亲的手信。信上说：「闻你掌了赵家的钥匙，为娘很放心。」","options":[{"text":"回信报平安","correct":true,"tags":["家世","情缘"],"dims":{"家世":1,"情缘":1},"feedback":"回信写了三页：家宅平安，夫君待我好，金石录校到八十卷了。","source":"归宁通问，见《仪礼》之义。"},{"text":"只说一切都好","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"「一切都好」四个字太短，娘会翻来覆去地想：到底怎么个好法？","source":"家书贵详，见《琅嬛记》。"}],"difficulty":1,"npc":["母亲"],"foreshadow":null},{"id":"C-104-未","branch":"C","stage":4,"day":104,"shichen":"未时","checkpoint":"词名再传","scene":"你的元宵词不知怎么又传了出去，这回落款没藏住——汴京人都知道，「词女」嫁了，嫁得极好。","options":[{"text":"不置可否","correct":true,"tags":["名声","自主"],"dims":{"名声":2,"自主":1},"feedback":"你由它传。嫁得极好这件事，你确实没什么可谦虚的。","source":"才名之传，见《琅嬛记》。"},{"text":"请族兄代为澄清","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"族兄回信大笑：「澄清什么？这事儿越描越好！」","source":"佳话不可禁，见《琅嬛记》。"}],"difficulty":2,"npc":["族兄"],"foreshadow":"词名"},{"id":"C-104-戌","branch":"C","stage":4,"day":104,"shichen":"戌时","checkpoint":"灯下论名","scene":"夜里他提起词名的事：「外头都说我娶了个『词女』，占了天大的便宜。」","options":[{"text":"说彼此成全","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"「你成我的词，我全你的碑。」他说，「这叫天生一对。」","source":"夫妇相成，见《金石录后序》。"},{"text":"说便宜的是他","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他认了：「是是是，是我占了便宜，占一辈子。」","source":"新婚谐语，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":null},{"id":"C-105","branch":"C","stage":4,"day":105,"shichen":"辰时","checkpoint":"金石录百卷","scene":"晨起你们校完了《金石录》的第一百卷。案头的碑帖摞起来，已经高过了椅背。","options":[{"text":"提议小酌庆祝","correct":true,"tags":["情缘","才华"],"dims":{"情缘":1,"才华":1},"feedback":"你们温了一小壶酒，对着满案碑帖碰了杯——敬金石，也敬彼此。","source":"著述之乐，见《金石录后序》。"},{"text":"只记下数目","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"「一百卷」记在簿上，可这一百个灯下的夜晚，是记不下的。","source":"簿录之记，见《金石录后序》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":"百卷"},{"id":"C-105-未","branch":"C","stage":4,"day":105,"shichen":"未时","checkpoint":"婆母再托","scene":"午后婆母把账房的总对牌也交给了你：「过了百日，又看了你这些日子——这家，你管得。」","options":[{"text":"接过总对牌","correct":true,"tags":["家世","自主"],"dims":{"家世":2,"自主":1},"feedback":"钥匙、对牌，都在你手里了。你从「新妇」，成了「当家娘子」。","source":"主母掌家，见《仪礼》妇职。"},{"text":"惶恐推让","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"婆母道：「让是礼，接是责。我给你的，不是权，是担子。」","source":"授受之义，见《仪礼》。"}],"difficulty":2,"npc":["婆母"],"foreshadow":"当家"},{"id":"C-105-戌","branch":"C","stage":4,"day":105,"shichen":"戌时","checkpoint":"当家之夜","scene":"夜里你在灯下理账，他校他的碑。两张案子，一盏灯。你忽然想：这大概就是「岁月静好」的模样。","options":[{"text":"把此刻写进词","correct":true,"tags":["才华","情缘"],"dims":{"才华":2,"情缘":1},"feedback":"词成。词里没有「岁月静好」四个字，可每个字都是。","source":"闺词记乐，见《琅嬛记》。"},{"text":"静静各忙各的","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"不说话，也是在一起。灯花爆了，你们同时抬头，笑了笑。","source":"闺房之乐，见《金石录后序》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":"阶段四毕","flavor":true},{"id":"C-106","branch":"C","stage":5,"day":106,"shichen":"辰时","checkpoint":"春回","scene":"又是一年春。园子里的海棠打了苞——你想起待嫁那年雨后的海棠，和那个「绿肥红瘦」的清晨。","options":[{"text":"把旧词翻出来看","correct":true,"tags":["才华","情缘"],"dims":{"才华":1,"情缘":1},"feedback":"旧词还在，看词的人心境不同了。那时的忐忑，都开成了今日的花。","source":"海棠词之旧，见《琅嬛记》。"},{"text":"折一枝供案头","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他见了笑道：「又一年海棠。」你们都记得。","source":"闺中感物，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":"海棠又开"},{"id":"C-106-未","branch":"C","stage":5,"day":106,"shichen":"未时","checkpoint":"奁册合壁","scene":"午后你把奁册的书画目和《金石录》的编目对照——两家的藏，两个人，两册书，正合成一部。","options":[{"text":"提议两册合一","correct":true,"tags":["才华","自主"],"dims":{"才华":2,"自主":1},"feedback":"合璧的那页你写：「二藏既合，如人既偶。」","source":"夫妇合藏，见《金石录后序》记归来堂。"},{"text":"还是各记各的","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"各记各的也行，只是「合璧」两个字，错过可惜。","source":"簿录之合，见《金石录后序》。"}],"difficulty":2,"npc":null,"foreshadow":"合璧"},{"id":"C-106-戌","branch":"C","stage":5,"day":106,"shichen":"戌时","checkpoint":"春夜","scene":"夜里海棠香透窗纱。你和他一案校书，一窗花香，谁都不说话。","options":[{"text":"记下这一刻","correct":true,"tags":["情缘","才华"],"dims":{"情缘":1,"才华":1},"feedback":"你在词稿边批了一行小字：「此时无声，胜于有声。」","source":"闺中记乐，见《琅嬛记》。"},{"text":"就静静坐着","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"有些时刻，记下来都是辜负。你选择了不辜负。","source":"闺房之乐，见《金石录后序》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":null,"flavor":true},{"id":"C-107","branch":"C","stage":5,"day":107,"shichen":"辰时","checkpoint":"归宁之约","scene":"他翻着历书忽然说：「去年中秋我说过，陪你回娘家看桂花。桂花开在八月——先陪你回门省亲如何？」","options":[{"text":"喜出望外","correct":true,"tags":["情缘","家世"],"dims":{"情缘":2,"家世":1},"feedback":"你笑着应下。他说过的话，句句都算数。","source":"归宁之礼，见《仪礼》。"},{"text":"说不用特意","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"他道：「特意？你是我明媒正娶的娘子，回娘家是天经地义。」","source":"归宁之义，见《仪礼》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":"归宁"},{"id":"C-107-未","branch":"C","stage":5,"day":107,"shichen":"未时","checkpoint":"省亲","scene":"归宁那日，你的马车刚停稳，母亲已经在门口。父亲在堂上，背挺得笔直——和送你上轿那天一样。","options":[{"text":"先拜双亲再叙话","correct":true,"tags":["家世","情缘"],"dims":{"家世":1,"情缘":2},"feedback":"母亲拉着你看了又看：「胖了。」胖没胖不重要，重要的是你回来了。","source":"归宁拜亲，见《仪礼》。"},{"text":"一进门就红了眼","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"眼圈红了，笑也在。母亲说：「回门是要笑的。」你们就笑着红了眼。","source":"归宁之情，见《琅嬛记》。"}],"difficulty":1,"npc":["父亲","母亲"],"foreshadow":null,"flavor":true},{"id":"C-107-戌","branch":"C","stage":5,"day":107,"shichen":"戌时","checkpoint":"娘家夜话","scene":"夜里母亲在你旧房里坐。房间空了大半年，陈设一点没动。母亲说：「这间房，永远给你留着。」","options":[{"text":"抱住母亲","correct":true,"tags":["情缘"],"dims":{"情缘":3},"feedback":"什么话都不用说。这间房、这个人，永远给你留着。","source":"母女之情，见《琅嬛记》。"},{"text":"说我在那边很好","correct":true,"tags":["家世","情缘"],"dims":{"家世":1,"情缘":1},"feedback":"你说了许多「好」：婆母好，夫君好，日子好。母亲听着，笑着，抹了三次眼。","source":"归宁报喜，见《琅嬛记》。"}],"difficulty":1,"npc":["母亲"],"foreshadow":"旧房留着","flavor":true},{"id":"C-108","branch":"C","stage":5,"day":108,"shichen":"辰时","checkpoint":"金石录过半","scene":"晨起案头清点：《金石录》校完一百五十卷，过半了。他在卷目上画了个圈：「过半，就是近了。」","options":[{"text":"与他击掌","correct":true,"tags":["才华","情缘"],"dims":{"才华":1,"情缘":1},"feedback":"一百五十卷，一卷一个灯下的夜。这部书，是你们的「日子书」。","source":"著述之程，见《金石录后序》。"},{"text":"说还有一半","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"他道：「一半怕什么？我们从第一卷走到这里，后半程只会更快。」","source":"为学之志，见《金石录后序》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":"金石录过半"},{"id":"C-108-未","branch":"C","stage":5,"day":108,"shichen":"未时","checkpoint":"持家与校书","scene":"如今你白日当家理事，午后校书，夜里还要理奁产账目。有人问你累不累。","options":[{"text":"答累但心里满","correct":true,"tags":["自主","家世"],"dims":{"自主":1,"家世":1},"feedback":"累是真的，满也是真的。这样的日子，是你自己挣来的。","source":"妇职与妇学并修，见《琅嬛记》。"},{"text":"答还好","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"「还好」两个字说多了，连自己都要信了。其实你知道，是「很好」。","source":"闺中自省，见《琅嬛记》。"}],"difficulty":1,"npc":null,"foreshadow":null},{"id":"C-108-戌","branch":"C","stage":5,"day":108,"shichen":"戌时","checkpoint":"灯下白发","scene":"夜里校书，烛光里你看见他鬓边一根白发。你伸手替他拔了。","options":[{"text":"问他累不累","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"他反问你。你们相视一笑——都累，都不说，都值。","source":"夫妇相恤，见《琅嬛记》。"},{"text":"什么也没说","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"白发拔了，你没说。可那一下，你的心疼了疼。","source":"闺中情态，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":null},{"id":"C-109","branch":"C","stage":5,"day":109,"shichen":"辰时","checkpoint":"族中来求","scene":"族中一位远亲来求：想把女儿送来与你「学规矩」。你知道这是冲着你的名声来的。","options":[{"text":"应下但立规矩","correct":true,"tags":["名声","家世"],"dims":{"名声":1,"家世":1},"feedback":"你道：「学可以，先学理家，再学文墨。」名声是你挣的，规矩也是你立的。","source":"闺学相传，见《琅嬛记》。"},{"text":"婉拒","correct":false,"tags":["自主"],"dims":{"自主":2},"feedback":"拒得得体，人家挑不出错。可你夜里想：一身的本事，不传可惜了。","source":"闺学之择，见《琅嬛记》。"}],"difficulty":2,"npc":["远亲"],"foreshadow":"传学"},{"id":"C-109-未","branch":"C","stage":5,"day":109,"shichen":"未时","checkpoint":"词集之议","scene":"午后他提议：「娘子这些年的词，该编一编了。不为传世，就为它们自己。」","options":[{"text":"应下自编词集","correct":true,"tags":["才华"],"dims":{"才华":3},"feedback":"你把奁册底的词稿一页页翻出来，从溪亭日暮编到花面比并——你的半生，都在词里。","source":"自编词集，见《琅嬛记》记闺词结集。"},{"text":"说再等等","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"他道：「等什么呢？词是你写的，集是你编的，怕什么。」","source":"著述之志，见《金石录后序》。"}],"difficulty":2,"npc":["夫君"],"foreshadow":"词集"},{"id":"C-109-戌","branch":"C","stage":5,"day":109,"shichen":"戌时","checkpoint":"编词之夜","scene":"夜里你编词集。编到「倚门回首，却把青梅嗅」，你笑了——这一阕，如今可以见人了。","options":[{"text":"把它编入集中","correct":true,"tags":["才华","情缘"],"dims":{"才华":2,"情缘":1},"feedback":"编到这一页，你叫了他来看。他读完，半天说：「原来你那么早就……」","source":"闺词示人，见《琅嬛记》。"},{"text":"还是舍不得","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他道：「舍得舍得，舍了才得。这阕词，该让世人看看。」","source":"闺词之藏与传，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":"词集编成"},{"id":"C-110","branch":"C","stage":5,"day":110,"shichen":"辰时","checkpoint":"一年将满","scene":"晨起翻历书，距你出阁，快一年了。这一年，你从「李家词女」成了「赵家当家娘子」。","options":[{"text":"在奁册记一年","correct":true,"tags":["自主","才华"],"dims":{"自主":1,"才华":1},"feedback":"奁册上你写：「一年。心安，身立，事成其半。」","source":"闺中自记，见《琅嬛记》。"},{"text":"与他数这一年","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"你们从花烛夜数到今日，数了一百多件事，件件都是好日子。","source":"夫妇话旧，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":"一年","flavor":true},{"id":"C-110-未","branch":"C","stage":5,"day":110,"shichen":"未时","checkpoint":"婆母的信","scene":"午后婆母把你叫去，郑重交付了一样东西——赵家祠堂的祭器簿。「这个，该你管了。」","options":[{"text":"拜手接过","correct":true,"tags":["家世"],"dims":{"家世":3},"feedback":"祭器簿到手，意味着你正式是赵家的「宗妇」了。香火传承，有你一份。","source":"宗妇掌祭器，见《仪礼》宗妇之职。"},{"text":"惶恐辞谢","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"婆母道：「我像你这么大时就接了。赵家的媳妇，一代比一代强。」","source":"宗妇之任，见《仪礼》。"}],"difficulty":2,"npc":["婆母"],"foreshadow":"宗妇"},{"id":"C-110-戌","branch":"C","stage":5,"day":110,"shichen":"戌时","checkpoint":"宗妇之夜","scene":"夜里你说起祭器簿，他替你高兴：「我娘把这个交给你，就是把赵家的『体统』交给你了。」","options":[{"text":"说不敢辜负","correct":true,"tags":["家世","情缘"],"dims":{"家世":1,"情缘":1},"feedback":"他道：「你不会辜负。你连自己都没辜负过。」","source":"夫妇相勉，见《琅嬛记》。"},{"text":"问体统是什么","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"他想了想：「体统就是——这个家为什么是这个家。」","source":"家道之义，见《仪礼》义疏。"}],"difficulty":1,"npc":["夫君"],"foreshadow":null,"flavor":true},{"id":"C-111","branch":"C","stage":5,"day":111,"shichen":"辰时","checkpoint":"词集编成","scene":"晨起你把词集最后一页编定。从溪亭日暮到泼茶香，一集在手，你的前半生尽收其中。","options":[{"text":"题名《漱玉》","correct":true,"tags":["才华"],"dims":{"才华":3},"feedback":"「漱玉」——词如漱玉，清越有声。这个名字，配得上这些句子。","source":"闺词结集，见《琅嬛记》。"},{"text":"暂不题名","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"名字不着急。可一部没有名字的集子，像一场没有名分的心事。","source":"集名之重，见《琅嬛记》。"}],"difficulty":1,"npc":null,"foreshadow":"漱玉集"},{"id":"C-111-未","branch":"C","stage":5,"day":111,"shichen":"未时","checkpoint":"他读词集","scene":"午后他从头到尾读了一遍词集。读到最后一页，他放下书，郑重向你长揖。","options":[{"text":"问他何至于此","correct":true,"tags":["情缘","才华"],"dims":{"情缘":1,"才华":1},"feedback":"他道：「我娶你的时候，以为娶的是李家娘子。今日才知，娶的是一位词人。」","source":"夫妇相敬，见《金石录后序》。"},{"text":"笑着回礼","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"你回了礼。这一揖一回之间，是夫妇，更是知己。","source":"夫妇之礼，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":null,"flavor":true},{"id":"C-111-戌","branch":"C","stage":5,"day":111,"shichen":"戌时","checkpoint":"词集之夜","scene":"夜里他把《漱玉集》供在书房正中，与《金石录》的稿本并排。他说：「这两部书，就是咱们俩。」","options":[{"text":"并册而观","correct":true,"tags":["情缘","才华"],"dims":{"情缘":2,"才华":1},"feedback":"一词一碑，一柔一刚。并排而立，恰似灯下两个人。","source":"夫妇著述并峙，见《金石录后序》。"},{"text":"说还差得远","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"他道：「差得远才好。往后的日子，就是往这两部书里添东西。」","source":"著述之志，见《金石录后序》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":"两书并立"},{"id":"C-112","branch":"C","stage":5,"day":112,"shichen":"辰时","checkpoint":"暮春","scene":"三月暮，春将尽。园中落红成阵。你立在花下，想起那首海棠词——「应是绿肥红瘦」。","options":[{"text":"看落花不伤感","correct":true,"tags":["自主","才华"],"dims":{"自主":1,"才华":1},"feedback":"花落是花落，你是你。明年它还开，你还在。","source":"伤春不如惜时，见《琅嬛记》。"},{"text":"难免有些怅惘","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"怅惘也是词料。你记了一笔：「春归何处？寂寞无行路。」","source":"惜春之词，见《琅嬛记》。"}],"difficulty":1,"npc":null,"foreshadow":null},{"id":"C-112-未","branch":"C","stage":5,"day":112,"shichen":"未时","checkpoint":"金石录冲刺","scene":"午后校书。他说：「还剩三十卷。这个春天，我们把它校完。」你研墨的手紧了紧。","options":[{"text":"应下这个冲刺","correct":true,"tags":["才华","自主"],"dims":{"才华":1,"自主":1},"feedback":"三十卷，一日两卷，半月可毕。这部书，要见天日了。","source":"著述之勤，见《金石录后序》。"},{"text":"怕太急出错","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"他道：「有你把关，快不了也错不了。」","source":"校勘之信，见《金石录后序》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":"金石录冲刺"},{"id":"C-112-戌","branch":"C","stage":5,"day":112,"shichen":"戌时","checkpoint":"灯下连校","scene":"夜里你们连校三卷。更鼓敲过三下，他说：「再校一卷。」你说：「再校一卷。」","options":[{"text":"再校一卷","correct":true,"tags":["才华","情缘"],"dims":{"才华":2,"情缘":1},"feedback":"四卷校完，天将破晓。这一夜，顶平常的三日。","source":"夜以继日之乐，见《金石录后序》。"},{"text":"拦他去睡","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"他依了你。可躺下了你们还在说：「白日那卷碑，还有一处可议。」","source":"著述之痴，见《金石录后序》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":null},{"id":"C-113","branch":"C","stage":5,"day":113,"shichen":"辰时","checkpoint":"藏室满架","scene":"晨起你走进藏室——两家的金石书画已经满架。你想起待嫁那年父亲说的：「这些，你们替我看着。」","options":[{"text":"再添一层架子","correct":true,"tags":["家世","才华"],"dims":{"家世":1,"才华":1},"feedback":"架子添了，藏还会长。这间藏室，会像你们的日子一样，越来越满。","source":"收藏日富，见《金石录后序》记归来堂。"},{"text":"盘点一遍","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"盘点半日，你心里有数：这个家最值钱的东西，不在库房，在这间藏室。","source":"收藏之重，见《金石录后序》。"}],"difficulty":1,"npc":null,"foreshadow":"归来堂"},{"id":"C-113-未","branch":"C","stage":5,"day":113,"shichen":"未时","checkpoint":"题名藏室","scene":"午后他提议给藏室起个名字。你们想了又想，他说：「不如叫『归来』——所有的好东西，都归到这里来。」","options":[{"text":"题「归来堂」三字","correct":true,"tags":["才华","情缘"],"dims":{"才华":2,"情缘":1},"feedback":"你亲笔题了「归来堂」。归来，是物的归来，也是心的归来。","source":"归来堂之名，见《金石录后序》。"},{"text":"说再想想","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"再想也想不到更好的了。归来，归来——好名字就是这样，越想越对。","source":"堂名之志，见《金石录后序》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":"归来堂"},{"id":"C-113-戌","branch":"C","stage":5,"day":113,"shichen":"戌时","checkpoint":"归来堂首夜","scene":"夜里你们在归来堂坐了许久。满架的碑帖书画，一室的墨香。他说：「往后几十年，我们就在这儿了。」","options":[{"text":"说此生足矣","correct":true,"tags":["情缘"],"dims":{"情缘":3},"feedback":"「足矣」两个字，你说得很轻，可它落地有声。","source":"归来堂之乐，见《金石录后序》。"},{"text":"规划往后的收藏","correct":true,"tags":["自主","才华"],"dims":{"自主":1,"才华":1},"feedback":"你们说：东边添书柜，西边放画轴，中间的案子——永远是你们两个人的。","source":"归来堂之规，见《金石录后序》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":"归来堂","flavor":true},{"id":"C-114","branch":"C","stage":5,"day":114,"shichen":"辰时","checkpoint":"金石录收尾","scene":"晨起你们校《金石录》倒数第十卷。案头的日历只剩薄薄几页——这部书，要成了。","options":[{"text":"愈近愈不敢慢","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"收尾的卷子校得比开头还细。你们都知道：好东西，要配得上自己的结尾。","source":"著述之慎，见《金石录后序》。"},{"text":"忍不住加快","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"快是快了，可核出一处错。你们退回去，重校。","source":"校勘贵稳，见《金石录后序》。"}],"difficulty":2,"npc":["夫君"],"foreshadow":"金石录尾声"},{"id":"C-114-未","branch":"C","stage":5,"day":114,"shichen":"未时","checkpoint":"倒数第五卷","scene":"午后校到倒数第五卷——一卷上古的钟鼎铭文。你说：「这些字三千年了，落在我们手里。」","options":[{"text":"肃然起敬","correct":true,"tags":["才华","家世"],"dims":{"才华":1,"家世":1},"feedback":"三千年前的字，由你们校定。这件事，比两个人的日子还大。","source":"金石之古，见《金石录后序》。"},{"text":"只觉得震撼","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"震撼是对的。校这样的字，手都该轻一点。","source":"敬古之心，见《金石录后序》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":null},{"id":"C-114-戌","branch":"C","stage":5,"day":114,"shichen":"戌时","checkpoint":"夜话身后名","scene":"夜里他忽然问：「你说，这部书能传下去吗？」","options":[{"text":"答能","correct":true,"tags":["才华","情缘"],"dims":{"才华":1,"情缘":1},"feedback":"你道：「字是真的，校是实的，心是诚的。这样的书，天都会帮着传。」","source":"著述传世之信，见《金石录后序》。"},{"text":"答传不传随它","correct":false,"tags":["自主"],"dims":{"自主":2},"feedback":"他笑了：「也对。我们做它，本来就不是为了『传』。」","source":"著述之志，见《金石录后序》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":"身后名"},{"id":"C-115","branch":"C","stage":5,"day":115,"shichen":"辰时","checkpoint":"金石录成","scene":"晨起，最后一卷校完。《金石录》二百卷，全成。你们在案前站了许久，谁也没说话。","options":[{"text":"抚卷良久","correct":true,"tags":["才华","情缘"],"dims":{"才华":2,"情缘":2},"feedback":"二百卷，一年零三个月，几百个灯下夜。这部书，是你们俩的命。","source":"金石录之成，见《金石录后序》。"},{"text":"说该喝一杯","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"你们温了酒，对着二百卷书碰了杯。敬金石，敬彼此，敬这一年。","source":"著述之乐，见《金石录后序》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":"金石录成","flavor":true},{"id":"C-115-未","branch":"C","stage":5,"day":115,"shichen":"未时","checkpoint":"成书之庆","scene":"午后你亲笔誊写了书签：「金石录，二百卷。」落款时你顿了顿——署谁的名？","options":[{"text":"署两人之名","correct":true,"tags":["情缘","才华"],"dims":{"情缘":1,"才华":2},"feedback":"他看了许久，说：「好。这部书，本来就是我们两个人的。」","source":"著述同署，见《金石录后序》。"},{"text":"只署他的名","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"他不依：「没有你的校，没有这部书。署名之事，没有你商量。」","source":"夫妇之公，见《金石录后序》。"}],"difficulty":2,"npc":["夫君"],"foreshadow":"同署"},{"id":"C-115-戌","branch":"C","stage":5,"day":115,"shichen":"戌时","checkpoint":"成书之夜","scene":"夜里你把《金石录》稿本和《漱玉集》并排供在归来堂。两部书，一对人。","options":[{"text":"在案前坐到夜深","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"烛火静静烧。你想：人生至此，真的可以打住了。","source":"闺中自足，见《琅嬛记》。"},{"text":"与他规划下一部","correct":true,"tags":["自主","才华"],"dims":{"自主":1,"才华":1},"feedback":"你们已经在说下一部了——这样的人，是停不下来的。","source":"著述之志，见《金石录后序》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":null,"flavor":true},{"id":"C-116","branch":"C","stage":5,"day":116,"shichen":"辰时","checkpoint":"出阁周年","scene":"晨起丫鬟道喜——今日是你出阁一周年。一年前的此刻，你正盖着盖头，坐在去赵家的花轿里。","options":[{"text":"晨起对镜一笑","correct":true,"tags":["情缘","自主"],"dims":{"情缘":1,"自主":1},"feedback":"镜中的你，鬓边是他去年上元夜送的花钿。一年了，越看越合适。","source":"闺中自记，见《琅嬛记》。"},{"text":"去给父母问安","correct":true,"tags":["家世","情缘"],"dims":{"家世":1,"情缘":1},"feedback":"你遣人给娘家送了一桌酒席，附言：「女儿嫁出一年，一切都好。」","source":"归宁通问，见《仪礼》之义。"}],"difficulty":1,"npc":["丫鬟"],"foreshadow":"周年","flavor":true},{"id":"C-116-未","branch":"C","stage":5,"day":116,"shichen":"未时","checkpoint":"周年盘点","scene":"午后你翻开奁册，从「嘉礼」读到「百日」，再到今日。一年的事，一册装不下。","options":[{"text":"补记周年","correct":true,"tags":["才华","自主"],"dims":{"才华":1,"自主":1},"feedback":"你写：「一年。家立，书成，心安。」八个字，一年的重量。","source":"闺中自记，见《琅嬛记》。"},{"text":"与他对数","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"你们对数这一年：吵过两次，笑了三百天，校了一部书，写了一集词。","source":"夫妇话旧，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":null,"flavor":true},{"id":"C-116-戌","branch":"C","stage":5,"day":116,"shichen":"戌时","checkpoint":"周年夜","scene":"夜里他在归来堂设了一小席，只你们两人。他说：「往后每一年，我们都在这里过。」","options":[{"text":"与他立约","correct":true,"tags":["情缘","感情"],"dims":{"情缘":3},"feedback":"「年年岁岁，归来堂见。」这个约，你们举盏为证。","source":"夫妇之约，见《琅嬛记》。"},{"text":"只笑着应了","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"笑是应了。灯花爆了一声，像谁在作证。","source":"闺中情态，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":"归来堂之约","flavor":true},{"id":"C-117","branch":"C","stage":5,"day":117,"shichen":"辰时","checkpoint":"词名更盛","scene":"晨起听闻：《漱玉集》传抄出去了，汴京人人争睹。「词女」之名，如今要改成「词人」了。","options":[{"text":"不骄不躁","correct":true,"tags":["名声","自主"],"dims":{"名声":2,"自主":1},"feedback":"名是名，你是你。你还是那个三更校碑、晨起理账的人。","source":"名与实之辨，见《琅嬛记》。"},{"text":"暗自欢喜","correct":false,"tags":["名声"],"dims":{"名声":2},"feedback":"欢喜是应该的。只是你提醒自己：词名越高，下笔越要稳。","source":"闺中自省，见《琅嬛记》。"}],"difficulty":1,"npc":null,"foreshadow":"词人"},{"id":"C-117-未","branch":"C","stage":5,"day":117,"shichen":"未时","checkpoint":"太学求词","scene":"午后族兄来信：太学诸生设词会，公推你为首座，请「不吝赐题」。","options":[{"text":"题一首寄去","correct":true,"tags":["才华","名声"],"dims":{"才华":2,"名声":1},"feedback":"词到太学，满座无声。族兄回信：「妹妹这首词，替咱们李家把太学压了。」","source":"闺词压太学，见《琅嬛记》。"},{"text":"婉辞不赴","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"辞得体面。可你心里清楚，你的词，早已不需要赴会了。","source":"闺词之誉，见《琅嬛记》。"}],"difficulty":2,"npc":["族兄"],"foreshadow":"词压太学"},{"id":"C-117-戌","branch":"C","stage":5,"day":117,"shichen":"戌时","checkpoint":"灯下论名","scene":"夜里他说：「外头如今都说，赵家娶了个宝。」你笑：「那赵家待宝如何？」","options":[{"text":"等他回答","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"他想了想：「赵家以归来堂待之，以夫妇之实待之，以一辈子待之。」","source":"夫妇之语，见《琅嬛记》。"},{"text":"自己答了","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你道：「赵家待宝如待人，这就够了。」","source":"闺中谐语，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":null},{"id":"C-118","branch":"C","stage":5,"day":118,"shichen":"辰时","checkpoint":"时光静好","scene":"晨起你立在归来堂前，看满架的书、案上的碑、窗外的海棠。你忽然觉得，可以数着日子变老。","options":[{"text":"珍惜眼前","correct":true,"tags":["情缘","自主"],"dims":{"情缘":1,"自主":1},"feedback":"「数着日子变老」——这大概是人间最好的愿景。","source":"闺中自足，见《琅嬛记》。"},{"text":"仍不敢满足","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"不满足也是好的。这样的日子，值得被更用力地过。","source":"闺中自励，见《琅嬛记》。"}],"difficulty":1,"npc":null,"foreshadow":null,"flavor":true},{"id":"C-118-未","branch":"C","stage":5,"day":118,"shichen":"未时","checkpoint":"午后小憩","scene":"午后你在廊下小坐，看丫鬟们扑蝶。你想起及笄那年的自己——也是这样，在满园春色里不知愁。","options":[{"text":"笑看她们玩","correct":true,"tags":["自主","情缘"],"dims":{"自主":1,"情缘":1},"feedback":"你如今是「看」的人了。可看的人心里，也住着那个荡秋千的姑娘。","source":"闺中怀旧，见《琅嬛记》。"},{"text":"也去扑了一只","correct":false,"tags":["自主"],"dims":{"自主":2},"feedback":"丫鬟们又惊又笑：「娘子还会这个！」你拍拍手：「怎么不会。」","source":"闺中谐趣，见《琅嬛记》。"}],"difficulty":1,"npc":["丫鬟"],"foreshadow":null},{"id":"C-118-戌","branch":"C","stage":5,"day":118,"shichen":"戌时","checkpoint":"夜读旧词","scene":"夜里你重读《漱玉集》。读到某阕，忽然停住——那些字句，像一封封从前寄来的信。","options":[{"text":"一封封读下去","correct":true,"tags":["才华","情缘"],"dims":{"才华":1,"情缘":1},"feedback":"你读完了全部的自己。原来你已经走了这么远。","source":"闺词重读，见《琅嬛记》。"},{"text":"读一半不忍读","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"不忍读，是因为太好，也太重。你合上书，心里满满的。","source":"闺中情态，见《琅嬛记》。"}],"difficulty":1,"npc":null,"foreshadow":null},{"id":"C-119","branch":"C","stage":5,"day":119,"shichen":"辰时","checkpoint":"终局前一日","scene":"晨起你忽然意识到：第一百二十日，就在明天。这一年多的路，就要在明日画一个句读。","options":[{"text":"心里平静","correct":true,"tags":["自主","家世"],"dims":{"自主":1,"家世":1},"feedback":"该得的都得了，该立的都立了。你等着明日，像等一盏茶的火候。","source":"闺中自省，见《琅嬛记》。"},{"text":"有些不舍","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"不舍是对的。可你知道，明日的句读之后，是更长的文章。","source":"闺中情思，见《琅嬛记》。"}],"difficulty":1,"npc":null,"foreshadow":"终局前","flavor":true},{"id":"C-119-未","branch":"C","stage":5,"day":119,"shichen":"未时","checkpoint":"家人闲坐","scene":"午后全家都在：婆母在理香烛，他在校书，你在理账。谁也不说话，可这就是最好的时刻。","options":[{"text":"静静享受","correct":true,"tags":["家世","情缘"],"dims":{"家世":1,"情缘":1},"feedback":"「家人闲坐，灯火可亲」——人间至味，不过如此。","source":"闺中之乐，见《琅嬛记》。"},{"text":"去给他添茶","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他抬头一笑。茶添了，话没说。说什么都是多余的。","source":"闺房之情，见《金石录后序》。"}],"difficulty":1,"npc":["夫君","婆母"],"foreshadow":null,"flavor":true},{"id":"C-119-戌","branch":"C","stage":5,"day":119,"shichen":"戌时","checkpoint":"终局前夜","scene":"夜里你立在归来堂中央。两部书在案上，满架金石在架上，而你在灯下。你想：「我是谁？」","options":[{"text":"答我是我自己","correct":true,"tags":["自主","才华"],"dims":{"自主":2,"才华":1},"feedback":"不是李家词女，不是赵家娘子，不是谁的谁——你是你自己。","source":"闺中自觉，见《琅嬛记》。"},{"text":"答我是我们","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"你看着案上的两部书：一部他的，一部你的，合起来，是「我们」。","source":"夫妇一体，见《金石录后序》。"}],"difficulty":1,"npc":null,"foreshadow":"我是谁","flavor":true},{"id":"C-120","branch":"C","stage":5,"day":120,"shichen":"辰时","checkpoint":"第一百二十日","scene":"晨光透过窗纱，落在案头两部书上。你想起及笄那日母亲的话：「日子是一天天短下去的。」可她错了——日子是一天天长出来的。","options":[{"text":"推开窗看天","correct":true,"tags":["自主","情缘"],"dims":{"自主":1,"情缘":1},"feedback":"天光正好。汴京的又一个清晨，你的又一个开始。","source":"闺中晨起，见《琅嬛记》。"},{"text":"研墨备笔","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"今日的词，还没写。今日的碑，还没校。今日，刚刚开始。","source":"著述日课，见《金石录后序》。"}],"difficulty":1,"npc":null,"foreshadow":"终局","flavor":true},{"id":"C-120-未","branch":"C","stage":5,"day":120,"shichen":"未时","checkpoint":"终局·午后","scene":"午后他在案前唤你：「来，坐。」案上摊着那部《金石录》，他翻到最后一页，指着一个空白处。","options":[{"text":"问这是要做什么","correct":true,"tags":["情缘","才华"],"dims":{"情缘":1,"才华":1},"feedback":"他道：「留白。这部书，等一个懂它的人来题跋。那个人，是你。」","source":"题跋之约，见《金石录后序》。"},{"text":"提笔就写","correct":true,"tags":["才华","自主"],"dims":{"才华":2,"自主":1},"feedback":"你提笔写下数行，落款时停了停——「后序」二字，笔重千钧。","source":"金石录后序，见《金石录后序》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":"后序","flavor":true},{"id":"C-120-戌","branch":"C","stage":5,"day":120,"shichen":"戌时","checkpoint":"终局·灯下","scene":"灯下。你和他对坐，案上是《金石录》与《漱玉集》，窗外是汴京的万家灯火。一百二十日，到此了——又才刚刚开始。","options":[{"text":"与他共饮一盏","correct":true,"tags":["情缘","感情"],"dims":{"情缘":3},"feedback":"盏中酒温。他说：「敬你。」你说：「敬我们。」","source":"夫妇之饮，见《琅嬛记》。"},{"text":"把此刻写进词","correct":true,"tags":["才华","情缘","感情"],"dims":{"才华":2,"情缘":1},"feedback":"词成，只有两句：「此情无计可消除，才下眉头，却上心头。」","source":"闺词绝唱，见《琅嬛记》。"}],"difficulty":1,"npc":["夫君"],"foreshadow":"终局","flavor":true,"finale":true,"yishou":true}];
